(function (K) {

K.add('tr-b1-11', {
  lesson: [
    { p: "Im Deutschen erzählst du eine Szene im **Imperfekt** („Es regnete, als ich losging“) und umschreibst Pläne und Pflichten der Vergangenheit: „ich wollte gehen“, „ich hätte gehen sollen“, „früher ging ich immer“. Türkisch hat dafür einen **Baukasten**: Du nimmst eine Zeit, die du schon kennst (**-Iyor, -AcAk, -mAlI, -Ir/-Ar**), und hängst **-(y)DI** („war“) dahinter. Die Person kommt ganz ans Ende, mit den **kurzen Endungen** (-m, -n, –, -k, -nIz, -lAr)." },
    { h: "Der Bauplan: Zeit + -(y)DI + Person" },
    { table: { head: ["Deutsche Konstruktion", "Bauplan", "Beispiel"], rows: [
      ["Es regnete. / Ich war gerade am Kochen. (Szene, Hintergrund)", "Stamm + **-Iyor** + **-DI**", "yağ**ıyordu**, pişir**iyordum**"],
      ["Ich wollte (eigentlich) gehen. (Plan, der nicht klappte)", "Stamm + **-AcAk** + **-tI**", "gid**ecektim**"],
      ["Ich hätte gehen sollen. (verpasste Pflicht)", "Stamm + **-mAlI** + **-ydI**", "git**meliydim**"],
      ["Früher ging ich immer … / pflegte zu gehen (Gewohnheit)", "Stamm + **-Ir/-Ar** + **-dI**", "gid**erdim**"]
    ] } },
    { h: "Alle Personen im Überblick (gelmek)" },
    { table: { head: ["Person", "-Iyor + DI", "-AcAk + DI", "-mAlI + DI", "-Ir + DI"], rows: [
      ["ben", "geliyor**dum**", "gelecek**tim**", "gelmeli**ydim**", "gelir**dim**"],
      ["sen", "geliyor**dun**", "gelecek**tin**", "gelmeli**ydin**", "gelir**din**"],
      ["o", "geliyor**du**", "gelecek**ti**", "gelmeli**ydi**", "gelir**di**"],
      ["biz", "geliyor**duk**", "gelecek**tik**", "gelmeli**ydik**", "gelir**dik**"],
      ["siz", "geliyor**dunuz**", "gelecek**tiniz**", "gelmeli**ydiniz**", "gelir**diniz**"],
      ["onlar", "geliyor**lardı**", "gelecek**lerdi**", "gelmeli**ydiler**", "gelir**lerdi**"]
    ] } },
    { warn: "Typischer Fehler: *„geliyorumdu“*, *„gidecekimdi“*. Die Person hängt **hinter** -DI, nicht davor: geliyor**dum**, gidecek**tim**. Auch die Präsens-Endungen (-(y)Im, -sIn, -(y)Iz) fallen weg – nach -DI gelten nur **-m, -n, –, -k, -nIz, -lAr**." },
    { h: "Die vier Formen im Einzelnen" },
    { p: "**1. -(I)yordu – Hintergrund.** Der Vokal von -(y)DI folgt hier immer dem **o** von -yor: es heißt immer **-yordu/-yordum**, nie -yordı. Die Stammregeln von -Iyor bleiben: *izle-* → izl**iyordu**, *ye-* → y**iyordu**, *de-* → d**iyordu**. Verneinung: gel**miyordum**. Frage: *Uyuyor **muydun**?* – mI steht vor -(y)DI und nimmt die Person mit: muydum, muydun, muydu, muyduk, muydunuz, muydular." },
    { p: "**2. -(y)AcAktI – der Plan, der nicht klappte.** -AcAk endet auf **k**, und k ist stimmlos: Das d von -DI wird zu **t** (gelecek**ti**m). Bei der Zukunft (gelece**ğ**im) wird k zu ğ, hier **nie** – es heißt gelecek**t**im. Nach Vokalstamm kommt der Puffer-y: söyle**y**ecektim. Verneinung: gel**meyecektim**. Frage: *Gelecek **miydin**?*" },
    { p: "**3. -mAlIydI – „hätte sollen“.** -mAlI endet auf Vokal, deshalb der Puffer **y**: gelmeli**y**dim. Der letzte Vokal ist immer ı oder i. Verneinung mit **-mAmAlI**: git**memeli**ydin (du hättest nicht gehen sollen); bei Vokalstamm: ye-**me-meli**ydin." },
    { p: "**4. -(I)rdI – Gewohnheit in der Vergangenheit.** Du bildest den Aorist (gelir, yapar, okur) und hängst -DI an: gelir**di**, yapar**dı**, okur**du**. Einsilbige Verben haben meist **-Ar** (yapardı, giderdi, yazardı). Nur 13 Ausnahmen haben -Ir: *al-, bil-, bul-, dur-, gel-, gör-, kal-, ol-, öl-, san-, var-, ver-, vur-* (gelirdi, alırdı, görürdü, olurdu, kalırdı); mehrsilbige Verben ebenfalls (anlatırdı, okurdu). Verneinung: **-mAzdI** (yemez**dim**, gelmez**di**)." },
    { h: "-DI oder -Iyordu?" },
    { table: { head: ["Form", "Funktion", "Beispiel"], rows: [
      ["-DI", "Ereignis, das **passiert**, die Handlung geht voran", "Telefon **çaldı**. (Das Telefon klingelte.)"],
      ["-Iyordu", "**Hintergrund**, Zustand, was gerade lief", "Ben duş **alıyordum**. (Ich duschte gerade.)"]
    ] } },
    { tip: "-Iyordu kann mit Zeitangaben wie *her yaz* auch Gewohnheiten ausdrücken (*her yaz kalıyorduk*); -(I)rdI ist dafür die typischere Form." },
    { tip: "Merke dir ein Bild: -DI ist der **Film**, der weitergeht, -Iyordu die **Kulisse**. *Eve girdim, annem yemek yapıyordu.* – „Ich kam nach Hause, Mama kochte (gerade).“" },
    { tip: "Der Bau -Ir + DI kann auch „würde“ bedeuten (*Param olsa giderdim*). Das kommt bei den Wenn-Sätzen. Hier geht es nur um „pflegte zu …“." },
    { ex: [
      ["Dışarıda yağmur yağıyordu, biz evde film izliyorduk.", "Draußen regnete es, wir schauten zu Hause einen Film."],
      ["Seni arayacaktım ama telefonum kapalıydı.", "Ich wollte dich anrufen, aber mein Telefon war aus."],
      ["Daha erken yola çıkmalıydık.", "Wir hätten früher losfahren sollen."],
      ["Çocukken her yaz dedemlerde kalırdık.", "Als Kinder blieben wir jeden Sommer bei meinen Großeltern."],
      ["Eskiden sebze yemezdim, şimdi çok seviyorum.", "Früher aß ich kein Gemüse, jetzt mag ich es sehr."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-11.1", t: "gap", q: "Telefon çaldı, ama ben duş ___ . (almak – Das Telefon klingelte, aber ich duschte gerade.)", a: ["alıyordum"],
      wrong: { "alıyorum": "Das ist Präsens. Die Szene liegt in der Vergangenheit: -Iyor + **-DI**.", "alıyordu": "*alıyordu* = er/sie duschte. „ich“ → **-m** am Ende: alıyordum.", "alıyorumdu": "Die Person steht hinter -DI: alıyor**dum**, nicht alıyorum-du.", "aldım": "-DI allein meldet ein Ereignis (ich duschte, fertig). „Gerade dabei“ braucht -Iyordu.", "alırdım": "Das wäre eine Gewohnheit („ich duschte immer“). Hier läuft eine einzelne Szene." },
      e: "al- + **ıyor** (Vokal a → ı) + **dum** (nach -yor immer -du) + m = **alıyordum**. Das Telefon klingelt (Ereignis, -DI), im Hintergrund läuft die Dusche (-Iyordu)." },
    { id: "tr-b1-11.2", t: "gap", q: "Dün akşam saat dokuzda uyuyor ___ ? (Hast du gestern Abend um neun geschlafen?)", a: ["muydun"],
      wrong: { "mıydın": "Letzter Vokal von *uyuyor* ist **o** → mI wird zu **mu**.", "musun": "Das ist die Präsens-Frage. Für die Vergangenheit steht hinter mI noch -(y)DI: mu**ydun**.", "muydu": "*muydu* = hat er/sie geschlafen? „du“ → **-n**: muydun.", "muyordun": "-Iyor steckt schon im Verb. Hinter mI kommt nur noch -(y)DI + Person." },
      e: "uyuyor + **mu** + **y** (Puffer) + **dun** = **uyuyor muydun**. mI wird getrennt geschrieben und trägt -(y)DI und die Person." },
    { id: "tr-b1-11.3", t: "gap", q: "Hafta sonu denize ___ , ama hava çok kötüydü. (gitmek – Am Wochenende wollten wir ans Meer fahren, aber das Wetter war schlecht.)", a: ["gidecektik"],
      wrong: { "gideceğiz": "Das ist Zukunft („wir werden fahren“). Für „wir wollten“ brauchst du -AcAk + **-tI**: gidecek**tik**.", "gidecekdik": "*-AcAk* endet auf **k** (stimmlos) → d wird **t**: gidecek**t**ik.", "gideceğik": "Das ğ gehört nur zur Zukunft mit Vokal danach. Vor -tI bleibt **k**.", "gidiyorduk": "Das hieße „wir fuhren gerade“. Hier ging es um einen **Plan**." },
      e: "git- (t → d vor Vokal) + **ecek** + **ti** + **k** = **gidecektik**. -(y)AcAktI sagt: Das war so geplant – und dann kam etwas dazwischen." },
    { id: "tr-b1-11.4", t: "gap", q: "Sana yarın ___ . (söylemek – Ich wollte es dir morgen sagen.)", a: ["söyleyecektim"],
      wrong: { "söylecektim": "*söyle-* endet auf Vokal → Puffer-**y**: söyle**y**ecektim.", "söyleyeceğim": "Das ist Zukunft („ich werde sagen“). Für „ich wollte“: -AcAk + **-tI** + m.", "söyleyecektım": "Letzter Vokal von *-ecek* ist e → -t**i**m (mit Punkt).", "söyledim": "Das ist -DI: „ich habe gesagt“. Ein Plan braucht -AcAktI." },
      e: "söyle- + **y** + **ecek** + **ti** + **m** = **söyleyecektim**. Die Person steht hinter -tI, kurz: -m." },
    { id: "tr-b1-11.5", t: "gap", q: "Daha erken ___ . (kalkmak – Ich hätte früher aufstehen sollen.)", a: ["kalkmalıydım"],
      wrong: { "kalkmalıyım": "Das ist Präsens: „ich muss aufstehen“. „Hätte sollen“ → -mAlI + **-ydI**.", "kalkmalıydim": "Letzter Vokal ist **ı** → -yd**ı**m ohne Punkt.", "kalkmalıydı": "*kalkmalıydı* = er/sie hätte aufstehen sollen. „ich“ → **-m**.", "kalkmalıdım": "Nach -mAlI (Vokal) braucht -DI den Puffer **y**: kalkmalı**y**dım." },
      e: "kalk- + **malı** + **y** + **dı** + **m** = **kalkmalıydım**. Türkisch hat dafür kein Hilfsverb wie „sollen“: Es ist alles in einem Wort." },
    { id: "tr-b1-11.6", t: "gap", q: "Çocukken her yaz dedemlerde ___ . (kalmak – Als Kinder blieben wir jeden Sommer bei den Großeltern.)", a: ["kalırdık", "kalıyorduk"],
      wrong: { "kalırdım": "*kalırdım* = ich pflegte zu bleiben. Hier sind „wir“ gemeint → **-k**.", "kalardık": "*kalmak* gehört zu den 13 einsilbigen Ausnahmen mit **-Ir**: kalır, nicht kalar.", "kalırdik": "Letzter Vokal ist **ı** → -d**ı**k ohne Punkt.", "kalırız": "Das ist Präsens. „Als Kinder“ liegt in der Vergangenheit: -Ir + **-dI**." },
      e: "kal- + **ır** + **dı** + **k** = **kalırdık**. „Jeden Sommer“ = wiederholte Handlung → -(I)rdI. Auch *kalıyorduk* ist richtig: -Iyordu kann mit Zeitangaben wie *her yaz* Gewohnheiten ausdrücken, -(I)rdI ist hier die typischere Form." },
    { id: "tr-b1-11.7", t: "mc", q: "Ben eve girdim, annem mutfakta yemek ___ .", o: ["yapıyordu", "yaptı", "yapacaktı", "yapardı"], a: 0,
      why: { 1: "-DI würde heißen: Sie kochte danach fertig – eine zweite Handlung. Gemeint ist die **Kulisse**.", 2: "-AcAktI = sie wollte kochen (hatte es vor).", 3: "-(I)rdI = sie pflegte zu kochen (Gewohnheit)." },
      e: "Ich komme herein (Ereignis, -DI), Mama steht am Herd (Hintergrund, **-Iyordu**)." },
    { id: "tr-b1-11.8", t: "mc", q: "„Ich hätte dich anrufen sollen.“", o: ["Seni aramalıydım.", "Seni arıyordum.", "Seni arayacaktım.", "Seni ararım."], a: 0,
      why: { 1: "*arıyordum* = ich rief gerade an / ich war am Anrufen.", 2: "*arayacaktım* = ich wollte dich anrufen (Plan, aber keine Pflicht).", 3: "*ararım* = ich rufe an (Aorist, Präsens)." },
      e: "Pflicht, die in der Vergangenheit nicht erfüllt wurde = **-mAlIydI**: ara-malı-y-dı-m." },
    { id: "tr-b1-11.9", t: "mc", q: "„Eigentlich wollte ich Pizza bestellen.“", o: ["Aslında pizza sipariş edecektim.", "Aslında pizza sipariş ediyordum.", "Aslında pizza sipariş etmeliydim.", "Aslında pizza sipariş ederdim."], a: 0,
      why: { 1: "*ediyordum* = ich war gerade dabei zu bestellen.", 2: "*etmeliydim* = ich hätte bestellen sollen.", 3: "*ederdim* = ich pflegte zu bestellen." },
      e: "„Eigentlich wollte ich …“ = Plan in der Vergangenheit = **-(y)AcAktI**. *aslında* = eigentlich." },
    { id: "tr-b1-11.10", t: "mc", q: "„Früher ging mein Vater jeden Morgen zu Fuß zur Arbeit.“", o: ["Eskiden babam her sabah işe yürüyerek giderdi.", "Eskiden babam her sabah işe yürüyerek gitti.", "Eskiden babam her sabah işe yürüyerek gidecekti.", "Eskiden babam her sabah işe yürüyerek gitmeliydi."], a: 0,
      why: { 1: "-DI meldet ein **einmaliges** Ereignis. „Jeden Morgen“ ist wiederholt.", 2: "-AcAktI = er wollte gehen (Plan).", 3: "-mAlIydI = er hätte gehen sollen." },
      e: "Wiederholte Handlung früher = **-(I)rdI**: git → gid**er** + **di**." },
    { id: "tr-b1-11.11", t: "mc", q: "„Wir aßen gerade.“", o: ["Yemek yiyorduk.", "Yemek yiyoruzdu.", "Yemek yiyorumduk.", "Yemek yiyordık."], a: 0,
      why: { 1: "-uz ist die Präsens-Endung. Nach -DI gilt die kurze Endung **-k**.", 2: "Die Person darf nur **einmal** stehen, und zwar hinten.", 3: "Nach -yor steht immer **-du** (o → u), nicht -dı." },
      e: "yi- (ye- → yi- vor -yor) + **yor** + **du** + **k** = **yiyorduk**." },
    { id: "tr-b1-11.12", t: "mc", q: "„Du hättest nicht gehen sollen.“", o: ["Gitmemeliydin.", "Gitmeliydin.", "Gitmeyecektin.", "Gitmiyordun."], a: 0,
      why: { 1: "*gitmeliydin* = du hättest gehen sollen – das Gegenteil.", 2: "*gitmeyecektin* = du wolltest nicht gehen.", 3: "*gitmiyordun* = du gingst nicht (gerade)." },
      e: "Verneinte Pflicht: **-mAmAlI** + -ydI: git-me-meli-ydi-n. Zweimal „me“ – einmal für die Verneinung, einmal im Suffix -mAlI." },
    { id: "tr-b1-11.13", t: "order", q: "Bilde den Satz: „Gestern Abend wollten wir ins Kino gehen.“", w: ["gidecektik", "Dün", "sinemaya", "akşam"], a: ["Dün akşam sinemaya gidecektik", "Sinemaya dün akşam gidecektik"],
      e: "Zeit – Ort – **Verb am Ende**. Das Verb trägt Plan (-AcAk), Vergangenheit (-tI) und Person (-k) in einem Wort." },
    { id: "tr-b1-11.14", t: "order", q: "Bilde den Satz: „Du hättest früher losfahren sollen.“", w: ["çıkmalıydın", "erken", "Daha", "yola"], a: ["Daha erken yola çıkmalıydın", "Yola daha erken çıkmalıydın"],
      e: "*yola çıkmak* = losfahren. -mAlIydI + **-n** (du) steht ganz am Ende." },
    { id: "tr-b1-11.15", t: "order", q: "Bilde den Satz: „Als wir Kinder waren, erzählte uns meine Oma Märchen.“", w: ["babaannem", "Biz", "çocukken", "anlatırdı", "masal", "bize"], a: ["Biz çocukken babaannem bize masal anlatırdı", "Biz çocukken bize babaannem masal anlatırdı"],
      e: "„Als wir Kinder waren“ = *biz çocukken*. Die Gewohnheit steckt in **anlat-ır-dı**. *masal* steht ohne Akkusativ, weil es unbestimmt ist (irgendwelche Märchen)." },
    { id: "tr-b1-11.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["yağıyordu", "es regnete (gerade)"], ["gidecektim", "ich wollte gehen"], ["gitmeliydim", "ich hätte gehen sollen"], ["giderdim", "ich ging früher immer"], ["gitmezdim", "ich ging früher nie"]],
      e: "-Iyordu = Kulisse, -AcAktI = Plan, -mAlIydI = verpasste Pflicht, -(I)rdI = Gewohnheit, -mAzdI = verneinte Gewohnheit." },
    {"id":"tr-b1-11.17","t":"cloze","q":"Ergänze die Verbformen.","text":"Dün akşam eve geldim. Annem telefonda konuş{1}. Babam salonda televizyon izli{2}. Ben aslında erken gel{3}, ama otobüsü kaçırdım.","gaps":{"1":{"a":["uyordu"],"wrong":{"uyorum":"„Ich“ passt nicht – es geht um die Mutter, und die Vergangenheit braucht -DI: konuşuyor**du**.","ıyordu":"Letzter Vokal von *konuş-* ist **u** → **-uyor**: konuşuyordu.","udu":"Ohne -yor wäre es nur -DI. Die Szene läuft gerade: konuş**uyor**du."}},"2":{"a":["yordu"],"wrong":{"iyordu":"*izle-* wird vor -yor zu *izli-*; das i steht schon im Text: izli**yordu**.","ordu":"Nach dem i fehlt das **y** von -yor: izli-**yor**-du.","yorlardı":"Hier ist nur eine Person gemeint („Babam“): -yordu."}},"3":{"a":["ecektim"],"wrong":{"eceğim":"Das ist Zukunft. Für „ich wollte“: -AcAk + **-tI**.","ecektım":"Letzter Vokal von -ecek ist e → -t**i**m.","ecektik":"*Ben* verlangt „ich“ → **-m**, nicht -k."}}},"e":"Zwei Szenen im Hintergrund (-Iyordu): Mama telefoniert, Papa schaut fern. Dazu ein Plan, der nicht klappte (-AcAktI). Die Person steht immer hinten und ist kurz."},
    {"id":"tr-b1-11.18","t":"sort","q":"Ereignis oder Hintergrund? Ordne die Sätze zu.","cats":["Ereignis (-DI)","Hintergrund (-Iyordu)"],"items":[["Telefon çaldı.",0],["Annem mutfakta çalışıyordu.",1],["Kapı açıldı.",0],["Dışarıda kar yağıyordu.",1],["Eve girdim.",0],["Çocuklar bahçede oynuyordu.",1]],"why":{"Telefon çaldı.":"Das Klingeln ist ein Moment, der die Handlung vorantreibt: -DI.","Annem mutfakta çalışıyordu.":"Ein Zustand, der schon lief: Kulisse mit -Iyordu.","Kapı açıldı.":"Ein einzelnes Ereignis (-DI).","Dışarıda kar yağıyordu.":"Wetter ist der klassische Hintergrund: -Iyordu.","Eve girdim.":"Eine abgeschlossene Handlung (-DI).","Çocuklar bahçede oynuyordu.":"Eine laufende Szene: -Iyordu."},"e":"-DI schiebt die Geschichte weiter (was passierte), -Iyordu beschreibt, was dabei im Hintergrund lief."},
    { id: "tr-b1-11.19", t: "listen", say: "Eve geldim, çocuklar salonda oynuyordu ve ben çok yorgundum.", q: "Hör zu: Was taten die Kinder, als die Person nach Hause kam?",
      o: ["Sie spielten im Wohnzimmer.", "Sie schliefen schon.", "Sie waren noch in der Schule.", "Sie kamen später nach Hause."], a: 0,
      why: { 1: "*oynuyordu* heißt „spielten“, nicht „schliefen“ (*uyuyordu*).", 2: "*salonda* = im Wohnzimmer, also zu Hause.", 3: "Die Kinder waren schon da: *salonda oynuyordu*." },
      e: "„Ich kam nach Hause, die Kinder spielten im Wohnzimmer, und ich war sehr müde.“ Ereignis: *geldim* (-DI), Kulisse: *oynuyordu*, Zustand: *yorgundum* (-(y)DI)." },
    { id: "tr-b1-11.20", t: "dictation", say: "Dün akşam dışarı çıkacaktık ama yağmur yağıyordu.", a: ["Dün akşam dışarı çıkacaktık ama yağmur yağıyordu."],
      wrong: { "Dün akşam dışarı çıkacaktik ama yağmur yağıyordu.": "Letzter Vokal von *çıkacak-* ist **a** → -t**ı**k ohne Punkt.", "Dün akşam dışarı çıkacaktık ama yağmur yağıyordı.": "Nach -yor steht immer **-du**: yağıyor**du**.", "Dün akşam dışarı çıkacağtık ama yağmur yağıyordu.": "Vor -tI bleibt das k: çıkacak**t**ık, kein ğ." },
      e: "„Gestern Abend wollten wir ausgehen, aber es regnete.“ Plan (-AcAktI) und Kulisse (-Iyordu) in einem Satz." },
    { id: "tr-b1-11.21", t: "speak", say: "Ben eve girdim, annem mutfakta yemek yapıyordu.",
      e: "„Ich kam nach Hause, meine Mutter kochte gerade.“ In *yapıyordu* alle ı dumpf, ohne Punkt; das ğ gibt es hier nicht. *mutfak* betont auf der letzten Silbe: mut-FAK. Typischer Fehler: *yapıyordu* mit deutschem „ü“ in der Mitte." },
    { id: "tr-b1-11.22", t: "speak", say: "Dün seni arayacaktım ama telefonum kapalıydı.",
      e: "„Gestern wollte ich dich anrufen, aber mein Telefon war aus.“ *arayacaktım*: a-ra-ya-cak-tım; c wie das „dsch“ in „Dschungel“, nicht wie „k“. Das k und das t in *-cak-tım* deutlich nacheinander sprechen. *kapalıydı* mit dumpfem ı." },
    { id: "tr-b1-11.23", t: "speak", say: "Çocukken her yaz dedemlerde kalırdık.",
      e: "„Als Kinder blieben wir jeden Sommer bei den Großeltern.“ *dedemlerde* = bei meinem Opa und seiner Familie (-lAr als „und Co.“). *kalırdık*: alle ı dumpf, Betonung auf kaLIRdık. Typischer Fehler: *kalirdik* mit deutschem i." },
    { id: "tr-b1-11.24", t: "respond", say: "Çocukken hafta sonları ne yapardın?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -(I)rdI für Gewohnheiten und -Iyordu für eine Szene.",
      chunks: ["Çocukken hafta sonları …", "Genellikle …", "Bazen …", "O zamanlar …"],
      models: ["Çocukken hafta sonları babaannemlere giderdik. Genellikle bahçede oynardık, babaannem de mutfakta yemek yapıyordu. Akşamları masal dinlerdik.", "Çocukken hafta sonları arkadaşlarımla futbol oynardım. Bazen annem bizi parka götürürdü. O zamanlar hiç sıkılmazdık."],
      modelsN: ["Als Kind fuhren wir am Wochenende zu meiner Oma. Meistens spielten wir im Garten, und Oma kochte in der Küche. Abends hörten wir Märchen.", "Als Kind spielte ich am Wochenende mit meinen Freunden Fußball. Manchmal nahm uns meine Mutter mit in den Park. Damals langweilten wir uns nie."],
      e: "Gewohnheiten aus der Kindheit stehen im Türkischen mit **-(I)rdI**: gid**erdik**, oyna**rdık**, götür**ürdü**. Verneint: sıkıl**mazdık**. Eine laufende Szene („Oma kochte dabei“) bekommt -Iyordu. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-01', {
  lesson: [
    { p: "Aus A2 kennst du **-mIş** für Dinge, die du **nicht selbst erlebt** hast („er soll gekommen sein“). Jetzt kommen drei Erweiterungen: **-mIştI** (etwas war **schon passiert**, als etwas anderes geschah), die **Überraschung** („Ach, es hat geschneit!“) und **-(y)mIş am Nomen** („er ist wohl krank“). Im Deutschen brauchst du dafür Plusquamperfekt, „offenbar“, „angeblich“ oder „soll“ – Türkisch hat überall **-mIş**." },
    { h: "Vorzeitigkeit: -mIş + -DI" },
    { p: "Wie bei den zusammengesetzten Zeiten hängst du an **-mIş** ein **-(y)DI**. Wieder gelten die kurzen Endungen. Das ist ein großer Unterschied zu -mIş **allein**, das die Präsens-Endungen trägt." },
    { table: { head: ["Person", "-mIş allein (Gerücht, Überraschung)", "-mIştI (Plusquamperfekt)"], rows: [
      ["ben", "gel**mişim**", "gel**miştim**"],
      ["sen", "gel**mişsin**", "gel**miştin**"],
      ["o", "gel**miş**", "gel**mişti**"],
      ["biz", "gel**mişiz**", "gel**miştik**"],
      ["siz", "gel**mişsiniz**", "gel**miştiniz**"],
      ["onlar", "gel**mişler**", "gel**mişlerdi**"]
    ] } },
    { p: "Vokalharmonie wie bei -DI: ı/i/u/ü (almış, gelmiş, olmuş, görmüş). Das ş bleibt immer ş. Nach -mIş wird d zu t, weil ş stimmlos ist: -mIş**tı**, nicht -mışdı. Verneinung mit -mA- davor: gel**memişti**. Frage: *Gelmiş **miydi**?* (War er schon gekommen?)" },
    { table: { head: ["Deutsch", "Bauplan", "Beispiel"], rows: [
      ["Als ich kam, war der Film schon zu Ende.", "-mIş + -(y)DI", "Ben gelince film çoktan bit**mişti**."],
      ["Er hatte die Mail nicht gelesen.", "-mA- + -mIş + -DI", "E-postayı oku**mamıştı**."]
    ] } },
    { warn: "-DI meldet einfach „es passierte“. Wenn zwei Dinge nacheinander passiert sind und du zeigen willst, was **zuerst** war, nimmst du für das frühere **-mIştI**: *Eve geldim, çocuklar yatmıştı.* (Ich kam heim, die Kinder lagen schon im Bett.)" },
    { h: "Überraschung: Du entdeckst etwas neu" },
    { p: "Auch wenn du **selbst** etwas siehst, aber den Vorgang nicht miterlebt hast, nimmst du **-mIş**: *Aa, bütün gece kar yağmış!* (Ach, es hat die ganze Nacht geschneit!) Du schließt aus dem Ergebnis (weißer Boden) auf das, was war. Dazu passt das Wort **meğer** („wie sich herausstellt“): *Meğer komşumuz taşınmış.*" },
    { tip: "Faustregel: Hast du die Handlung **gesehen/gemacht**, nimmst du **-DI**. Siehst du nur das **Ergebnis**, hörst du es von anderen, oder bist du überrascht, nimmst du **-mIş**." },
    { h: "-(y)mIş am Nomen und Adjektiv" },
    { p: "Bei Nomen, Adjektiven und Orten ist -mIş die Vergangenheit/Gerüchte-Form von „sein“. Nach **Vokal** steht der Puffer-**y**, nach Konsonant nicht. Vokalharmonie ı/i/u/ü." },
    { table: { head: ["Wort", "-(y)mIş", "Bedeutung"], rows: [
      ["hasta", "hasta**ymış**", "(Er/Sie) ist wohl/soll krank sein"],
      ["evde", "evde**ymiş**", "(Er/Sie) ist angeblich zu Hause"],
      ["yorgun", "yorgun**muş**", "(Er/Sie) ist offenbar müde"],
      ["güzel", "güzel**miş**", "(Es) ist wohl schön"],
      ["var / yok", "var**mış** / yok**muş**", "es gibt (offenbar) / es gibt (offenbar) nicht"]
    ] } },
    { p: "Mit Personalendung (Präsens-Typ): *hastaymışım* (ich bin offenbar krank), *hastaymışsın*, *hastaymış*, *hastaymışız*, *hastaymışsınız*, *hastaymışlar*. Der Vergleich: *evdeydi* (er war zu Hause, das weißt du sicher) – *evdeymiş* (er ist/war angeblich zu Hause)." },
    { tip: "**Meğer ben çok yorgunmuşum.** – „Ich war offenbar sehr müde.“ Hier entdeckst du etwas über **dich selbst**, was du vorher nicht gemerkt hast (nach dem Schlaf, nach einem Fehler). Das ist im Deutschen schwer wiederzugeben, im Türkischen ganz normal." },
    { tip: "Märchen beginnen mit *Bir varmış, bir yokmuş …* – „Es war einmal …“. Der Erzähler hat die Geschichte nicht selbst erlebt, nur überliefert bekommen: Dafür ist -mIş da." },
    { ex: [
      ["Biz sinemaya vardık, ama film çoktan başlamıştı.", "Wir kamen im Kino an, aber der Film hatte schon begonnen."],
      ["Aa, bak, bütün gece kar yağmış!", "Ach, schau, es hat die ganze Nacht geschneit!"],
      ["Meğer komşumuz çoktan taşınmış.", "Wie sich herausstellt, ist unser Nachbar längst umgezogen."],
      ["Doktor bugün yokmuş.", "Der Arzt ist heute wohl nicht da."],
      ["Kardeşim çok yorgunmuş, erken yatmış.", "Meine Schwester/mein Bruder ist wohl sehr müde, er/sie ist früh ins Bett gegangen."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-01.1", t: "gap", q: "Sen gelince ben çoktan yemek ___ . (yemek – Als du kamst, hatte ich schon gegessen.)", a: ["yemiştim"],
      wrong: { "yemiştum": "Letzter Vokal von *yemiş-* ist **i** → -t**i**m mit Punkt.", "yemişim": "Das ist -mIş allein („ich habe offenbar gegessen“). Für „hatte“ kommt -DI dazu: -miş**ti**m.", "yemişdim": "*ş* ist stimmlos → d wird **t**: -miş**t**im.", "yemiştin": "-n ist „du“. „Ich“ endet auf **-m**." },
      e: "ye- + **miş** + **ti** + **m** = **yemiştim**. Das Essen war zuerst da, dann kamst du: -mIştI drückt die Vorzeitigkeit aus." },
    { id: "tr-b1-01.2", t: "gap", q: "Sabah pencereden baktım, vay canına, bütün gece kar ___ ! (yağmak – Ich sah morgens aus dem Fenster: Wow, es hat die ganze Nacht geschneit! Du entdeckst es gerade.)", a: ["yağmış"],
      wrong: { "yağmuş": "Letzter Vokal von *yağ-* ist **a** → -m**ı**ş.", "yağmıs": "Das Suffix schreibt man mit **ş**: -mış.", "yağıyor": "Das ist Präsens: es schneit jetzt. Du siehst das Ergebnis → -mIş.", "yağmıştım": "Das hieße „ich hatte geschneit“ – der Schnee, nicht du, ist das Subjekt." },
      e: "yağ- + **mış**. Du hast den Schneefall nicht miterlebt, siehst nur das Ergebnis und bist überrascht: das ist die typische Situation für -mIş." },
    { id: "tr-b1-01.3", t: "gap", q: "Duydum ki Ali evde___ . (Ich habe gehört, dass Ali zu Hause ist.)", a: ["ymiş"],
      wrong: { "miş": "*evde* endet auf einen Vokal → Puffer-**y**: evde**y**miş.", "ymış": "Letzter Vokal von *evde* ist **e** → -y**mi**ş mit Punkt.", "ydi": "*evdeydi* = er war zu Hause (sicheres Wissen). Hier heißt es „ich habe es gehört“." },
      e: "evde + **y** + **miş** = **evdeymiş**. Nach Vokal steht der Puffer-y, danach folgt die Vokalharmonie." },
    { id: "tr-b1-01.4", t: "gap", q: "Kardeşim çok yorgun___ , erken yatmış. (Mein Bruder ist wohl sehr müde, er ist früh schlafen gegangen.)", a: ["muş"],
      wrong: { "ymuş": "*yorgun* endet auf **n**, einen Konsonanten – kein Puffer-y nötig: yorgun**muş**.", "miş": "Letzter Vokal von *yorgun* ist **u** → -**muş**.", "muşsun": "-sun ist „du“. Hier geht es um den Bruder („er/sie“): keine Endung." },
      e: "yorgun + **muş**. Nach Konsonant kommt -mIş direkt hinter das Wort, der Vokal folgt der Harmonie (u → muş)." },
    { id: "tr-b1-01.5", t: "gap", q: "Meğer ben çok yorgun___ . (Ich war offenbar sehr müde – das merke ich erst jetzt.)", a: ["muşum"],
      wrong: { "muşsun": "-sun ist „du“. „Ich“ → **-um** (Präsens-Typ nach -mIş).", "mışım": "Letzter Vokal von *yorgun* ist **u** → -muşum.", "muştum": "-mIş**tI** würde „ich war müde gewesen“ heißen (Vorzeitigkeit). Hier entdeckst du es neu: nur -mIş + **-Im**." },
      e: "yorgun + **muş** + **um** = **yorgunmuşum**. Mit *meğer* zeigt das, dass du selbst etwas über dich entdeckt hast." },
    { id: "tr-b1-01.6", t: "gap", q: "Biz sinemaya vardık, ama film çoktan başla___ . (… aber der Film hatte schon begonnen.)", a: ["mıştı"],
      wrong: { "mıştık": "-k = „wir“. Subjekt ist der Film („er/sie/es“): keine Endung nach -tI.", "mışdı": "*ş* ist stimmlos → d wird **t**: -mış**tı**.", "mıyordu": "Das hieße „der Film begann gerade“. Du willst sagen: Er hatte **schon** begonnen." },
      e: "başla- + **mış** + **tı** = **başlamıştı**. Zuerst begann der Film, dann kamt ihr: Vorzeitigkeit." },
    { id: "tr-b1-01.7", t: "mc", q: "Eine Freundin sagt: „Ayşe evlenmiş.“ Was bedeutet das?", o: ["Ayşe hat geheiratet – so habe ich es erfahren.", "Ayşe wird heiraten.", "Ayşe heiratet gerade.", "Ich war bei Ayşes Hochzeit dabei."], a: 0,
      why: { 1: "Zukunft hieße *evlenecek*.", 2: "Gegenwart hieße *evleniyor*.", 3: "Wer dabei war, sagt *evlendi* (-DI = selbst erlebt)." },
      e: "-mIş kennzeichnet Informationen aus zweiter Hand oder Schlüsse aus dem Ergebnis." },
    { id: "tr-b1-01.8", t: "mc", q: "„Als wir kamen, hatte Mama das Essen schon vorbereitet.“", o: ["Biz gelince annem yemeği hazırlamıştı.", "Biz gelince annem yemeği hazırlıyordu.", "Biz gelince annem yemeği hazırlamıştım.", "Biz gelince annem yemeği hazırlayacaktı."], a: 0,
      why: { 1: "*hazırlıyordu* = Mama war gerade beim Vorbereiten, es war noch nicht fertig.", 2: "*-tım* = „ich“. Das Subjekt ist Mama → -tı.", 3: "*hazırlayacaktı* = sie wollte es vorbereiten." },
      e: "Das Vorbereiten war **vor** dem Kommen abgeschlossen: -mIştI. Das Subjekt „annem“ verlangt die Form ohne Personalendung." },
    { id: "tr-b1-01.9", t: "mc", q: "„Wir hatten schon bezahlt.“", o: ["Ödemiştik.", "Ödemiştiyiz.", "Ödemişiz.", "Ödemiştük."], a: 0,
      why: { 1: "Nach -tI heißt „wir“ nur **-k**, nicht -(y)Iz.", 2: "*ödemişiz* = wir haben offenbar bezahlt (Gerücht-Form ohne -DI).", 3: "Der letzte Vokal ist i (ö-de-**miş**-ti), also -tik, nicht -tük." },
      e: "öde- + **miş** + **ti** + **k** = **ödemiştik**." },
    { id: "tr-b1-01.10", t: "mc", q: "„Er hatte die E-Mail nicht gelesen.“", o: ["E-postayı okumamıştı.", "E-postayı okumamış.", "E-postayı okumamışdı.", "E-postayı okumayacaktı."], a: 0,
      why: { 1: "*okumamış* = er hat sie offenbar nicht gelesen. Ohne -tI fehlt die Vorzeitigkeit „hatte“.", 2: "Nach ş wird d zu **t**: okumamış**tı**.", 3: "*okumayacaktı* = er wollte sie nicht lesen (Plan)." },
      e: "oku- + **ma** + **mış** + **tı**: Verneinung -mA- vor -mIş, dann -tI. Vokalharmonie: ma (u) und mış (a)." },
    { id: "tr-b1-01.11", t: "mc", q: "„Laut Ayşe ist Ali zu Hause.“", o: ["Ali evdeymiş.", "Ali evdemiş.", "Ali evdeydi.", "Ali evdeyimiş."], a: 0,
      why: { 1: "Nach Vokal (e) steht der Puffer-**y**: evde**y**miş.", 2: "*evdeydi* = er war zu Hause (selbst gesehen). Du gibst hier wieder, was du gehört hast.", 3: "Diese Form gibt es nicht. Lang: evde imiş, kurz: evdeymiş." },
      e: "evde + **y** + **miş**. Ohne Personalendung für die 3. Person." },
    { id: "tr-b1-01.12", t: "mc", q: "Warum beginnen Märchen mit *Bir varmış, bir yokmuş …*?", o: ["Weil der Erzähler die Geschichte nicht selbst erlebt, sondern überliefert hat.", "Weil Märchen in der Zukunft spielen.", "Weil -mIş „sehr alt“ bedeutet.", "Weil Märchen immer Gegenwart sind."], a: 0,
      why: { 1: "Zukunft hieße *-AcAk* (*olacak*).", 2: "-mIş bedeutet nicht „alt“, sondern „nicht selbst erlebt“.", 3: "Märchen sind Erzählungen aus der Vergangenheit." },
      e: "-mIş = Überliefertes: Der Erzähler hat es gehört, nicht gesehen. Darum beginnt jedes Märchen so." },
    { id: "tr-b1-01.13", t: "order", q: "Bilde den Satz: „Als ich ankam, war der Film schon zu Ende.“", w: ["Ben", "gelince", "film", "çoktan", "bitmişti"], a: ["Ben gelince film çoktan bitmişti", "Ben gelince çoktan film bitmişti", "Film ben gelince çoktan bitmişti"],
      e: "Nebensatz *Ben gelince* („wenn/als ich kam“) – dann Hauptsatz. -mIştI steht am Ende und zeigt: Das Ende des Films war schon vorbei." },
    { id: "tr-b1-01.14", t: "order", q: "Bilde den Satz: „Wie sich herausstellt, ist unser Nachbar längst umgezogen.“", w: ["Meğer", "komşumuz", "çoktan", "taşınmış"], a: ["Meğer komşumuz çoktan taşınmış"],
      e: "*Meğer* steht am Satzanfang und kündigt die Überraschung an. Das Verb mit -mIş bildet das Ende." },
    { id: "tr-b1-01.15", t: "order", q: "Bilde den Satz: „Der Arzt ist heute wohl nicht da.“", w: ["yokmuş", "bugün", "Doktor"], a: ["Doktor bugün yokmuş", "Bugün doktor yokmuş"],
      e: "*yok* (nicht da, nicht vorhanden) + **muş** (Vokal o → u). Kein Verb im Satz, -mIş hängt am Nomen." },
    { id: "tr-b1-01.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["gelmişti", "er/sie war schon gekommen"], ["gelmiş", "er/sie ist offenbar gekommen"], ["gelmiş miydi", "war er/sie schon gekommen?"], ["gelmemişti", "er/sie war noch nicht gekommen"], ["gelmemiş", "er/sie ist offenbar nicht gekommen"]],
      e: "Mit **-DI** hinten: Vorzeitigkeit („war“). Ohne -DI: Gerücht oder Entdeckung. Die Verneinung -mA- steht vor -mIş." },
    {"id":"tr-b1-01.17","t":"cloze","q":"Ergänze das Märchen.","text":"Bir köyde yaşlı bir kadın yaşa{1}. Kadının çok güzel bir bahçesi var{2}. Bir gün bahçede altın bir elma bul{3}.","gaps":{"1":{"a":["mış"],"wrong":{"ymış":"-mIş beginnt mit Konsonant: Der Puffer-y ist nur nötig, wenn ein Vokal folgt. Also yaşa**mış**.","mıştı":"-mIştI würde „hatte gelebt“ heißen. Das Märchen beginnt mit der einfachen überlieferten Form.","miş":"Letzter Vokal von *yaşa-* ist **a** → -m**ı**ş."}},"2":{"a":["mış"],"wrong":{"muş":"Letzter Vokal von *var* ist **a** → -m**ı**ş.","ymış":"*var* endet auf Konsonant r → kein Puffer-y: var**mış**.","mıştı":"Das Märchen erzählt in -mIş ohne -DI."}},"3":{"a":["muş"],"wrong":{"mış":"Letzter Vokal von *bul-* ist **u** → -m**u**ş.","muştu":"Ohne -DI: Märchen stehen in -mIş.","du":"-DI würde sagen, dass der Erzähler es selbst gesehen hat. Märchen sind überliefert: -mIş."}}},"e":"Märchen werden in -mIş erzählt, weil sie überliefert sind. Alle drei Verben: yaşa**mış**, var**mış**, bul**muş**. Die Vokalharmonie entscheidet: a → ı (yaşamış, varmış), u → u (bulmuş)."},
    {"id":"tr-b1-01.18","t":"sort","q":"Selbst erlebt oder nur gehört/entdeckt? Ordne die Situationen zu.","cats":["-DI (selbst erlebt)","-mIş (gehört, erschlossen, überrascht)"],"items":[["Du warst gestern selbst im Kino.",0],["Dein Freund erzählt dir, dass Ayşe umgezogen ist.",1],["Du öffnest die Tür und siehst: Es hat geschneit!",1],["Du erzählst, was du gestern gegessen hast.",0],["Du liest in der Zeitung, dass der Minister zurückgetreten ist.",1],["Du erzählst von deiner letzten Reise.",0]],"why":{"Du warst gestern selbst im Kino.":"Du hast es selbst erlebt: -DI (sinemaya gittim).","Dein Freund erzählt dir, dass Ayşe umgezogen ist.":"Fremde Information: taşınmış.","Du öffnest die Tür und siehst: Es hat geschneit!":"Du siehst das Ergebnis, nicht den Vorgang, und bist überrascht: yağmış.","Du erzählst, was du gestern gegessen hast.":"Eigenes Erlebnis: yedim.","Du liest in der Zeitung, dass der Minister zurückgetreten ist.":"Aus zweiter Hand: istifa etmiş.","Du erzählst von deiner letzten Reise.":"Eigenes Erlebnis: gittim, gördüm."},"e":"-DI = ich habe es selbst erlebt. -mIş = gehört, gelesen, aus dem Ergebnis erschlossen oder überrascht."},
    { id: "tr-b1-01.19", t: "listen", say: "Biz tiyatroya vardık, ama oyun çoktan başlamıştı.", q: "Hör zu: Was war schon passiert, als sie ankamen?",
      o: ["Das Stück hatte schon begonnen.", "Das Stück war schon zu Ende.", "Das Stück sollte erst anfangen.", "Das Theater war geschlossen."], a: 0,
      why: { 1: "*başlamıştı* = hatte begonnen, nicht „war zu Ende“ (*bitmişti*).", 2: "-mIştI = es war **schon** passiert, nicht „erst später“.", 3: "Von Schließung ist nicht die Rede." },
      e: "„Wir kamen im Theater an, aber das Stück hatte schon begonnen.“ *vardık* (-DI, kam an) gegen *başlamıştı* (-mIştI, war schon passiert)." },
    { id: "tr-b1-01.20", t: "dictation", say: "Meğer komşumuz çoktan taşınmış, kimse bize söylememiş.", a: ["Meğer komşumuz çoktan taşınmış, kimse bize söylememiş."],
      wrong: { "Meğer komşumuz çoktan taşınmiş, kimse bize söylememiş.": "Letzter Vokal von *taşın-* ist **ı** → taşın**mış** ohne Punkt.", "Meğer komşumuz çoktan taşınmış, kimse bize söylemiş.": "Hier fehlt die Verneinung: „niemand hat es uns gesagt“ → söyle**me**miş.", "Meğer komşumuz çoktan taşınmış, kimse bize söylememişti.": "Mit -tI wäre es Vorzeitigkeit. Der Satz sagt: offenbar hat es niemand gesagt (-mIş)." },
      e: "„Wie sich herausstellt, ist unser Nachbar längst umgezogen; offenbar hat es uns niemand gesagt.“ *kimse* + Verneinung = niemand." },
    { id: "tr-b1-01.21", t: "speak", say: "Ben gelince film çoktan bitmişti.",
      e: "„Als ich kam, war der Film schon zu Ende.“ *bitmişti*: das ş wie „sch“, das tt kurz doppelt. Alle i mit Punkt. *çoktan* beginnt mit „tsch“. Typischer Fehler: *bit-mi-sti* mit deutschem „st“." },
    { id: "tr-b1-01.22", t: "speak", say: "Meğer komşumuz taşınmış.",
      e: "„Wie sich herausstellt, ist unser Nachbar umgezogen.“ *meğer*: das ğ nach e klingt wie ein leichtes j: „me-yer“. *taşınmış*: dumpfes ı, zweimal ş wie „sch“. Typischer Fehler: *meger* mit hartem g." },
    { id: "tr-b1-01.23", t: "speak", say: "Aa, bak, bütün gece kar yağmış!",
      e: "„Ach, schau, es hat die ganze Nacht geschneit!“ Die Überraschung steckt in der Stimme: *aa* lang und steigend. *bütün* mit ü wie in „über“, *yağmış* mit stummem ğ: ya-mış (das a lang)." },
    { id: "tr-b1-01.24", t: "respond", say: "Eve geldin, pencere açık, yerde cam var. Ne olmuş?",
      q: "Hör dir die Situation an und antworte laut in 2–3 Sätzen. Vermute, was passiert ist, mit -mIş.",
      chunks: ["Sanırım biri …", "Belki de …", "Meğer …", "Çünkü …"],
      models: ["Sanırım biri pencereden girmiş. Belki de kedi camı kırmış. Meğer pencereyi sabah açık bırakmışım.", "Sanırım rüzgâr camı kırmış. Çünkü pencere açıkmış ve dışarıda fırtına varmış."],
      modelsN: ["Ich glaube, jemand ist durchs Fenster eingestiegen. Vielleicht hat die Katze das Glas zerbrochen. Wie sich herausstellt, habe ich das Fenster morgens offen gelassen.", "Ich glaube, der Wind hat das Glas zerbrochen. Denn das Fenster war offen, und draußen war wohl ein Sturm."],
      e: "Du schließt aus dem Ergebnis (Glas am Boden) auf das, was passiert ist: **-mIş** (girmiş, kırmış). Mit *meğer* entdeckst du etwas über dich selbst: *bırakmışım*. Nomen mit -(y)mIş: *açıkmış*. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-07', {
  lesson: [
    { p: "Im Deutschen hast du **zu + Infinitiv** („Ich habe vergessen, zu schreiben“) und **dass-Sätze** („Ich möchte, dass du kommst“). Türkisch hat **keine dass-Sätze mit eigenem Verb**. Stattdessen macht es aus dem Verb ein **Nomen** (Verbalnomen): **-mAk**, **-mA** und **-(y)Iş**. Der Handelnde steckt im Possessivsuffix: *gel-me-n* = „dein Kommen“." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutsche Konstruktion", "Bauplan", "Beispiel"], rows: [
      ["Ich möchte gehen. (gleicher Handelnder)", "Stamm + **-mAk**", "git**mek** istiyorum"],
      ["Ich möchte, dass du kommst. (anderer Handelnder)", "Stamm + **-mA** + Possessiv + Kasus", "gel**men**i istiyorum"],
      ["Ich liebe es zu schwimmen / Ich habe vergessen zu …", "Stamm + **-mA** + **-yI**/**-yA**", "yüz**meyi** seviyorum"],
      ["Die Art, wie sie lacht / Spaziergang / Abfahrt", "Stamm + **-(y)Iş**", "gül**üş**, yürü**yüş**, kalk**ış**"]
    ] } },
    { h: "1. -mAk: gleicher Handelnder" },
    { p: "-mAk ist der **Infinitiv**, die Form, die du aus dem Wörterbuch kennst. Er steht, wenn **derselbe** Handelnde Verb 1 und Verb 2 macht: *Ben sinemaya **gitmek** istiyorum.* Typisch dafür: **istemek** (wollen), **-mAk için** (um zu), **-mAk zorunda** (müssen) und als Subjekt: *Yüzmek sağlıklı.*" },
    { h: "2. -mA + Possessiv: anderer Handelnder (dass-Satz)" },
    { p: "Wechselt der Handelnde, nimmst du **-mA** und hängst das **Possessivsuffix** an, das den neuen Handelnden zeigt. Danach folgt ein **Kasus**, wie ihn das Hauptverb verlangt (nach *istemek*: Akkusativ)." },
    { table: { head: ["Person", "-mA + Possessiv", "+ Akkusativ", "Beispiel"], rows: [
      ["ben", "gelme**m**", "gelme**mi**", "Annem **gitmemi** istiyor."],
      ["sen", "gelme**n**", "gelme**ni**", "**Gelmeni** istiyorum."],
      ["o", "gelme**si**", "gelme**sini**", "**Gelmesini** bekliyorum."],
      ["biz", "gelme**miz**", "gelme**mizi**", "**Gelmemizi** istiyorlar."],
      ["siz", "gelme**niz**", "gelme**nizi**", "**Gelmenizi** rica ederim."],
      ["onlar", "gelme**leri**", "gelme**lerini**", "**Gelmelerini** bekledik."]
    ] } },
    { warn: "Typischer Fehler: *„Ben senin geliyorsun istiyorum“* – so wie im Deutschen „ich will, du kommst“. Türkisch hat hier **kein zweites konjugiertes Verb**: *Gelmeni istiyorum.* (wörtlich „dein Kommen will ich“). Wer handelt, sieht man an der Possessiv-Endung (-n = du)." },
    { p: "Verneinung: **-mA- vor -mA**: *gelmeme-n-i* → **gelmemeni** istiyorum (ich will, dass du nicht kommst). Als Subjekt braucht -mA + Possessiv den **Nominativ**: *Senin çok çalışman beni üzüyor.* (Dass du so viel arbeitest, macht mich traurig.) Mit **gerek/lazım**: *Gitmem gerekiyor.* (Ich muss gehen. Wörtlich „mein Gehen ist nötig“.) Mit **rağmen** (Dativ): *Çok çalışmasına rağmen zengin değil.* (Obwohl er viel arbeitet, ist er nicht reich.)" },
    { h: "3. -mA + Kasus ohne Possessiv: sevmek, başlamak, bırakmak …" },
    { p: "Bei Verben, die **dasselbe Subjekt** haben und ein Objekt verlangen, steht -mA mit dem Kasus des Hauptverbs, ohne Possessiv. **Das Hauptverb bestimmt den Kasus.**" },
    { table: { head: ["Hauptverb", "Kasus", "Beispiel"], rows: [
      ["sevmek, öğrenmek, bırakmak, unutmak, denemek", "Akkusativ **-mAyI**", "Yüz**meyi** öğrendim. Sigara iç**meyi** bıraktım."],
      ["başlamak, karar vermek, devam etmek", "Dativ **-mAyA**", "Çalış**maya** başladım. Gitme**ye** karar verdim."],
      ["korkmak, hoşlanmak", "Ablativ **-mAktAn**", "Uç**maktan** korkuyorum."]
    ] } },
    { tip: "Der Puffer: -mA endet auf Vokal, deshalb **y** vor dem Kasus: yüz-me-**y**i, çalış-ma-**y**a. Ohne Kasus (Nominativ) braucht man ihn nicht." },
    { h: "4. -(y)Iş: die Art und das Ergebnis" },
    { p: "-(y)Iş macht aus dem Verb ein **Nomen** der Art und Weise oder des Vorgangs: *gül-üş* (die Art zu lachen), *bak-ış* (Blick), *yürü-yüş* (Spaziergang), *kalk-ış* (Abfahrt), *var-ış* (Ankunft), *giriş / çıkış* (Eingang / Ausgang). Vokalharmonie ı/i/u/ü, nach Vokal Puffer-**y** (yürü-**y**üş). **Achtung:** t wird zu d vor dem Vokal: *git* → **gid**iş (*gidiş dönüş* = Hin- und Rückfahrt)." },
    { tip: "Mit Possessiv: *Onun gülüşünü seviyorum.* (Ich mag seine/ihre Art zu lachen.) *gül-üş-ü-nü*: -üş (Nomen), -ü (3. Person), -nü (Akkusativ, mit Puffer-n)." },
    { ex: [
      ["Hafta sonu sinemaya gitmek istiyorum.", "Am Wochenende möchte ich ins Kino gehen."],
      ["Annem benim doktora gitmemi istiyor.", "Meine Mutter möchte, dass ich zum Arzt gehe."],
      ["Çocuklar yüzmeyi öğreniyor.", "Die Kinder lernen schwimmen."],
      ["Dün akşam sana mesaj yazmayı unuttum.", "Gestern Abend habe ich vergessen, dir zu schreiben."],
      ["Her sabah parkta bir saat yürüyüş yapıyorum.", "Jeden Morgen mache ich eine Stunde Spaziergang im Park."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-07.1", t: "gap", q: "Ben bu hafta sonu sinemaya ___ istiyorum. (gitmek – Ich möchte am Wochenende ins Kino gehen.)", a: ["gitmek"],
      wrong: { "gitmeyi": "Nach *istemek* ist der Infinitiv auf **-mAk** üblicher (-mAyI klingt hier ungewöhnlich). Der Handelnde ist derselbe.", "gitme": "Hier fehlt das **k**: -mAk ist der Infinitiv.", "gitmemi": "Mit -mA + Possessiv wechselst du den Handelnden („ich will, dass ich gehe“). Hier handelt dieselbe Person: -mAk." },
      e: "Gleicher Handelnder + istemek = **-mAk**: gitmek istiyorum. Wie im Deutschen „ich will gehen“, nur ohne „zu“." },
    { id: "tr-b1-07.2", t: "gap", q: "Annem benim doktora ___ istiyor. (gitmek – Meine Mutter möchte, dass ich zum Arzt gehe.)", a: ["gitmemi"],
      wrong: { "gitmek": "Dann würde die Mutter selbst gehen. Der Handelnde wechselt (ich), also -mA + **Possessiv**.", "gitmem": "Nach *istemek* braucht das Objekt den **Akkusativ**: gitmem**i**.", "gitmeni": "-n ist „du“. Hier geht „ich“: -m.", "gitmeyi": "Ohne Possessiv bleibt unklar, wer geht. „Ich“ → -me**m** + i." },
      e: "git- + **me** + **m** (ich) + **i** (Akkusativ nach istemek) = **gitmemi**. Wer handelt, sagt die Possessiv-Endung." },
    { id: "tr-b1-07.3", t: "gap", q: "Senin bu kadar çok ___ beni üzüyor. (çalışmak – Dass du so viel arbeitest, macht mich traurig.)", a: ["çalışman"],
      wrong: { "çalışmanı": "Der Ausdruck ist das **Subjekt** („…macht mich traurig“): Nominativ, kein Akkusativ-i.", "çalışmak": "-mAk passt nicht, weil „du“ der Handelnde ist: -mA + **-n**.", "çalışması": "-sI ist „er/sie“. Hier geht es um „du“ (*senin*): -n." },
      e: "çalış- + **ma** + **n** (du) = **çalışman**. Als Subjekt bleibt es im Nominativ." },
    { id: "tr-b1-07.4", t: "gap", q: "Çocuklar yüz___ öğreniyor. (yüzmek – Die Kinder lernen schwimmen.)", a: ["meyi", "me"],
      wrong: { "mek": "*öğrenmek* verlangt ein Objekt im Akkusativ: -mA**yI**.", "mayı": "Letzter Vokal von *yüz-* ist **ü** → -me**yi**, nicht -mayı." },
      e: "yüz- + **me** + **y** (Puffer) + **i** (Akkusativ) = **yüzmeyi**. Umgangssprachlich hört man auch *yüzme öğreniyor* (Schwimmen lernen als feste Verbindung). Nach *öğrenmek, sevmek, bırakmak, unutmak* steht -mAyI." },
    { id: "tr-b1-07.5", t: "gap", q: "Dün akşam sana mesaj yaz___ unuttum. (Gestern Abend habe ich vergessen, dir zu schreiben.)", a: ["mayı"],
      wrong: { "mak": "*unutmak* verlangt den Akkusativ: -mA**yI**.", "meyi": "Letzter Vokal von *yaz-* ist **a** → -ma**yı**.", "mayi": "Letzter Vokal von -ma ist **a**, aber das Kasus-ı ist ohne Punkt: -ma**yı**." },
      e: "yaz- + **ma** + **y** + **ı** = **yazmayı**. Das Hauptverb *unutmak* verlangt den Akkusativ." },
    { id: "tr-b1-07.6", t: "gap", q: "Her sabah parkta bir saat yürü___ yapıyorum. (yürümek – Jeden Morgen mache ich eine Stunde Spaziergang im Park.)", a: ["yüş"],
      wrong: { "üş": "*yürü-* endet auf Vokal → der Puffer-**y** ist nötig: yürü**y**üş.", "yış": "Letzter Vokal von *yürü-* ist **ü** → -yüş, nicht -yış.", "yuş": "Letzter Vokal ist **ü** (nicht u) → -yüş." },
      e: "yürü- + **y** + **üş** = **yürüyüş**. *yürüyüş yapmak* = Spaziergang machen." },
    { id: "tr-b1-07.7", t: "mc", q: "„Ich muss jetzt gehen.“", o: ["Gitmem gerekiyor.", "Gitmen gerekiyor.", "Gitmemi gerekiyor.", "Gitmesi gerekiyor."], a: 0,
      why: { 1: "-n = „du“: *Gitmen gerekiyor* = du musst gehen.", 2: "*gerekmek* hat das Verbalnomen als **Subjekt**: kein Akkusativ-i.", 3: "-sI = „er/sie“: er/sie muss gehen." },
      e: "git- + **me** + **m** (ich) + **gerekiyor** (ist nötig). Wörtlich: „Mein Gehen ist nötig.“" },
    { id: "tr-b1-07.8", t: "mc", q: "„Ich habe aufgehört zu rauchen.“", o: ["Sigara içmeyi bıraktım.", "Sigara içmek bıraktım.", "Sigara içme bıraktım.", "Sigara içmeye bıraktım."], a: 0,
      why: { 1: "*bırakmak* braucht den Akkusativ: -mA**yI**, nicht -mAk.", 2: "Es fehlt das **-yi** des Akkusativs.", 3: "-mAyA (Dativ) steht nach *başlamak*, nicht nach *bırakmak*." },
      e: "iç- + **me** + **yi** = **içmeyi**. Bırakmak (aufhören) verlangt wie sevmek den Akkusativ." },
    { id: "tr-b1-07.9", t: "mc", q: "„Ich habe angefangen, Türkisch zu lernen.“", o: ["Türkçe öğrenmeye başladım.", "Türkçe öğrenmeyi başladım.", "Türkçe öğrenmek başladım.", "Türkçe öğrenmeme başladım."], a: 0,
      why: { 1: "*başlamak* verlangt den Dativ: -mA**yA**, nicht -mAyI.", 2: "-mAk allein passt nicht als Objekt von *başlamak*.", 3: "Bei gleichem Handelnden braucht man kein Possessiv: -mAyA genügt." },
      e: "öğren- + **me** + **y** + **e** = **öğrenmeye**. Merke: başlamak → Dativ (-mAyA), bırakmak/sevmek → Akkusativ (-mAyI)." },
    { id: "tr-b1-07.10", t: "mc", q: "„Wir fahren nach Izmir, um meine Oma zu besuchen.“", o: ["Babaannemi ziyaret etmek için İzmir’e gidiyoruz.", "Babaannemi ziyaret etmeye için İzmir’e gidiyoruz.", "Babaannemi ziyaret etme için İzmir’e gidiyoruz.", "Babaannemi ziyaret ediş için İzmir’e gidiyoruz."], a: 0,
      why: { 1: "*için* steht direkt hinter dem Infinitiv auf -mAk, ohne Dativ.", 2: "*-mA için* ist keine übliche Form für „um zu“.", 3: "-(y)Iş benennt die Art und Weise, nicht den Zweck." },
      e: "„Um … zu“ = **-mAk için**: ziyaret et**mek için**." },
    { id: "tr-b1-07.11", t: "mc", q: "Wie heißt die „Hinfahrt“ (von gitmek) in *… dönüş bileti*?", o: ["gidiş", "gitiş", "gitmiş", "gidmek"], a: 0,
      why: { 1: "t wird vor einem Vokal zu **d**: git → gidiyorum, gid-iş.", 2: "*gitmiş* ist die -mIş-Form („er ist offenbar gegangen“), kein Nomen.", 3: "*gidmek* gibt es nicht – der Infinitiv heißt gitmek." },
      e: "git- → **gid-** + **iş** = **gidiş**. *gidiş dönüş* = Hin- und Rückfahrt." },
    { id: "tr-b1-07.12", t: "mc", q: "„Ich mag ihre Art zu lachen.“", o: ["Onun gülüşünü seviyorum.", "Onun gülmek seviyorum.", "Onun gülmeyi seviyorum.", "Onun gülüş seviyorum."], a: 0,
      why: { 1: "Weder Possessiv noch Akkusativ: -mAk passt nicht zu „ihre Art zu lachen“.", 2: "*gülmeyi* bezieht sich auf „ich lache“ und ignoriert *onun*.", 3: "Es fehlt das Possessiv -ü (3. Person) und der Akkusativ." },
      e: "gül- + **üş** + **ü** (Poss. 3. Person) + **nü** (Akk. mit Puffer-n) = **gülüşünü**." },
    { id: "tr-b1-07.13", t: "order", q: "Bilde den Satz: „Ich möchte, dass du mir hilfst.“", w: ["istiyorum", "Bana", "yardım", "etmeni"], a: ["Bana yardım etmeni istiyorum"],
      e: "*yardım etmek* (helfen, mit Dativ: *bana*). Das Verbalnomen *etmeni* (du) trägt den Akkusativ, *istiyorum* steht am Ende." },
    { id: "tr-b1-07.14", t: "order", q: "Bilde den Satz: „Mein Vater hat vergessen, die Tür abzuschließen.“", w: ["unuttu", "Babam", "kapıyı", "kilitlemeyi"], a: ["Babam kapıyı kilitlemeyi unuttu"],
      e: "*unutmak* + -mAyI. *kapıyı* (bestimmtes Objekt, Akkusativ) gehört zu *kilitlemek*. *Babam* als Subjekt vorne." },
    { id: "tr-b1-07.15", t: "order", q: "Bilde den Satz: „Obwohl er viel arbeitet, ist er nicht reich.“", w: ["Çok", "çalışmasına", "rağmen", "zengin", "değil"], a: ["Çok çalışmasına rağmen zengin değil"],
      e: "*çalış-ma-sı-na rağmen* – das Verbalnomen mit Possessiv (er) und Dativ vor *rağmen* (obwohl). Das Türkische braucht keinen Nebensatz mit „obwohl“." },
    { id: "tr-b1-07.16", t: "match", q: "Welche Form verlangt das Hauptverb?", p: [["istemek", "-mAk (gitmek istiyorum)"], ["sevmek", "-mAyI (yüzmeyi seviyorum)"], ["başlamak", "-mAyA (çalışmaya başladı)"], ["için (um zu)", "-mAk (almak için)"], ["gerekmek", "-mA + Possessiv (gitmem gerekiyor)"]],
      e: "Das Hauptverb bestimmt die Form: istemek und için → -mAk; sevmek → -mAyI; başlamak → -mAyA; gerekmek → -mA + Possessiv als Subjekt." },
    {"id":"tr-b1-07.17","t":"cloze","q":"Ergänze die Verbalnomen.","text":"Geçen yıl Türkçe öğren{1} başladım. Şimdi Türkiye’de çalış{2} istiyorum. Annem benim daha çok dinlen{3} istiyor.","gaps":{"1":{"a":["meye"],"wrong":{"mek":"*başlamak* verlangt den Dativ: -mA**yA**.","meyi":"Nach *başlamak* steht der Dativ, nicht der Akkusativ.","maya":"Letzter Vokal von *öğren-* ist **e** → -me**ye**."}},"2":{"a":["mak"],"wrong":{"mayı":"Nach *istemek* steht -mAk, nicht -mAyI.","mam":"Possessiv -m würde „ich“ + anderen Handelnden anzeigen. Hier arbeitet dieselbe Person: -mAk.","mek":"Letzter Vokal von *çalış-* ist **ı** → -m**a**k (kleine Harmonie)."}},"3":{"a":["memi"],"wrong":{"mek":"Dann würde die Mutter ruhen. Der Handelnde ist „ich“: -me**m**.","meni":"-n = „du“. Hier handelt „ich“: -m.","meyi":"Ohne Possessiv fehlt, wer sich ausruht. -mem + i."}}},"e":"Gleicher Handelnder: -mAyA (nach başlamak), -mAk (nach istemek). Wechselt der Handelnde („Annem … benim dinlenmemi istiyor“), kommt -mA + Possessiv + Akkusativ: dinlen**memi**."},
    {"id":"tr-b1-07.18","t":"sort","q":"Wer handelt? Ordne die Sätze dem Bauplan zu.","cats":["gleicher Handelnder → -mAk","anderer Handelnder → -mA + Possessiv"],"items":[["Ich will nach Hause gehen.",0],["Ich will, dass du nach Hause gehst.",1],["Meine Chefin will, dass ich morgen komme.",1],["Wir möchten ein Eis essen.",0],["Er bittet sie, leiser zu sein.",1],["Sie will Ärztin werden.",0]],"why":{"Ich will nach Hause gehen.":"Ich will und ich gehe: eine Person → gitmek istiyorum.","Ich will, dass du nach Hause gehst.":"Ich will, du gehst: neuer Handelnder → gitmeni istiyorum.","Meine Chefin will, dass ich morgen komme.":"Die Chefin will, ich komme: Wechsel → gelmemi istiyor.","Wir möchten ein Eis essen.":"Wir wollen und wir essen: yemek istiyoruz.","Er bittet sie, leiser zu sein.":"Er bittet, sie soll leise sein: Wechsel → sessiz olmasını rica ediyor.","Sie will Ärztin werden.":"Sie will und sie wird: olmak istiyor."},"e":"Dieselbe Person handelt → -mAk. Wechselt der Handelnde, braucht -mA ein Possessiv, das ihn anzeigt."},
    { id: "tr-b1-07.19", t: "listen", say: "Annem her sabah erken kalkmamı ve kahvaltı yapmamı istiyor.", q: "Hör zu: Was wünscht sich die Mutter?",
      o: ["Dass ich früh aufstehe und frühstücke.", "Dass sie selbst früh aufsteht.", "Dass ich spät frühstücke.", "Dass wir zusammen frühstücken."], a: 0,
      why: { 1: "*kalkmamı* heißt „dass ich aufstehe“ (-m = ich), nicht „dass sie aufsteht“.", 2: "*erken kalkmamı* = dass ich **früh** aufstehe.", 3: "Von „zusammen“ ist keine Rede; Handelnder ist „ich“ (*yapmamı*)." },
      e: "kalk-**ma-m-ı** und yap-**ma-m-ı** + istiyor: „Meine Mutter will, dass ich jeden Morgen früh aufstehe und frühstücke.“" },
    { id: "tr-b1-07.20", t: "dictation", say: "Sigara içmeyi bıraktım, çünkü sağlığım için çok kötüydü.", a: ["Sigara içmeyi bıraktım, çünkü sağlığım için çok kötüydü."],
      wrong: { "Sigara içmek bıraktım, çünkü sağlığım için çok kötüydü.": "*bırakmak* braucht den Akkusativ: iç**meyi**.", "Sigara içmeyi bıraktım, çünkü sağlıkım için çok kötüydü.": "*sağlık* → k wird vor Vokal zu **ğ**: sağlı**ğ**ım.", "Sigara içmeyi bırakdım, çünkü sağlığım için çok kötüydü.": "*k* ist stimmlos → d wird **t**: bırak**t**ım." },
      e: "„Ich habe aufgehört zu rauchen, weil es sehr schlecht für meine Gesundheit war.“ *sağlık* wird zu *sağlığım* (Konsonantenerweichung)." },
    { id: "tr-b1-07.21", t: "speak", say: "Ben her sabah yürüyüş yapmayı seviyorum.",
      e: "„Ich mache jeden Morgen gern einen Spaziergang.“ *yürüyüş*: ü wie in „über“, y zwischen den Vokalen kurz. *yapmayı*: dumpfes ı am Ende. Typischer Fehler: *yapmaji* mit deutschem „i“." },
    { id: "tr-b1-07.22", t: "speak", say: "Annem benim daha çok dinlenmemi istiyor.",
      e: "„Meine Mutter möchte, dass ich mich mehr ausruhe.“ *dinlenmemi*: din-len-me-mi, alle e kurz und offen. *istiyor*: is-ti-yor, das s nicht wie „sch“. Typischer Fehler: *dinlenme mi* als Frage getrennt gelesen – hier ist es ein einziges Wort." },
    { id: "tr-b1-07.23", t: "speak", say: "Gitmem gerekiyor, çünkü geç oldu.",
      e: "„Ich muss gehen, denn es ist spät geworden.“ *gerekiyor*: g wie im Deutschen, r gerollt. *çünkü*: ç wie „tsch“, ü wie „über“. Typischer Fehler: *chünkü* mit „ch“ statt „tsch“." },
    { id: "tr-b1-07.24", t: "respond", say: "Boş zamanında ne yapmayı seviyorsun?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -mAyI nach sevmek und -mAk nach istemek.",
      chunks: ["Boş zamanımda … seviyorum.", "Hafta sonu … istiyorum.", "Bir de … yapmayı …", "Çünkü …"],
      models: ["Boş zamanımda kitap okumayı ve yürüyüş yapmayı seviyorum. Hafta sonu arkadaşlarımla buluşmak istiyorum. Çünkü birlikte vakit geçirmek çok güzel.", "Boş zamanımda müzik dinlemeyi seviyorum. Bir de yemek yapmayı çok seviyorum. Hafta sonu ailemi ziyaret etmek istiyorum."],
      modelsN: ["In meiner Freizeit lese ich gern und gehe gern spazieren. Am Wochenende möchte ich mich mit Freunden treffen. Denn zusammen Zeit zu verbringen ist schön.", "In meiner Freizeit höre ich gern Musik. Außerdem koche ich sehr gern. Am Wochenende möchte ich meine Familie besuchen."],
      e: "Nach **sevmek** steht -mA**yI**: okuma**yı**, dinleme**yi**. Nach **istemek** und **için** steht -mAk: buluş**mak**, ziyaret et**mek**. Du kannst auch -(y)Iş benutzen: *yürüyüş yapmak*. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-02', {
  lesson: [
    { p: "Im Deutschen hängst du einen **Relativsatz** hinter das Bezugswort: „der Mann, **der** gestern angerufen hat“. Türkisch hat kein Relativpronomen und keinen Nebensatz mit eigenem Verb. Das Verb wird zu einem **Partizip** und steht wie ein Adjektiv **vor** dem Nomen: *dün arayan adam*. Alles, was im Deutschen nach „der/die/das“ kommt, steht im Türkischen **vor** dem Bezugswort." },
    { h: "Der Bauplan: Verbstamm + -(y)An + Nomen" },
    { table: { head: ["Deutscher Relativsatz", "Bauplan", "Türkisch"], rows: [
      ["der Mann, der kommt", "Stamm + **-An** + Nomen", "gel**en** adam"],
      ["die Frau, die hier arbeitet", "Ergänzung (z. B. Ortsangabe) + Stamm + -An + Nomen", "burada çalış**an** kadın"],
      ["die Kinder, die im Garten spielen", "… Stamm + **-yAn** (nach Vokal)", "bahçede oyna**yan** çocuklar"],
      ["der Gast, der nicht kommt", "Stamm + **-mA** + **-yAn**", "gel**meyen** misafir"]
    ] } },
    { p: "**-An** hat zwei Formen (kleine Vokalharmonie): **-an** nach a, ı, o, u (*çalışan, okuyan, olan*) und **-en** nach e, i, ö, ü (*gelen, giden, gören*). Endet der Stamm auf einen **Vokal**, steht der Puffer-**y**: *oyna-**y**an, bekle-**y**en, ye-**y**en* → *yiyen* (ye- wird vor -yAn zu yi-; auch *de-* → *diyen*). Bei *gitmek* und *etmek* wird t vor dem Vokal zu **d**: *giden, eden* (*yardım eden kişi*)." },
    { p: "Die Verneinung steht vor dem Partizip: **-mA-yAn**, also *gelmeyen, çalışmayan, bilmeyen*. Auf **-mIyen** (*gelmiyen*) musst du achten: Das ist ein typischer Fehler, weil -mIyor im Kopf mitläuft." },
    { warn: "**Keine Personalendung, kein Plural, keine Zeit:** *gelen* heißt „der kommt / der kam / der (immer) kommt“, ob es um jetzt oder früher geht, sagt der Zusammenhang. Und das Partizip bekommt vor einem Nomen **nie** -lAr: *gelen çocuklar* (nicht „gelenler çocuklar“). Auch ein konjugiertes Verb (*„geliyor adam“, „geldi adam“*) darf nie vor dem Nomen stehen." },
    { h: "Wann geht -(y)An? Nur wenn das Bezugswort der Handelnde ist" },
    { p: "-(y)An ersetzt Relativsätze, in denen das Bezugswort das **Subjekt** ist („**der** Mann, der anruft“). Ist das Bezugswort Objekt („der Mann, **den** ich anrief“) oder ein Ort („das Haus, **in dem** ich wohne“), nimmst du -DIk/-(y)AcAk (das lernst du im Thema über Partizipien mit Possessiv)." },
    { h: "Als Nomen ohne Bezugswort: „der, der …“" },
    { p: "Lässt du das Nomen weg, wird das Partizip selbst zum Nomen und bekommt Plural und Kasus: *gelenler* (die, die kommen), *Bilen var mı?* (Gibt es jemanden, der es weiß?), *Erken gelenler oturabilir.* (Wer früh kommt, darf sich setzen.)" },
    { tip: "Bei **Nomen und Adjektiven** braucht das Partizip **olan** („der … ist“): *evde olan çocuk* (das Kind, das zu Hause ist), *hasta olan öğrenci* (der Schüler, der krank ist), *burada olmayan kişi* (die Person, die nicht hier ist). Wichtig, weil man *evde* oder *hasta* nicht einfach zu einem Partizip machen kann." },
    { ex: [
      ["Kapıda bekleyen adam seni arıyor.", "Der Mann, der an der Tür wartet, sucht dich."],
      ["Ankara’ya giden otobüs saat dokuzda kalkıyor.", "Der Bus, der nach Ankara fährt, fährt um neun Uhr ab."],
      ["Bana yardım eden komşuya teşekkür ettim.", "Ich habe mich bei dem Nachbarn bedankt, der mir geholfen hat."],
      ["Türkçe konuşan biri var mı?", "Gibt es jemanden, der Türkisch spricht?"],
      ["Gelmeyen öğrencilere haber verdik.", "Wir haben den Schülern, die nicht gekommen sind, Bescheid gesagt."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-02.1", t: "gap", q: "Burada çalış___ kadın benim teyzem. (Die Frau, die hier arbeitet, ist meine Tante.)", a: ["an"],
      wrong: { "en": "Letzter Vokal von *çalış-* ist **ı** → -**an** (kleine Harmonie: a, ı, o, u → an).", "ıyor": "Ein konjugiertes Verb darf nicht vor dem Nomen stehen. Das Partizip heißt **-(y)An**.", "tığı": "-DIk steht für den Fall, dass das Bezugswort Objekt oder Ort ist („die Frau, bei der er arbeitet“). Hier ist die Frau selbst die Handelnde." },
      e: "çalış- + **an** = **çalışan**. Wie ein Adjektiv steht es direkt vor dem Nomen: *çalışan kadın*." },
    { id: "tr-b1-02.2", t: "gap", q: "Kapıda bekle___ adam kim? (Wer ist der Mann, der an der Tür wartet?)", a: ["yen"],
      wrong: { "en": "*bekle-* endet auf einen Vokal → der Puffer-**y** ist nötig: bekle**y**en.", "yan": "Letzter Vokal von *bekle-* ist **e** → -y**en**, nicht -yan.", "yin": "-(y)An hat keine Form mit i. Es heißt **-yen**." },
      e: "bekle- + **y** + **en** = **bekleyen**. Nach Vokal steht immer der Puffer-y." },
    { id: "tr-b1-02.3", t: "gap", q: "Okula ___ yol çok uzun. (gitmek – Der Weg, der zur Schule führt, ist sehr lang.)", a: ["giden"],
      wrong: { "giten": "t wird vor einem **Vokal** zu d (gidiyorum, **gid**en). Nur vor Konsonanten bleibt es t.", "gidan": "Letzter Vokal von *git-* ist **i** → -**en**.", "gitmeyen": "Das wäre „der nicht führt“. Hier führt der Weg zur Schule." },
      e: "git- (t → d) + **en** = **giden**. „Der Weg, der führt“ = *giden yol*." },
    { id: "tr-b1-02.4", t: "gap", q: "Bu konuyu ___ kimse var mı? (bilmek – Gibt es jemanden, der dieses Thema nicht kennt?)", a: ["bilmeyen"],
      wrong: { "bilen": "Das heißt „der es kennt“. Du willst die Verneinung: -mA- vor -yAn.", "bilmiyen": "Das Partizip wird mit **-mA-** verneint, nicht mit -mI-: bil-**me**-yen.", "bilmeyan": "Letzter Vokal von *bil-me-* ist **e** → -yen." },
      e: "bil- + **me** (Verneinung) + **y** + **en** = **bilmeyen**." },
    { id: "tr-b1-02.5", t: "gap", q: "Sınavı geçen___ çok sevindi. (Die, die die Prüfung bestanden haben, haben sich sehr gefreut.)", a: ["ler"],
      wrong: { "lar": "Letzter Vokal von *geçen* ist **e** → -**ler**.", "leri": "Als Subjekt braucht der Satz keinen Akkusativ. Es genügt -ler: geçen**ler** sevindi.", "ler mi": "Das wäre eine Frage. Hier erzählst du." },
      e: "Ohne Bezugswort wird das Partizip selbst zum Nomen: geçen + **ler** = „die, die bestanden haben“." },
    { id: "tr-b1-02.6", t: "gap", q: "Evde ol___ kitapları getir. (Bring die Bücher, die zu Hause sind.)", a: ["an"],
      wrong: { "en": "Letzter Vokal von *ol-* ist **o** → -**an**.", "yan": "*ol-* endet auf Konsonant l → kein Puffer-y: ol**an**." },
      e: "evde + **olan** = „die dort sind“. *evde olan kitaplar* = die Bücher, die zu Hause sind." },
    { id: "tr-b1-02.7", t: "mc", q: "„Der Mann, der gestern angerufen hat, ist mein Chef.“", o: ["Dün arayan adam benim müdürüm.", "Adam dün arayan benim müdürüm.", "Dün arıyor adam benim müdürüm.", "Dün aradığı adam benim müdürüm."], a: 0,
      why: { 1: "Das Partizip steht **vor** dem Nomen, das es näher bestimmt (arayan adam).", 2: "Ein konjugiertes Verb (*arıyor*) kann nicht vor dem Nomen stehen.", 3: "*-DIğI* zeigt, dass das Bezugswort **Objekt** ist („den er angerufen hat“)." },
      e: "ara- + **yan** + adam. Relativsatz = Partizip + Nomen." },
    { id: "tr-b1-02.8", t: "mc", q: "„die Kinder, die im Garten spielen“", o: ["bahçede oynayan çocuklar", "bahçede oynayanlar çocuklar", "bahçede oynan çocuklar", "bahçede oynıyan çocuklar"], a: 0,
      why: { 1: "Vor einem Nomen bekommt das Partizip keinen Plural. Der Plural steht am Nomen: *çocuklar*.", 2: "Nach Vokal braucht -An den Puffer-**y**: oyna**yan**.", 3: "-(y)An hat nur a/e: oyna**yan**, nicht -Iyan." },
      e: "oyna- + **yan** + çocuklar." },
    { id: "tr-b1-02.9", t: "mc", q: "„Gibt es jemanden, der Türkisch spricht?“", o: ["Türkçe konuşan var mı?", "Türkçe konuşuyor biri var mı?", "Türkçe konuşmak var mı?", "Türkçe konuşar var mı?"], a: 0,
      why: { 1: "Ein konjugiertes Verb kann nicht vor dem Nomen stehen. Das Partizip ersetzt es.", 2: "*konuşmak* ist der Infinitiv („Türkisch sprechen“), nicht „jemand, der spricht“.", 3: "*konuşar* ist keine Form für „der spricht“." },
      e: "konuş- + **an** = „der, der spricht“, auch ohne Nomen (*Türkçe konuşan var mı?*)." },
    { id: "tr-b1-02.10", t: "mc", q: "„Der Zug, der nach Ankara fährt …“", o: ["Ankara’ya giden tren", "Ankara’ya gelen tren", "Ankara’dan giden tren", "Ankara’ya gidiyor tren"], a: 0,
      why: { 1: "*gelen* = der hierher kommt, nicht „der wegfährt“.", 2: "*-dan* heißt „von“: der Zug, der **von** Ankara fährt.", 3: "Ein konjugiertes Verb darf nicht vor dem Nomen stehen." },
      e: "Ankara’ya (Richtung) + **giden** (git → gid-en) + tren." },
    { id: "tr-b1-02.11", t: "mc", q: "„der Student, der nicht gekommen ist“", o: ["gelmeyen öğrenci", "gelmiyen öğrenci", "gelen değil öğrenci", "gelmeyan öğrenci"], a: 0,
      why: { 1: "Die Verneinung ist **-mA-**: gel-me-yen (nicht -mI-).", 2: "*değil* verneint nicht ein Partizip vor dem Nomen.", 3: "Letzter Vokal von *gelme-* ist e → -yen." },
      e: "gel- + **me** + **yen** + öğrenci." },
    { id: "tr-b1-02.12", t: "mc", q: "„Beni arayan kişi kimdi?“ bedeutet …", o: ["Wer war die Person, die mich angerufen hat?", "Wen habe ich angerufen?", "Wer ruft mich an?", "Wer war die Person, die ich angerufen habe?"], a: 0,
      why: { 1: "Dann wäre „ich“ Subjekt und es hieße *aradığım kişi*.", 2: "Das Verb im Satz ist *kimdi* (war), nicht Präsens.", 3: "„die ich angerufen habe“ wäre *aradığım kişi*." },
      e: "*beni arayan kişi* = die Person, die mich angerufen hat. Die Person ist die Handelnde." },
    { id: "tr-b1-02.13", t: "order", q: "Bilde den Satz: „Die Frau, die neben mir sitzt, ist Ärztin.“", w: ["Yanımda", "oturan", "kadın", "bir", "doktor"], a: ["Yanımda oturan kadın bir doktor"],
      e: "Der ganze Relativsatz (*yanımda oturan*) steht **vor** dem Bezugswort *kadın*. Das Prädikat *bir doktor* braucht in der 3. Person keine Endung." },
    { id: "tr-b1-02.14", t: "order", q: "Bilde den Satz: „Ich suche das Restaurant, das hier in der Nähe ist.“", w: ["Buraya", "yakın", "olan", "lokantayı", "arıyorum"], a: ["Buraya yakın olan lokantayı arıyorum"],
      e: "*buraya yakın olan* (das nah bei hier ist: Adjektiv *yakın* + *olan*). Das Bezugswort *lokantayı* trägt den Akkusativ, weil es bestimmt gemeint ist." },
    { id: "tr-b1-02.15", t: "order", q: "Bilde den Satz: „Kennst du jemanden, der sehr gut Deutsch spricht?“", w: ["Çok", "iyi", "Almanca", "konuşan", "birini", "tanıyor", "musun"], a: ["Çok iyi Almanca konuşan birini tanıyor musun", "Almanca çok iyi konuşan birini tanıyor musun"],
      e: "*konuşan* steht vor *birini* (jemanden, Akkusativ). *musun* bekommt die Endung für „du“, weil das Verb in -Iyor steht." },
    { id: "tr-b1-02.16", t: "match", q: "Ordne die Wortgruppe der Bedeutung zu:", p: [["gelen adam", "der Mann, der kommt"], ["giden otobüs", "der Bus, der abfährt"], ["gelmeyen misafir", "der Gast, der nicht kommt"], ["yardım eden kişi", "die Person, die hilft"], ["yiyen çocuk", "das Kind, das isst"]],
      e: "Der Stamm bleibt gleich, nur -(y)An kommt dazu: git → gid-en, et → ed-en, ye- → yi-yen. Die Verneinung ist -mA-yAn." },
    {"id":"tr-b1-02.17","t":"cloze","q":"Ergänze das Partizip.","text":"Bahçede oyna{1} çocuklar çok mutlu. Bana yardım ed{2} komşum çok nazik biri. Dün gel{3} misafirler sabaha kadar kaldı.","gaps":{"1":{"a":["yan"],"wrong":{"an":"*oyna-* endet auf Vokal → Puffer-**y**: oyna**yan**.","yen":"Letzter Vokal von *oyna-* ist **a** → -yan.","ıyor":"Vor dem Nomen steht ein Partizip, kein konjugiertes Verb."}},"2":{"a":["en"],"wrong":{"an":"Letzter Vokal von *et-/ed-* ist **e** → -**en**.","iyor":"Ein konjugiertes Verb darf nicht vor dem Nomen stehen.","en mi":"Das wäre eine Frage."}},"3":{"a":["en"],"wrong":{"an":"Letzter Vokal von *gel-* ist **e** → -**en**.","dığı":"-DIğI würde bedeuten, dass die Misafirler Objekt sind („die er eingeladen hat“).","miş":"Das wäre „offenbar gekommen“, kein Partizip vor dem Nomen."}}},"e":"Alle drei Lücken: Stamm + -(y)An direkt vor dem Nomen. Nach Vokal Puffer-y (oyna-yan), bei *et-* wird t zu d (ed-en), Vokal e → en (gelen)."},
    {"id":"tr-b1-02.18","t":"sort","q":"Wann passt -(y)An? Bezugswort = Handelnder (-An) oder Bezugswort = Objekt/Ort (nicht -An)?","cats":["-(y)An (Bezugswort = Handelnder)","nicht -(y)An (Objekt oder Ort)"],"items":[["der Mann, der hier wohnt",0],["das Buch, das ich gelesen habe",1],["die Kinder, die spielen",0],["der Film, den wir gesehen haben",1],["die Frau, die mir geholfen hat",0],["die Stadt, in der ich geboren bin",1]],"why":{"der Mann, der hier wohnt":"Der Mann wohnt – er ist der Handelnde: burada oturan adam.","das Buch, das ich gelesen habe":"Das Buch ist Objekt, „ich“ liest: okuduğum kitap (-DIk).","die Kinder, die spielen":"Die Kinder spielen – sie handeln: oynayan çocuklar.","der Film, den wir gesehen haben":"Der Film ist Objekt: izlediğimiz film (-DIk).","die Frau, die mir geholfen hat":"Die Frau hilft – Handelnde: bana yardım eden kadın.","die Stadt, in der ich geboren bin":"Die Stadt ist ein Ort: doğduğum şehir (-DIk)."},"e":"-(y)An passt nur, wenn das Bezugswort selbst tut, was das Verb sagt („der Mann, der …“). Bei Objekten und Orten brauchst du -DIk/-(y)AcAk."},
    { id: "tr-b1-02.19", t: "listen", say: "Kapıda bekleyen adam seni arıyor.", q: "Hör zu: Wer sucht dich?",
      o: ["Der Mann, der an der Tür wartet.", "Der Mann, den du erwartest.", "Der Mann, der gleich weggeht.", "Eine Frau, die an der Tür wartet."], a: 0,
      why: { 1: "*bekleyen* = der wartet (er ist der Handelnde), nicht „den du erwartest“.", 2: "Von Weggehen ist nicht die Rede (*gitmek* kommt nicht vor).", 3: "*adam* ist ein Mann." },
      e: "„Der Mann, der an der Tür wartet, sucht dich.“ *kapıda bekleyen adam* ist das Subjekt des Satzes." },
    { id: "tr-b1-02.20", t: "dictation", say: "Dün bizi ziyaret eden komşular çok güzel pasta getirdi.", a: ["Dün bizi ziyaret eden komşular çok güzel pasta getirdi.", "Dün bizi ziyaret eden komşular çok güzel pasta getirdiler."],
      wrong: { "Dün bizi ziyaret edan komşular çok güzel pasta getirdi.": "Letzter Vokal von *et-* ist **e** → ed**en**.", "Dün bizi ziyaret ediyen komşular çok güzel pasta getirdi.": "-(y)An ist keine Form mit -iyor: ed**en**.", "Dün bizi ziyaret eden komşuler çok güzel pasta getirdi.": "Letzter Vokal von *komşu-* ist **u** → komşu**lar**." },
      e: "„Die Nachbarn, die uns gestern besucht haben, haben einen sehr leckeren Kuchen mitgebracht.“ *ziyaret etmek* → ziyaret **eden** (t → d)." },
    { id: "tr-b1-02.21", t: "speak", say: "Burada çalışan kadın benim teyzem.",
      e: "„Die Frau, die hier arbeitet, ist meine Tante.“ *çalışan*: ç wie „tsch“, ş wie „sch“, ı dumpf. *teyzem*: ey wie in „Meyer“ (e-y). Typischer Fehler: *çalischan* mit hartem „sch-an“." },
    { id: "tr-b1-02.22", t: "speak", say: "Kapıda bekleyen adamı tanıyor musun?",
      e: "„Kennst du den Mann, der an der Tür wartet?“ *bekleyen*: Betonung auf der letzten Silbe: be-kle-YEN. *adamı* mit dumpfem ı. Typischer Fehler: *musun* mit dem Ton auf -mu- statt auf der Silbe davor." },
    { id: "tr-b1-02.23", t: "speak", say: "İyi Almanca konuşan birini arıyorum.",
      e: "„Ich suche jemanden, der gut Deutsch spricht.“ *Almanca*: c wie „dsch“. *konuşan*: o kurz, ş wie „sch“. *arıyorum*: das ı dumpf, das y wie „j“." },
    { id: "tr-b1-02.24", t: "respond", say: "Sence iyi bir komşu nasıl biri olmalı?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -(y)An, um Eigenschaften zu beschreiben.",
      chunks: ["İyi bir komşu … olan biri.", "Bana yardım eden …", "Gürültü yapmayan …", "Çünkü …"],
      models: ["İyi bir komşu, sorun olduğunda yardım eden biri olmalı. Gürültü yapmayan ve selam veren insanları severim. Çünkü iyi komşu, güvenebileceğin biridir.", "Bence iyi komşu, kapıda karşılaşınca gülümseyen ve zor zamanlarda yanında olan kişidir. Gece geç saatlerde müzik dinlemeyen biri olmalı."],
      modelsN: ["Ein guter Nachbar sollte jemand sein, der hilft, wenn es ein Problem gibt. Ich mag Menschen, die keinen Lärm machen und grüßen. Denn ein guter Nachbar ist jemand, dem man vertrauen kann.", "Meiner Meinung nach ist ein guter Nachbar jemand, der lächelt, wenn man sich an der Tür trifft, und in schweren Zeiten da ist. Er sollte nicht spätabends Musik hören."],
      e: "Mit **-(y)An** beschreibst du Menschen und Dinge: yardım **eden**, yap**mayan**, söyle**yen**. Das Partizip steht **vor** dem Nomen *kişi/biri*. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-03', {
  lesson: [
    { p: "Bei „der Mann, **der** kommt“ ist das Bezugswort der Handelnde: dafür gibt es -(y)An. Bei **„das Buch, das ich gelesen habe“** oder **„die Stadt, in der ich geboren bin“** ist das Bezugswort Objekt oder Ort, und der Handelnde („ich“) steht im Relativsatz. Türkisch macht daraus ein **Partizip mit Possessiv**: der Handelnde wird zur Possessiv-Endung am Partizip: *okudu**ğum** kitap* (wörtlich „mein Gelesenes“ Buch). **-DIk** ist das Partizip für Vergangenheit und Gegenwart, **-(y)AcAk** für die Zukunft." },
    { h: "Der Bauplan: Stamm + -DIk / -(y)AcAk + Possessiv + Nomen" },
    { table: { head: ["Deutscher Relativsatz", "Bauplan", "Türkisch"], rows: [
      ["das Buch, das ich gelesen habe", "Stamm + **-DIk** + Poss.", "oku**duğum** kitap"],
      ["das Essen, das meine Mutter macht", "Gen. + Stamm + -DIk + Poss.", "annemin yap**tığı** yemek"],
      ["der Ort, zu dem wir fahren werden", "Stamm + **-(y)AcAk** + Poss.", "gid**eceğimiz** yer"],
      ["die Stadt, die ich nie gesehen habe", "Stamm + **-mA-dIk** + Poss.", "hiç gör**mediğim** şehir"]
    ] } },
    { h: "Die Possessiv-Endung zeigt, wer handelt" },
    { table: { head: ["Person", "-DIk (okumak)", "-(y)AcAk (gitmek)"], rows: [
      ["ben", "okudu**ğum**", "gidece**ğim**"],
      ["sen", "okudu**ğun**", "gidece**ğin**"],
      ["o", "okudu**ğu**", "gidece**ği**"],
      ["biz", "okudu**ğumuz**", "gidece**ğimiz**"],
      ["siz", "okudu**ğunuz**", "gidece**ğiniz**"],
      ["onlar", "okudu**kları**", "gidece**kleri**"]
    ] } },
    { p: "Der **Konsonant** wechselt: **k → ğ** vor einer Endung mit Vokal (okudu**ğ**um, gidece**ğ**imiz). Bei „sie (mehrere)“ beginnt die Endung mit l → das **k bleibt**: okudu**k**ları, gidece**k**leri. -DIk selbst: d → t nach f, s, t, k, ç, ş, h, p (*yaptığım, gittiğim, içtiğim, konuştuğum*), sonst d (*geldiğim, aldığım, okuduğum, gördüğüm*). Vokalharmonie ı/i/u/ü. Bei -(y)AcAk kommt nach Vokalstamm der Puffer-y (*söyleyeceğim*). Verneinung: **-mA-dIk** (*okumadığım*), **-mA-yAcAk** (*okumayacağım*)." },
    { p: "Steht ein Handelnder im Satz, bekommt er den **Genitiv**: *annem**in** yaptığı yemek*, *benim okuduğum kitap* (*benim* kann wegfallen). Bei Plural-Handelnden stehen beide Möglichkeiten: *öğrencilerin okuduğu / okudukları kitaplar*. Das Partizip mit Possessiv funktioniert wie ein Nomen und bekommt Kasus: *okuduğum kitabı sevdim*, *gittiğim yere*." },
    { h: "-An oder -DIk?" },
    { table: { head: ["Bezugswort ist …", "Form", "Beispiel"], rows: [
      ["der Handelnde (Subjekt)", "-(y)An", "kitabı okuyan çocuk (das Kind, das das Buch liest)"],
      ["Objekt, Ort, Zeit …", "-DIk / -(y)AcAk + Possessiv", "çocuğun okuduğu kitap (das Buch, das das Kind liest)"]
    ] } },
    { warn: "Typische Fehler: *„okudum kitap“* (finites Verb vor dem Nomen), *„benim okuyan kitap“* (-An passt nicht, wenn „ich“ liest), *„okudukum kitap“* (k wird vor Vokal zu ğ)." },
    { tip: "Gehst du vom Deutschen aus, such erst das **Bezugswort** und frage: Was macht der Relativsatz mit ihm? Handelt es selbst → -(y)An. Wird etwas **mit ihm gemacht** oder **an ihm** (Ort, Zeit) → -DIk/-(y)AcAk. Stelle dann den ganzen Relativsatz davor." },
    { ex: [
      ["Dün okuduğum kitap çok ilginçti.", "Das Buch, das ich gestern gelesen habe, war sehr interessant."],
      ["Annemin yaptığı börek çok lezzetliydi.", "Der Börek, den meine Mutter gemacht hat, war sehr lecker."],
      ["Hafta sonu gideceğimiz yeri henüz bilmiyoruz.", "Den Ort, zu dem wir am Wochenende fahren werden, kennen wir noch nicht."],
      ["Doğduğum şehir denize çok yakın.", "Die Stadt, in der ich geboren wurde, ist ganz nah am Meer."],
      ["Hiç görmediğim bir film izledim.", "Ich habe einen Film gesehen, den ich nie zuvor gesehen hatte."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-03.1", t: "gap", q: "Dün ___ kitap çok ilginçti. (okumak, ben – Das Buch, das ich gestern gelesen habe, war sehr interessant.)", a: ["okuduğum"],
      wrong: { "okuyan": "Das ist -(y)An: „das Buch, das liest“. Hier ist das Buch Objekt, „ich“ liest: -DIk + Possessiv.", "okudum": "Ein konjugiertes Verb darf nicht vor dem Nomen stehen.", "okuduğun": "-n = „du“. Hier handelt „ich“: -m.", "okudugum": "Das **ğ** (weiches g) muss geschrieben werden: okudu**ğ**um.", "okutuğum": "*oku-* endet auf Vokal → d bleibt: oku**d**uğum." },
      e: "oku- + **duk** (Vokal u → u; nach Vokal d) → k wird vor Vokal zu **ğ** + **um** = **okuduğum**." },
    { id: "tr-b1-03.2", t: "gap", q: "Annemin ___ yemek çok lezzetli. (yapmak – Das Essen, das meine Mutter macht, ist sehr lecker.)", a: ["yaptığı"],
      wrong: { "yapan": "*yapan* = „der/das macht“. Das Essen macht nicht, die Mutter macht es: -DIk + Possessiv.", "yaptığım": "-m = „ich“. Die Mutter handelt: -**ı** (3. Person).", "yapdığı": "*yap-* endet auf **p** (stimmlos) → d wird **t**: yap**tığ**ı.", "yaptıkı": "k wird vor einer Vokal-Endung zu **ğ**: yaptı**ğı**." },
      e: "yap- + **tık** (p → t) → ğ + **ı** (Possessiv, 3. Person) = **yaptığı**. Der Handelnde *annemin* steht im Genitiv." },
    { id: "tr-b1-03.3", t: "gap", q: "Hafta sonu ___ yer çok güzel. (gitmek, biz – Der Ort, zu dem wir am Wochenende fahren werden, ist sehr schön.)", a: ["gideceğimiz"],
      wrong: { "gideceğim": "-im = „ich“. Hier gehen „wir“: -imiz.", "gidecekimiz": "k wird vor einer Vokal-Endung zu **ğ**: gidece**ğ**imiz.", "gittiğimiz": "Das ist Vergangenheit („zu dem wir gefahren sind“). Der Satz spricht über die Zukunft: -(y)AcAk.", "gideceğiz": "Das ist ein Satz („wir werden fahren“), kein Partizip mit Possessiv vor dem Nomen." },
      e: "git- (t → d vor Vokal) + **ecek** → ğ + **imiz** = **gideceğimiz**. Zukunft = -(y)AcAk, Possessiv für „wir“ = -ImIz." },
    { id: "tr-b1-03.4", t: "gap", q: "Ali’nin ___ film çok güzelmiş. (izlemek – Der Film, den Ali gesehen hat, soll sehr schön sein.)", a: ["izlediği"],
      wrong: { "izleyen": "*izleyen* = „der schaut“. Ali ist der Handelnde, der Film Objekt: -DIk + Possessiv.", "izlediğin": "-n = „du“. Ali ist „er“: -i.", "izletiği": "*izle-* endet auf Vokal → d bleibt: izle**d**iği." },
      e: "izle- + **dik** → ğ + **i** = **izlediği**. Mit Genitiv: *Ali’nin izlediği film*." },
    { id: "tr-b1-03.5", t: "gap", q: "Hiç ___ şehirlere gitmek istiyorum. (görmek, ben – Ich möchte in Städte fahren, die ich noch nie gesehen habe.)", a: ["görmediğim"],
      wrong: { "görmeyen": "Das wäre „die nicht sehen“. Du selbst hast die Städte nie gesehen: -mA-dIk + Possessiv.", "görmedim": "Ein finites Verb darf nicht vor dem Nomen stehen.", "görmediğin": "-n = „du“. Es geht um „ich“: -m.", "görmeğim": "Es fehlt -dIk: gör-**me**-**diğ**-im." },
      e: "gör- + **me** + **dik** → ğ + **im** = **görmediğim**. *hiç* verstärkt die Verneinung („überhaupt noch nie“)." },
    { id: "tr-b1-03.6", t: "gap", q: "Öğrencilerin ___ kitaplar masada duruyor. (okumak – Die Bücher, die die Schüler lesen, liegen auf dem Tisch.)", a: ["okudukları", "okuduğu"],
      wrong: { "okuduğları": "Vor -lArI bleibt das **k**: okudu**k**ları (nicht ğ).", "okuyan": "*okuyan* = „die lesen“. Hier lesen die Schüler, die Bücher sind Objekt.", "okudukarı": "Die Endung ist -**ları**: okudukları." },
      e: "oku- + **duk** + **ları** (3. Person Plural) = **okudukları**. Auch *okuduğu* ist korrekt, weil der Genitiv-Plural *öğrencilerin* mit -sI stehen darf." },
    { id: "tr-b1-03.7", t: "mc", q: "„das Buch, das ich gelesen habe“", o: ["okuduğum kitap", "okuyan kitap", "okuduğu kitap", "okudum kitap"], a: 0,
      why: { 1: "*okuyan* = „das liest“. Das Buch liest nicht, ich lese es.", 2: "-ı/-i zeigt „er/sie“ als Handelnden, aber hier liest „ich“.", 3: "Ein finites Verb kann nicht vor dem Nomen stehen." },
      e: "oku- + **duğ** + **um** + kitap." },
    { id: "tr-b1-03.8", t: "mc", q: "„das Mädchen, das das Buch liest“", o: ["Kitabı okuyan kız", "Kitabı okuduğu kız", "Kitabı okuduğum kız", "Kitabı okudu kız"], a: 0,
      why: { 1: "Possessiv-Form passt, wenn das Bezugswort **nicht** der Handelnde ist; das Mädchen liest selbst.", 2: "„das Mädchen, das ich lese“? Das passt nicht.", 3: "Ein finites Verb darf nicht vor dem Nomen stehen." },
      e: "Das Mädchen ist die Handelnde → **-(y)An**: okuyan kız. Der Akkusativ (*kitabı*) bleibt am Objekt." },
    { id: "tr-b1-03.9", t: "mc", q: "„der Ort, an dem ich geboren wurde“", o: ["doğduğum yer", "doğan yer", "doğacağım yer", "doğdum yer"], a: 0,
      why: { 1: "*doğan yer* = der Ort, der geboren wird (der Ort ist Handelnder) – das ist unsinnig.", 2: "*doğacağım* = „wo ich geboren werden werde“ (Zukunft).", 3: "Ein finites Verb darf nicht vor dem Nomen stehen." },
      e: "doğ- + **duk** → ğ + **um** + yer. Ort + Possessiv." },
    { id: "tr-b1-03.10", t: "mc", q: "„das Haus, in dem wir wohnen werden“ (Zukunft)", o: ["oturacağımız ev", "oturduğumuz ev", "oturan ev", "oturacakımız ev"], a: 0,
      why: { 1: "*oturduğumuz* = in dem wir wohnen/wohnten (kein Zukunftsbezug).", 2: "*oturan* = das Haus selbst „sitzt/wohnt“ – das passt nicht.", 3: "k wird vor Vokal zu **ğ**: otura**cağ**ımız." },
      e: "otur- + **acak** → ğ + **ımız** + ev." },
    { id: "tr-b1-03.11", t: "mc", q: "„das Essen, das du gemacht hast“", o: ["senin yaptığın yemek", "senin yapan yemek", "senin yaptığı yemek", "senin yaptıkın yemek"], a: 0,
      why: { 1: "-(y)An hat keine Possessiv-Endung und passt hier nicht.", 2: "-**ı** zeigt „er/sie“, aber *senin* verlangt „du“: -**ın**.", 3: "k wird vor Vokal-Endung zu **ğ**: yaptı**ğ**ın." },
      e: "yap- + **tık** → ğ + **ın** + yemek. Das Genitiv *senin* und die Endung -n gehören zusammen." },
    { id: "tr-b1-03.12", t: "mc", q: "„alles, was ich weiß“", o: ["bildiğim her şey", "bilen her şey", "bildim her şey", "biliyor her şey"], a: 0,
      why: { 1: "*bilen* = „was weiß“ – ein Gegenstand weiß nichts.", 2: "*bildim* ist ein finites Verb und darf nicht vor dem Nomen stehen.", 3: "*biliyor* ist ebenfalls ein finites Verb; vor einem Nomen braucht man das Partizip." },
      e: "bil- + **dik** → ğ + **im** + her şey. *Bildiğim* = was ich weiß." },
    { id: "tr-b1-03.13", t: "order", q: "Bilde den Satz: „Das Essen, das meine Mutter gemacht hat, war sehr lecker.“", w: ["Annemin", "yaptığı", "yemek", "çok", "lezzetliydi"], a: ["Annemin yaptığı yemek çok lezzetliydi"],
      e: "Der Relativsatz *annemin yaptığı* steht vor *yemek*. Das Prädikat *lezzetliydi* (war lecker) ist -(y)DI am Adjektiv." },
    { id: "tr-b1-03.14", t: "order", q: "Bilde den Satz: „Ich habe den Film gesehen, den du empfohlen hast.“", w: ["Tavsiye", "ettiğin", "filmi", "izledim"], a: ["Tavsiye ettiğin filmi izledim"],
      e: "*tavsiye etmek* (empfehlen) → et + **tik** → ğ + **in** = *ettiğin* (et- endet auf t → -tIk; k wird vor Vokal zu ğ). Der Film im Akkusativ: *filmi*." },
    { id: "tr-b1-03.15", t: "order", q: "Bilde die Frage: „Gibt es einen Ort, zu dem wir am Wochenende fahren?“", w: ["Hafta", "sonu", "gideceğimiz", "bir", "yer", "var", "mı"], a: ["Hafta sonu gideceğimiz bir yer var mı"],
      e: "*gideceğimiz bir yer* = ein Ort, zu dem wir fahren werden. *var mı* bildet die Frage („Gibt es …?“)." },
    { id: "tr-b1-03.16", t: "match", q: "Wer handelt? Ordne die Form zu:", p: [["okuduğum", "(das) ich lese/gelesen habe"], ["okuduğun", "(das) du liest/gelesen hast"], ["okuduğu", "(das) er/sie liest/gelesen hat"], ["okuduğumuz", "(das) wir lesen/gelesen haben"], ["okudukları", "(das) sie (mehrere) lesen/gelesen haben"]],
      e: "Die Possessiv-Endung zeigt den Handelnden. Nur bei „sie (mehrere)“ bleibt das k (okuduk-ları), sonst wird es zu ğ." },
    {"id":"tr-b1-03.17","t":"cloze","q":"Ergänze die Possessiv-Endung.","text":"Bizim geçen yıl tatilde kaldığ{1} otel çok güzeldi. Ben orada tanıştığ{2} insanlarla hâlâ konuşuyorum. Bizim gelecek yıl gideceğ{3} yer henüz belli değil.","gaps":{"1":{"a":["ımız"],"wrong":{"ım":"-m = „ich“. Der Genitiv *Bizim* zeigt „wir“ → -**ımız**.","ı":"-ı wäre „er/sie“. Gemeint sind „wir“ (*Bizim*).","imiz":"Letzter Vokal von *kaldığ-* ist **ı** → -ımız."}},"2":{"a":["ım"],"wrong":{"ımız":"Hier handelt „ich“ (*Ben*): -ım.","ı":"-ı wäre „er/sie“.","um":"Letzter Vokal von *tanıştığ-* ist **ı** → -ım."}},"3":{"a":["imiz"],"wrong":{"im":"-im = „ich“. Der Genitiv *Bizim* zeigt „wir“ → -imiz.","i":"-i wäre „er/sie“.","ımız":"Letzter Vokal von *gideceğ-* ist **e** → -imiz mit Punkt."}}},"e":"Der Handelnde des Relativsatzes steht im Genitiv (*Bizim*, *Benim*, *annemin*), die Endung passt dazu: bizim → -ImIz, benim → -Im. Die Vokalharmonie entscheidet zwischen ı und i. Der Konsonant steht vor dem Vokal schon als ğ im Text."},
    {"id":"tr-b1-03.18","t":"sort","q":"-(y)An oder -DIk/-(y)AcAk? Ordne die deutschen Relativsätze zu.","cats":["-(y)An (Bezugswort handelt)","-DIk/-(y)AcAk + Possessiv (Objekt/Ort)"],"items":[["der Mann, der hier wohnt",0],["der Mann, den ich kenne",1],["das Kind, das schläft",0],["das Buch, das du mir gegeben hast",1],["die Stadt, in der ich geboren bin",1],["die Frau, die dort steht",0]],"why":{"der Mann, der hier wohnt":"Der Mann wohnt selbst: burada oturan adam.","der Mann, den ich kenne":"Der Mann ist Objekt, ich kenne ihn: tanıdığım adam.","das Kind, das schläft":"Das Kind schläft selbst: uyuyan çocuk.","das Buch, das du mir gegeben hast":"Das Buch ist Objekt: bana verdiğin kitap.","die Stadt, in der ich geboren bin":"Die Stadt ist ein Ort: doğduğum şehir.","die Frau, die dort steht":"Die Frau steht selbst: orada duran kadın."},"e":"Entscheidend ist das Bezugswort: Handelt es selbst → -(y)An; ist es Objekt, Ort oder Zeit → -DIk/-(y)AcAk mit Possessiv."},
    { id: "tr-b1-03.19", t: "listen", say: "Annemin yaptığı börek çok lezzetliydi.", q: "Hör zu: Was war lecker?",
      o: ["Der Börek, den Mama gemacht hat.", "Der Börek, den ich gemacht habe.", "Der Börek aus der Bäckerei.", "Die Suppe von Oma."], a: 0,
      why: { 1: "*yaptığı* = „den sie macht/gemacht hat“; für „ich“ hieße es *yaptığım*.", 2: "Gemacht hat ihn *annem* (Mama).", 3: "Es ist von *börek* die Rede, nicht von Suppe." },
      e: "„Der Börek, den meine Mutter gemacht hat, war sehr lecker.“ *annemin yaptığı börek* = Genitiv + -DIk + Possessiv der 3. Person." },
    { id: "tr-b1-03.20", t: "dictation", say: "Dün yolda konuştuğum kişi benim eski öğretmenimdi.", a: ["Dün yolda konuştuğum kişi benim eski öğretmenimdi."],
      wrong: { "Dün yolda konuşduğum kişi benim eski öğretmenimdi.": "*konuş-* endet auf **ş** (stimmlos) → d wird **t**: konuş**tuğ**um.", "Dün yolda konuştugum kişi benim eski öğretmenimdi.": "Das weiche g muss geschrieben werden: konuştu**ğ**um.", "Dün yolda konuşan kişi benim eski öğretmenimdi.": "*konuşan* = „die (dort) spricht/sprach“, die Person als Handelnde. Gemeint ist „mit der ich gesprochen habe“." },
      e: "„Die Person, mit der ich gestern auf der Straße gesprochen habe, war mein früherer Lehrer.“ Hier: konuş- + **tuk** → ğ + **um** = konuştuğum." },
    { id: "tr-b1-03.21", t: "speak", say: "Annemin yaptığı yemeği çok seviyorum.",
      e: "„Ich mag das Essen, das meine Mutter macht, sehr.“ *yaptığı*: ğ nach ı dehnt den Vokal: yap-tı-ı. *yemeği*: ğ nach e/i klingt wie ein leichtes j: ye-me-yi. Typischer Fehler: *yaptigi* mit hartem g." },
    { id: "tr-b1-03.22", t: "speak", say: "Hafta sonu gideceğimiz yeri henüz bilmiyoruz.",
      e: "„Den Ort, zu dem wir am Wochenende fahren werden, kennen wir noch nicht.“ *gideceğimiz*: c wie „dsch“, ğ nach e klingt wie ein leichtes j: gi-de-ce-yi-miz. *henüz*: ü wie in „über“. Typischer Fehler: *gideceghimiz* mit hartem g." },
    { id: "tr-b1-03.23", t: "speak", say: "Okuduğum kitap çok ilginçti.",
      e: "„Das Buch, das ich gelesen habe, war sehr interessant.“ *okuduğum*: das ğ ist stumm und macht das u lang: o-ku-du-um. *ilginçti*: g hart, ç wie „tsch“. Typischer Fehler: *okudugum* mit hartem g." },
    { id: "tr-b1-03.24", t: "respond", say: "En son okuduğun kitap ya da izlediğin film neydi?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -DIk mit Possessiv.",
      chunks: ["En son okuduğum kitap …", "Kitabın konusu …", "En çok beğendiğim yer …", "Çünkü …"],
      models: ["En son okuduğum kitap bir polisiye romandı. En çok beğendiğim yer, sonunda kimin suçlu olduğunu öğrendiğimiz bölümdü. Çünkü hiç beklemediğim bir sonuç vardı.", "En son izlediğim film bir aile komedisiydi. Beni en çok güldüren sahne, dedenin torunuyla yaptığı yarışmaydı. Arkadaşlarıma da önerdim."],
      modelsN: ["Das letzte Buch, das ich gelesen habe, war ein Krimi. Der Teil, der mir am besten gefallen hat, war der, in dem wir erfahren, wer der Täter ist. Denn es gab ein Ende, mit dem ich nicht gerechnet hatte.", "Der letzte Film, den ich gesehen habe, war eine Familienkomödie. Die Szene, die mich am meisten zum Lachen brachte, war der Wettkampf des Opas mit seinem Enkel. Ich habe ihn auch meinen Freunden empfohlen."],
      e: "Alles, was im Deutschen nach „den/das/der … ich“ kommt, steht vor dem Nomen: okudu**ğum** kitap, beğen**diğim** yer, yap**tığı** yarışma. Die Possessiv-Endung zeigt, wer handelt. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-10', {
  lesson: [
    { p: "Im Deutschen leitest du die **indirekte Rede** mit „dass“ ein („Er sagte, dass er kommt“) oder fragst indirekt mit „ob“/„wo“ („Sie fragte, ob ich komme“). Türkisch hat dafür **keinen dass-Satz**: Der Inhalt wird zu einem **Verbalnomen mit Possessiv und Akkusativ**, das vor *söylemek* (sagen), *sormak* (fragen) usw. steht: *Yarın geleceğini söyledi.* Wer handelt, zeigt die **Possessiv-Endung**." },
    { h: "Der Bauplan: Verbalnomen + Possessiv + Akkusativ + söylemek" },
    { table: { head: ["Deutsch (dass-Satz)", "Bauplan", "Türkisch"], rows: [
      ["Er sagte, dass er morgen kommt/kommen werde.", "Stamm + **-(y)AcAk** + Poss. + **-(y)I**", "Yarın gel**eceğini** söyledi."],
      ["Sie sagte, sie sei gestern gegangen.", "Stamm + **-DIk** + Poss. + -(y)I", "Dün git**tiğini** söyledi."],
      ["Das Kind sagte, es sei krank.", "Nomen/Adj. + **olduğunu**", "Hasta **olduğunu** söyledi."],
      ["Er sagte mir, ich solle kommen.", "Stamm + **-mA** + Poss. + -(y)I", "Gel**memi** söyledi."],
      ["Sie fragte mich, wo ich wohne.", "Frage + -DIk + Poss. + -(y)I + sormak", "Nerede otur**duğumu** sordu."],
      ["Sie fragte, ob ich komme.", "Stamm + **-Ip** + -mA-**dIk** + Poss.", "Gelip gel**mediğimi** sordu."]
    ] } },
    { h: "Wessen Endung? – Die des Handelnden im Nebensatz" },
    { p: "Die Possessiv-Endung zeigt immer den **Handelnden der indirekten Aussage**, nicht den Sprecher. *Ali geleceğini söyledi.* = Ali sagte, **er** (Ali) werde kommen. *Ali geleceğimi söyledi.* = Ali sagte, **ich** werde kommen. *Bana geleceğimi söyledi.* = Er sagte mir, dass ich komme." },
    { table: { head: ["gemeint", "Beispiel (Ali sagt …)"], rows: [
      ["Ali: „Ich komme.“", "Ali geleceğ**ini** söyledi."],
      ["Ali (zu mir): „Du kommst.“", "Ali geleceğ**imi** söyledi."],
      ["Ali (zu mir): „Komm!“ (Aufforderung)", "Ali gelmem**i** söyledi."],
      ["Ali: „Wir kommen.“", "Ali geleceğ**imizi** söyledi."]
    ] } },
    { p: "**Aufforderung:** -mA + Possessiv (*gelmemi söyledi*), verneint -mAmA (*gelmememi söyledi* = ich solle nicht kommen, *yememi* – *yemememi*). **Zeit:** -DIk deckt Gegenwart und Vergangenheit ab (der Zusammenhang entscheidet), -(y)AcAk die Zukunft. Es gibt keine Rückverschiebung wie im Deutschen und keinen Konjunktiv („käme“). **Im Gespräch** gibt man fremde Aussagen meist als direkte Rede mit *dedi* wieder: *Ali „Yarın gelirim“ dedi.* Die Formen auf -DIğInI sind eher schriftlich und formell." },
    { p: "**de- / ye-:** *demek* → *dediğini, diyeceğini*, *yemek* → *yediğini, yiyeceğini* (vor y wird e zu i). **Fragen:** Fragewort + -DIk: *Neden geç kaldığımı sordu.* Ja/nein-Fragen: **-Ip -mAdIk**: *Gelip gelmediğini sordu.* (ob er gekommen ist), *gelip gelmeyeceğini sordu* (ob er kommen wird)." },
    { h: "diye und göre" },
    { p: "**diye** nach einem direkten Satz: *„Gel!“ diye bağırdı.* (Er rief: Komm!) – *„Yarın gelirim“ diye söz verdi.* Außerdem für Zweck oder Sorge: *Kimse duymasın diye sessizce konuştu.* (Er sprach leise, damit niemand es hört.) *Geç kalırım diye acele ettim.* (Ich beeilte mich, weil ich fürchtete, zu spät zu kommen.) **göre** („laut“): *Ali’nin dediğine göre film çok güzel.* (Laut Ali ist der Film sehr schön.) *Duyduğuma göre …* (Wie ich höre …)." },
    { warn: "Typische Fehler: *„Ali söyledi geliyor“* (so wie im Deutschen „sagte, kommt“) – Türkisch braucht das Verbalnomen: *geleceğini söyledi*. Und: Die Endung ist **nicht** die des Sprechers. *„Geleceğimi söyledi“* heißt „ich werde kommen“ (er sagt es über mich), nicht „er kommt“." },
    { ex: [
      ["Annem hafta sonu bize geleceğini söyledi.", "Meine Mutter hat gesagt, dass sie am Wochenende zu uns kommt."],
      ["Doktor bana çok su içmemi söyledi.", "Der Arzt sagte mir, ich solle viel Wasser trinken."],
      ["Öğretmen ödevi yapıp yapmadığımı sordu.", "Der Lehrer fragte, ob ich die Hausaufgaben gemacht habe."],
      ["Ayşe’nin dediğine göre sınav çok zormuş.", "Laut Ayşe soll die Prüfung sehr schwer gewesen sein."],
      ["Geç kalırım diye taksiye bindim.", "Ich nahm ein Taxi, weil ich fürchtete, zu spät zu kommen."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-10.1", t: "gap", q: "Ali yarın ___ söyledi. (gelmek – Ali sagte, dass er morgen kommen wird.)", a: ["geleceğini"],
      wrong: { "geldiğini": "Das ist Vergangenheit („er sei gekommen“). Mit *yarın* brauchst du die Zukunft -(y)AcAk.", "geleceğimi": "-im = „ich“. Ali spricht von sich: -ini (3. Person).", "gelecekini": "k wird vor Vokal-Endung zu **ğ**: gele**ceğ**ini.", "gelecek": "Es fehlen Possessiv und Akkusativ: gelece**ğ-i-ni**." },
      e: "gel- + **ecek** → ğ + **i** (Possessiv, 3. Person) + **ni** (Akkusativ mit Puffer-n) = **geleceğini**." },
    { id: "tr-b1-10.2", t: "gap", q: "Ayşe dün akşam erken ___ söyledi. (yatmak – Ayşe sagte, sie sei gestern Abend früh schlafen gegangen.)", a: ["yattığını"],
      wrong: { "yatdığını": "*yat-* endet auf **t** (stimmlos) → d wird **t**: yat**tığ**ını.", "yattığımı": "-im = „ich“. Ayşe spricht von sich selbst: -ını (3. Person).", "yatacağını": "Das wäre Zukunft („sie werde schlafen gehen“). *dün akşam* verlangt Vergangenheit.", "yattıkını": "k wird vor Vokal-Endung zu **ğ**: yattı**ğ**ını." },
      e: "yat- + **tık** → ğ + **ı** + **nı** = **yattığını**. Zeitangabe *dün* → -DIk (Vergangenheit)." },
    { id: "tr-b1-10.3", t: "gap", q: "Çocuk hasta ___ söyledi. (olmak – Das Kind sagte, es sei krank.)", a: ["olduğunu"],
      wrong: { "oldu": "Das ist ein Satz („wurde“), kein Verbalnomen vor *söyledi*.", "olacağını": "Das hieße „es werde krank sein“ (Zukunft).", "olduğumu": "-m = „ich“. Das Kind spricht über sich: -unu (3. Person).", "olduğunı": "Letzter Vokal von *olduğ-* ist **u** → -**unu**." },
      e: "ol- + **duk** → ğ + **u** + **nu** = **olduğunu**. Wenn kein Verb im Aussagesatz steht (hasta), verwendest du *olmak* für „sein“." },
    { id: "tr-b1-10.4", t: "gap", q: "Müdür bana yarın erken ___ söyledi. (gelmek – Der Chef sagte mir, ich solle morgen früh kommen.)", a: ["gelmemi"],
      wrong: { "geleceğimi": "Das wäre eine Aussage („ich werde kommen“), keine Aufforderung. Eine Aufforderung wird mit -mA + Possessiv gebildet.", "gelmeni": "-n = „du“. Du sollst nicht kommen, **ich** soll kommen.", "gelmek": "Der Infinitiv sagt nicht, **wer** kommen soll.", "gelmemizi": "-miz = „wir“. Gemeint ist „ich“." },
      e: "gel- + **me** + **m** (ich) + **i** (Akkusativ) = **gelmemi**. Aufforderung in der indirekten Rede = -mA + Possessiv + Akkusativ." },
    { id: "tr-b1-10.5", t: "gap", q: "Doktor bana şeker ___ söyledi. (yemek – Der Arzt sagte mir, ich solle keinen Zucker essen.)", a: ["yemememi"],
      wrong: { "yememi": "Das ist die positive Aufforderung („ich soll essen“). Für „nicht“ brauchst du zweimal -me-: ye-**me**-**me**-m-i.", "yemeyeceğimi": "Das wäre eine Aussage („ich werde nicht essen“). Es geht um eine Aufforderung.", "yemememizi": "-miz = „wir“. Gemeint ist „ich“.", },
      e: "ye- + **me** (Verneinung) + **me** (-mA des Verbalnomens) + **m** + **i** = **yemememi**. Zweimal „me“: einmal verneint, einmal bildet es das Verbalnomen." },
    { id: "tr-b1-10.6", t: "gap", q: "Öğretmen bana nerede ___ sordu. (oturmak – Der Lehrer fragte mich, wo ich wohne.)", a: ["oturduğumu"],
      wrong: { "oturduğunu": "-unu = „er/sie“. Gefragt wird nach „mir“: -umu.", "oturan": "*oturan* = „der wohnt“, kein Fragesatz mit Possessiv.", "oturdum": "Das ist ein Satz („ich wohnte“), kein Verbalnomen vor *sordu*.", "oturtuğumu": "*otur-* endet auf **r** (stimmhaft) → d bleibt: otur**duğ**umu." },
      e: "otur- + **duk** → ğ + **um** + **u** = **oturduğumu**. Fragewort (*nerede*) + Verbalnomen + sormak." },
    { id: "tr-b1-10.7", t: "mc", q: "„Er sagt, dass er morgen kommt.“", o: ["Yarın geleceğini söylüyor.", "Yarın geleceğimi söylüyor.", "Yarın gelecek söylüyor.", "Yarın geldiğini söylüyor."], a: 0,
      why: { 1: "-im = „ich“: „er sagt, dass ich komme“.", 2: "Das Verbalnomen braucht Possessiv und Akkusativ: gelece**ği-ni**.", 3: "*geldiğini* = „dass er gekommen ist“ (Vergangenheit)." },
      e: "gel- + **eceğ** + **i** + **ni** + söylüyor." },
    { id: "tr-b1-10.8", t: "mc", q: "„Sie fragte mich, ob ich Hunger habe.“", o: ["Aç olup olmadığımı sordu.", "Aç olup olmadığını sordu.", "Aç olmak sordu.", "Aç olup olmadım sordu."], a: 0,
      why: { 1: "-ını = „er/sie“. Gefragt wird, ob „ich“ Hunger habe: -ımı.", 2: "Der Infinitiv sagt nicht, **wer** Hunger hat.", 3: "-dım ist ein finites Verb. Vor *sordu* braucht man das Verbalnomen mit Akkusativ." },
      e: "aç ol-**up** ol-**ma-dık** → ğ + **ım** + **ı** = **aç olup olmadığımı**. Ja/nein-Frage = -Ip -mAdIk." },
    { id: "tr-b1-10.9", t: "mc", q: "„Ali sagte, ich solle kommen.“", o: ["Ali gelmemi söyledi.", "Ali geleceğimi söyledi.", "Ali gelmeni söyledi.", "Ali gelmek söyledi."], a: 0,
      why: { 1: "*geleceğimi* = „dass ich komme/kommen werde“ (Aussage), keine Aufforderung.", 2: "-n = „du“. Gemeint ist „ich“.", 3: "Der Infinitiv sagt nicht, wer kommen soll." },
      e: "Aufforderung = -mA + Possessiv + Akkusativ: gel-**me-m-i**." },
    { id: "tr-b1-10.10", t: "mc", q: "„Laut Ayşe ist der Film langweilig.“", o: ["Ayşe’nin dediğine göre film sıkıcı.", "Ayşe’nin dediği göre film sıkıcı.", "Ayşe dediğine göre film sıkıcı.", "Ayşe’nin dedi göre film sıkıcı."], a: 0,
      why: { 1: "*göre* verlangt den Dativ: dedi**ğine**.", 2: "Der Handelnde im Verbalnomen steht im Genitiv: Ayşe**’nin**.", 3: "Ein finites Verb (*dedi*) kann nicht vor *göre* stehen." },
      e: "Ayşe’nin (Genitiv) + de- + **diğ** + **i** + **ne** (Dativ) + **göre**." },
    { id: "tr-b1-10.11", t: "mc", q: "Was bedeutet: *Kimse duymasın diye sessizce konuştu.*", o: ["Er sprach leise, damit niemand es hört.", "Er sprach leise, weil niemand es hörte.", "Er sagte, niemand höre ihn.", "Er sprach leise, nachdem niemand es gehört hatte."], a: 0,
      why: { 1: "*duymasın* ist der Wunsch/Imperativ („niemand soll hören“), kein Bericht über Vergangenes.", 2: "Dafür bräuchte man ein Verbalnomen mit *söylemek*.", 3: "*diye* hier nennt den Zweck, keine Zeit." },
      e: "**-sIn diye** = damit (er/sie/es …). Zweck oder Sorge nennst du mit *diye*." },
    { id: "tr-b1-10.12", t: "mc", q: "Ali sagte zu mir: „Ich bin nicht krank.“ Wie gibst du das wieder?", o: ["Ali hasta olmadığını söyledi.", "Ali hasta değilim söyledi.", "Ali hasta değil söyledi.", "Ali hasta olmadığımı söyledi."], a: 0,
      why: { 1: "Vor *söyledi* braucht man ein Verbalnomen mit Akkusativ.", 2: "*değil* kann nicht direkt vor *söyledi* stehen.", 3: "-ımı = „ich“. Ali spricht über sich selbst: -ını." },
      e: "ol- + **ma** + **dık** → ğ + **ı** + **nı** = **olmadığını**." },
    { id: "tr-b1-10.13", t: "order", q: "Bilde den Satz: „Meine Mutter sagte, dass sie morgen kommen wird.“", w: ["Annem", "yarın", "geleceğini", "söyledi"], a: ["Annem yarın geleceğini söyledi", "Yarın annem geleceğini söyledi"],
      e: "Subjekt – Zeit – Verbalnomen – *söyledi* am Ende. *geleceğini* trägt Possessiv und Akkusativ." },
    { id: "tr-b1-10.14", t: "order", q: "Bilde den Satz: „Der Lehrer fragte, ob ich die Hausaufgaben gemacht habe.“", w: ["Öğretmen", "ödevi", "yapıp", "yapmadığımı", "sordu"], a: ["Öğretmen ödevi yapıp yapmadığımı sordu"],
      e: "*yapıp yapmadığımı* = „ob ich gemacht habe oder nicht“ (-Ip -mAdIk + Possessiv + Akkusativ). *sordu* steht am Ende." },
    { id: "tr-b1-10.15", t: "order", q: "Bilde den Satz: „Er sagte mir, ich solle nicht laut sprechen.“", w: ["Bana", "yüksek", "sesle", "konuşmamamı", "söyledi"], a: ["Bana yüksek sesle konuşmamamı söyledi"],
      e: "*konuş-ma-ma-m-ı*: zweimal „ma“ (Verneinung + Verbalnomen), dann Possessiv (ich) und Akkusativ. *yüksek sesle* = laut." },
    { id: "tr-b1-10.16", t: "match", q: "Ordne die direkte Rede der indirekten Rede zu:", p: [["Ali: „Hastayım.“", "hasta olduğunu söyledi"], ["Ali: „Geleceğim.“", "geleceğini söyledi"], ["Ali: „Geldim.“", "geldiğini söyledi"], ["Ali zu mir: „Gel!“", "gelmemi söyledi"], ["Ali zu mir: „Gelme!“", "gelmememi söyledi"]],
      e: "Aussage: -DIğInI / -(y)AcAğInI / olduğunu. Aufforderung: -mAmI, verneint -mAmAmI. Die Endung zeigt den Handelnden." },
    {"id":"tr-b1-10.17","t":"cloze","q":"Ergänze die indirekte Rede.","text":"Dün Ayşe beni aradı. Hafta sonu taşın{1} söyledi. Bana da yardım et{2} söyledi. Ben de hasta ol{3} söyledim.","gaps":{"1":{"a":["acağını"],"wrong":{"acağımı":"-ımı = „ich“. Ayşe spricht von sich: -ını (3. Person).","dığını":"Das wäre Vergangenheit („sie sei umgezogen“). *Hafta sonu* ist Zukunft.","acakını":"k wird vor Vokal zu **ğ**: -aca**ğ**ını."}},"2":{"a":["memi"],"wrong":{"meni":"-n = „du“. Ayşe sagte mir: **ich** soll helfen: -mem-i.","mek":"Der Infinitiv sagt nicht, wer helfen soll.","eceğimi":"Das wäre „dass ich helfen werde“ (Aussage), keine Aufforderung."}},"3":{"a":["duğumu","acağımı"],"wrong":{"duğunu":"-unu = „er/sie“. Hier spricht „ich“ über sich: -umu.","dum":"-dum ist ein finites Verb. Vor *söyledim* braucht man das Verbalnomen mit Akkusativ."}}},"e":"Drei Möglichkeiten in einem Text: Zukunft (taşın-acağ-ını), Aufforderung (et-me-m-i), Zustand (ol-duğ-um-u oder ol-acağ-ım-ı, je nach Sinn). Die Endung zeigt immer den Handelnden der indirekten Aussage."},
    {"id":"tr-b1-10.18","t":"sort","q":"Aussage oder Aufforderung? Ordne die deutschen Sätze zu.","cats":["Aussage (-DIğInI / -(y)AcAğInI)","Aufforderung (-mA + Possessiv: gelmemi/gelmesini)"],"items":[["Er sagte, dass er müde ist.",0],["Sie sagte mir, ich solle warten.",1],["Der Arzt sagte, ich solle mehr Wasser trinken.",1],["Mein Bruder sagte, er werde morgen kommen.",0],["Sie sagte, sie habe es vergessen.",0],["Der Lehrer sagte uns, wir sollen leise sein.",1]],"why":{"Er sagte, dass er müde ist.":"Eine Tatsache: yorgun olduğunu söyledi.","Sie sagte mir, ich solle warten.":"Eine Aufforderung: beklememi söyledi.","Der Arzt sagte, ich solle mehr Wasser trinken.":"Eine Aufforderung: daha çok su içmemi söyledi.","Mein Bruder sagte, er werde morgen kommen.":"Eine Aussage: yarın geleceğini söyledi.","Sie sagte, sie habe es vergessen.":"Eine Aussage: unuttuğunu söyledi.","Der Lehrer sagte uns, wir sollen leise sein.":"Eine Aufforderung: sessiz olmamızı söyledi."},"e":"„Solle/sollen“ = Aufforderung → -mA + Possessiv. Alles andere (ist, hat, wird) = Aussage → -DIğInI / -(y)AcAğInI."},
    { id: "tr-b1-10.19", t: "listen", say: "Öğretmen bana yarın erken gelmemi söyledi.", q: "Hör zu: Was hat der Lehrer gesagt?",
      o: ["Ich soll morgen früh kommen.", "Er kommt morgen früh.", "Ich soll morgen spät kommen.", "Wir sollen heute früh gehen."], a: 0,
      why: { 1: "*gelmemi* heißt „dass ich komme/kommen soll“ (Aufforderung), nicht „er kommt“.", 2: "*erken* heißt „früh“, nicht „spät“.", 3: "*yarın* heißt „morgen“, nicht „heute“; und es geht ums Kommen." },
      e: "„Der Lehrer sagte mir, ich solle morgen früh kommen.“ *gelmemi* = gel-me-m-i: Aufforderung, Handelnder „ich“." },
    { id: "tr-b1-10.20", t: "dictation", say: "Annem hafta sonu bize geleceğini söyledi.", a: ["Annem hafta sonu bize geleceğini söyledi."],
      wrong: { "Annem hafta sonu bize geleceğimi söyledi.": "-imi = „ich“. Die Mutter spricht von sich: -ini.", "Annem hafta sonu bize gelecekini söyledi.": "k wird vor Vokal zu **ğ**: gele**ceğ**ini.", "Annem hafta sonu bize geliceğini söyledi.": "Letzter Vokal von *gel-* ist **e** → -**ecek**, nicht -icek." },
      e: "„Meine Mutter sagte, dass sie am Wochenende zu uns kommt.“ Zukunft + 3. Person + Akkusativ: gel + eceğ + i + ni." },
    { id: "tr-b1-10.21", t: "speak", say: "Ali bana yarın geleceğini söyledi.",
      e: "„Ali sagte mir, dass er morgen kommt.“ *geleceğini*: c wie „dsch“, ğ nach e klingt wie ein leichtes j: ge-le-ce-yi-ni. *söyledi*: ö wie in „schön“. Typischer Fehler: *geleceghini* mit hartem g." },
    { id: "tr-b1-10.22", t: "speak", say: "Doktor çok su içmemi söyledi.",
      e: "„Der Arzt sagte, ich solle viel Wasser trinken.“ *içmemi*: iç-me-mi, ç wie „tsch“, beide m getrennt gesprochen. Typischer Fehler: *içme mi* als Frage zerlegen – es ist ein einziges Wort." },
    { id: "tr-b1-10.23", t: "speak", say: "Öğretmen ödevi yapıp yapmadığımı sordu.",
      e: "„Der Lehrer fragte, ob ich die Hausaufgaben gemacht habe.“ *yapıp yapmadığımı*: das ğ ist stumm: yap-ma-dı-ı-mı. *ödevi*: ö wie in „schön“, v wie w. Typischer Fehler: *yapmadighimi* mit hartem g." },
    { id: "tr-b1-10.24", t: "respond", say: "Dün biri sana önemli bir şey söyledi. Ne söyledi?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze die indirekte Rede mit söylemek, sormak und diye.",
      chunks: ["… bana … söyledi.", "Bana … -mAmI söyledi.", "Ben de … diye düşündüm.", "Sonra …"],
      models: ["Arkadaşım bana yeni bir işe başlayacağını söyledi. Ben de ona çok sevindiğimi söyledim. Sonra bana yeni ofisini gezdireceğini söyledi.", "Annem dün bana hafta sonu gelmemi söyledi. Evde bir şey olduğunu sandım. Meğer sadece birlikte yemek yemek istiyormuş."],
      modelsN: ["Mein Freund sagte mir, dass er eine neue Stelle antreten wird. Ich sagte ihm, dass ich mich sehr freue. Dann sagte er mir, dass er mir sein neues Büro zeigen wird.", "Meine Mutter sagte mir gestern, ich solle am Wochenende kommen. Ich dachte, zu Hause sei etwas passiert. Wie sich herausstellte, wollte sie nur zusammen essen."],
      e: "Bei **Aussagen** nimmst du -DIğInI/-(y)AcAğInI: *başlayacağını söyledi*, *sevindiğimi söyledim*. Bei **Aufforderungen** -mAmI: *gelmemi söyledi*. Mit *Meğer … -mIş* kannst du Überraschung zeigen. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-08', {
  lesson: [
    { p: "Im Deutschen leitest du einen Nebensatz mit „während“ oder „als“ ein: „**Während** ich nach Hause ging, rief er an“, „**Als** ich Kind war, …“. Türkisch nimmt dafür keinen Nebensatz mit Konjunktion, sondern hängt **-(y)ken** direkt an das Wort: *Eve **giderken** beni aradı.* Der Nebensatz wird zu einer Verbform, die **Gleichzeitigkeit** ausdrückt." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutscher Nebensatz", "Bauplan", "Türkisch"], rows: [
      ["Während ich nach Hause gehe, …", "Aorist (-Ir/-Ar) + **-ken**", "eve gid**erken**"],
      ["Während ich esse, …", "Stamm + -Ir/-Ar + -ken", "yemek y**erken**"],
      ["Während er arbeitet / gerade arbeitet, …", "Stamm + -Iyor + **-ken**", "çalış**ıyorken**"],
      ["Als ich Kind war, … / Solange ich krank bin, …", "Nomen/Adjektiv + **-(y)ken**", "çocuk**ken**, hasta**yken**"],
      ["Während er nicht zu Hause ist, …", "Nomen + **değilken** / Verb: -mAz-ken", "evde değil**ken** / evde yok**ken**, gel**mezken**"]
    ] } },
    { p: "**-ken ändert sich nie**: keine Vokalharmonie, keine Person, keine Zeit. Die Zeit liefert das Verb im Hauptsatz. Am häufigsten steht -ken hinter dem **Aorist** (*gelirken, yaparken, okurken, çalışırken*), dazu gehören alle Besonderheiten des Aorists: *gitmek* → *giderken* (t → d), *yemek* → *yerken*, *almak* → *alırken* (eines der 13 einsilbigen Verben mit -Ir). Nach **Vokal** steht beim Nomen der Puffer-**y**: *hasta**yken**, evde**yken**, öğrenci**yken**, genç**ken**, çocuk**ken**." },
    { p: "Neben dem Aorist geht auch **-Iyor** (*eve gidiyorken*): Das klingt aber betonter und ist seltener als *giderken*. Für „Als ich Kind war“ benutzt du das Nomen: nach Konsonant direkt (*çocukken, gençken, küçükken*), nach Vokal mit Puffer-y (*öğrenciyken, hastayken*), ohne Personalendung: Die Person steht im Hauptsatz. Für „nicht zu Hause“ ist *evde yokken* die häufigste Form (*evde değilken* geht auch)." },
    { warn: "Typische Fehler: *„gidiken“* (-ken braucht erst den Aorist: gid**er**ken), *„hastaken“* (nach Vokal braucht -ken den Puffer-y: hasta**yken**), *„çocukyken“* (nach Konsonant kein y: çocukken) und *„gelirkan“* (-ken bleibt immer -ken, keine Harmonie)." },
    { tip: "Meist hat der -ken-Satz **dasselbe Subjekt** wie der Hauptsatz (*Yürürken müzik dinliyorum.*). Wechselt das Subjekt, setzt du es ausdrücklich dazu: *Ben duş alırken telefon çaldı.* (Während ich duschte, klingelte das Telefon.)" },
    { tip: "-ken sagt **gleichzeitig**: *Eve girerken* = beim Hineingehen. Für **nacheinander** („sobald/als ich hineinkam“) nimmst du später -(y)IncA oder -DIğIndA." },
    { ex: [
      ["Yolda yürürken eski bir arkadaşımla karşılaştım.", "Während ich die Straße entlangging, bin ich einem alten Freund begegnet."],
      ["Yemek yerken televizyon izlemeyi sevmem.", "Beim Essen sehe ich nicht gern fern."],
      ["Çocukken her yaz denize giderdik.", "Als Kinder fuhren wir jeden Sommer ans Meer."],
      ["Hastayken dinlenmek en iyisi.", "Wenn man krank ist, ist Ausruhen das Beste."],
      ["Ben duş alırken telefon çaldı.", "Während ich duschte, klingelte das Telefon."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-08.1", t: "gap", q: "Eve ___ markete uğradım. (gitmek – Auf dem Heimweg, während ich nach Hause ging, bin ich beim Markt vorbeigegangen.)", a: ["giderken", "gidiyorken"],
      wrong: { "gitirken": "t wird vor einem **Vokal** zu d: gid-er-ken. Der Aorist von *gitmek* heißt *gider*.", "giderkan": "-ken ändert sich nie. Es gibt keine Vokalharmonie: gider**ken**.", "gidince": "-(y)IncA meint „sobald/als ich ankam“ – hinterher, nicht gleichzeitig.", "gittiken": "Vor -ken steht der Aorist (-Ir/-Ar) oder -Iyor, nie -DI." },
      e: "git- → gid- + **er** (Aorist) + **ken** = **giderken**. Auch *gidiyorken* ist möglich, klingt aber betonter." },
    { id: "tr-b1-08.2", t: "gap", q: "Yemek ___ televizyon izleme. (yemek – Schau nicht fern, während du isst.)", a: ["yerken", "yiyorken"],
      wrong: { "yiyerken": "Der Aorist von *yemek* ist *yer* (nicht yiyer): y**er**ken.", "yeken": "Es fehlt das **-r** des Aorists: ye-**r**-ken.", "yemekken": "Nach dem Infinitiv steht nicht -ken. Du brauchst den Aorist: yerken.", "yedikken": "-ken verbindet sich nicht mit -DIk." },
      e: "ye- + **r** (Aorist nach Vokal) + **ken** = **yerken**. Der Aorist von *yemek* ist *yer*, daher *yerken*." },
    { id: "tr-b1-08.3", t: "gap", q: "___ çok yaramazdım. (çocuk – Als Kind war ich sehr unartig.)", a: ["Çocukken"],
      wrong: { "Çocukyken": "*çocuk* endet auf Konsonant k → kein Puffer-y: çocuk**ken**.", "Çocuğken": "k wird nur vor einer Endung mit Vokal zu ğ. Hier beginnt -ken mit k: çocuk**ken**.", "Çocukkan": "-ken ändert sich nie.", "Çocukdu": "Das wäre „war ein Kind“ (-(y)DI), nicht „als Kind“." },
      e: "çocuk + **ken** = **çocukken**. Bei Nomen und Adjektiven hängt -ken direkt dran, ohne Personalendung." },
    { id: "tr-b1-08.4", t: "gap", q: "Hasta___ işe gitme. (Geh nicht zur Arbeit, solange du krank bist.)", a: ["yken"],
      wrong: { "ken": "*hasta* endet auf Vokal → der Puffer-**y** ist nötig: hasta**yken**.", "ykan": "-ken ändert sich nie (kein -kan).", "yiken": "Die Form heißt -(y)ken, nicht -yiken." },
      e: "hasta + **y** + **ken** = **hastayken**. Nach Vokal immer Puffer-y." },
    { id: "tr-b1-08.5", t: "gap", q: "Ben duş ___ telefon çaldı. (almak – Während ich duschte, klingelte das Telefon.)", a: ["alırken", "alıyorken"],
      wrong: { "alarken": "*almak* gehört zu den einsilbigen Verben mit **-Ir**: al**ır**, nicht alar.", "aldıken": "Vor -ken steht nie -DI, sondern Aorist oder -Iyor.", "alırkan": "-ken ändert sich nie." },
      e: "al- + **ır** + **ken** = **alırken**. Das Subjekt wechselt (*Ben … telefon*), deshalb steht *Ben* ausdrücklich im Satz." },
    { id: "tr-b1-08.6", t: "gap", q: "Henüz genç___ çok seyahat ettim. (Als ich noch jung war, bin ich viel gereist.)", a: ["ken"],
      wrong: { "yken": "*genç* endet auf Konsonant ç → kein Puffer-y: genç**ken**.", "kan": "-ken ändert sich nie." },
      e: "genç + **ken** = **gençken**. Nach Konsonant steht -ken ohne y." },
    { id: "tr-b1-08.7", t: "mc", q: "„Während ich frühstücke, höre ich Radio.“", o: ["Kahvaltı yaparken radyo dinlerim.", "Kahvaltı yaptıkça radyo dinlerim.", "Kahvaltı yapınca radyo dinlerim.", "Kahvaltı yaparkan radyo dinlerim."], a: 0,
      why: { 1: "-DIkçA heißt „je mehr / immer wenn“, nicht „während“.", 2: "-(y)IncA meint „sobald ich gefrühstückt habe“ – danach, nicht gleichzeitig.", 3: "-ken hat keine Vokalharmonie: yapar**ken**." },
      e: "yap- + **ar** + **ken**. Aorist + -ken = Gleichzeitigkeit." },
    { id: "tr-b1-08.8", t: "mc", q: "„Als ich Student war, wohnte ich in Izmir.“", o: ["Öğrenciyken İzmir’de yaşıyordum.", "Öğrenciken İzmir’de yaşıyordum.", "Öğrenci olunca İzmir’de yaşıyordum.", "Öğrenciydi İzmir’de yaşıyordum."], a: 0,
      why: { 1: "*öğrenci* endet auf Vokal i → Puffer-**y**: öğrenci**yken**.", 2: "*olunca* = „sobald ich Student wurde“ – ein Zeitpunkt, kein Zeitraum.", 3: "*öğrenciydi* ist ein finites Verb („war Student“) und kann keinen Nebensatz bilden." },
      e: "öğrenci + **y** + **ken**. „Als ich … war“ bei Nomen = -(y)ken." },
    { id: "tr-b1-08.9", t: "mc", q: "„Wenn ich Auto fahre, höre ich Musik.“ (während des Fahrens)", o: ["Araba sürerken müzik dinlerim.", "Araba sürerkan müzik dinlerim.", "Araba sürmekken müzik dinlerim.", "Araba sürüken müzik dinlerim."], a: 0,
      why: { 1: "-ken hat nur diese eine Form.", 2: "Nach -ken steht der Aorist, nicht der Infinitiv.", 3: "Der Aorist von *sürmek* ist *sürer*, nicht sürür: sür**er**ken." },
      e: "sür- + **er** (Aorist von *sürmek*) + **ken** = **sürerken**." },
    { id: "tr-b1-08.10", t: "mc", q: "Was bedeutet: *Ben yemek yaparken çocuklar bahçede oynuyordu.*", o: ["Während ich kochte, spielten die Kinder im Garten.", "Nachdem ich gekocht hatte, spielten die Kinder im Garten.", "Ich kochte, damit die Kinder im Garten spielen.", "Weil ich kochte, spielten die Kinder im Garten."], a: 0,
      why: { 1: "-ken zeigt Gleichzeitigkeit, nicht die Reihenfolge „danach“.", 2: "Für „damit“ nimmt man *diye* oder *için*.", 3: "-ken nennt keinen Grund, nur gleichzeitiges Geschehen." },
      e: "Zwei Handlungen mit verschiedenen Subjekten laufen gleichzeitig: Subjekt ausdrücklich (*Ben …, çocuklar …*)." },
    { id: "tr-b1-08.11", t: "mc", q: "„Während er nicht zu Hause ist, …“", o: ["evde değilken", "evde değilkan", "evde değilyken", "evde olmadıken"], a: 0,
      why: { 1: "-ken ändert sich nie (kein -kan).", 2: "*değil* endet auf Konsonant l → kein Puffer-y.", 3: "-DI kann nicht mit -ken verbunden werden." },
      e: "evde + **değil** + **ken** = **evde değilken**." },
    { id: "tr-b1-08.12", t: "mc", q: "Was ist der Unterschied zwischen *Eve girerken* und *Eve girince*?", o: ["girerken = während des Hineingehens; girince = sobald man drin ist", "Es gibt keinen Unterschied.", "girerken = danach; girince = vorher", "girince = während des Hineingehens"], a: 0,
      why: { 1: "Es gibt einen Unterschied: -ken = gleichzeitig, -(y)IncA = nacheinander.", 2: "Vertauscht: -ken ist gleichzeitig, nicht „danach“.", 3: "Vertauscht: das ist -ken, nicht -(y)IncA." },
      e: "-ken = Gleichzeitigkeit; -(y)IncA = Folge („sobald“). Mehr dazu im Thema über „wenn/als“." },
    { id: "tr-b1-08.13", t: "order", q: "Bilde den Satz: „Auf dem Heimweg höre ich Musik.“ (während ich nach Hause gehe)", w: ["Eve", "giderken", "müzik", "dinlerim"], a: ["Eve giderken müzik dinlerim", "Müzik eve giderken dinlerim"],
      e: "Nebensatz mit *giderken* steht vor dem Hauptverb. Das Verb *dinlerim* bleibt am Ende." },
    { id: "tr-b1-08.14", t: "order", q: "Bilde den Satz: „Als Kind habe ich viel Fußball gespielt.“", w: ["Çocukken", "çok", "futbol", "oynardım"], a: ["Çocukken çok futbol oynardım", "Çocukken futbol çok oynardım"],
      e: "*çocukken* (als Kind) steht am Anfang. *oynardım* ist -(I)rdI (Gewohnheit in der Vergangenheit)." },
    { id: "tr-b1-08.15", t: "order", q: "Bilde den Satz: „Als meine Mutter krank war, bin ich nicht zur Arbeit gegangen.“", w: ["Annem", "hastayken", "ben", "işe", "gitmedim"], a: ["Annem hastayken ben işe gitmedim", "Ben annem hastayken işe gitmedim"],
      e: "Zwei verschiedene Subjekte: *Annem hastayken* (Mama war krank) und *ben*. Das Subjekt steht beim -ken-Satz ausdrücklich da." },
    { id: "tr-b1-08.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["çocukken", "als Kind"], ["yemek yerken", "beim Essen"], ["evdeyken", "während man zu Hause ist"], ["yürürken", "beim Gehen"], ["hastayken", "solange man krank ist"]],
      e: "-ken hängt direkt an Nomen/Adjektiv (çocuk-ken), nach Vokal mit Puffer-y (evde-yken, hasta-yken); bei Verben hinter dem Aorist (yer-ken, yürür-ken)." },
    {"id":"tr-b1-08.17","t":"cloze","q":"Ergänze -ken.","text":"Ben okula gid{1} arkadaşımla konuştum. Annem yemek yap{2} radyo dinliyor. Çocuk{3} çok yaramazdım.","gaps":{"1":{"a":["erken","iyorken"],"wrong":{"arken":"Letzter Vokal von *gid-* ist **i** → -**er**ken (e-Aorist).","ken":"Vor -ken fehlt der Aorist: gid-**er**-ken.","dikken":"Vor -ken steht nie -DIk."}},"2":{"a":["arken","ıyorken"],"wrong":{"erken":"Letzter Vokal von *yap-* ist **a** → yap**ar**ken.","ırken":"Der Aorist von *yapmak* heißt *yapar* (nicht yapır).","ken":"Vor -ken fehlt der Aorist: yap-**ar**-ken."}},"3":{"a":["ken"],"wrong":{"yken":"*çocuk* endet auf Konsonant → kein Puffer-y.","kan":"-ken ändert sich nie.","ta":"Das wäre ein Kasus (Lokativ), nicht „als Kind“."}}},"e":"Verb + Aorist + -ken (gid-er-ken, yap-ar-ken). Nomen + -ken direkt (çocuk-ken). Die Form -ken bleibt immer gleich."},
    {"id":"tr-b1-08.18","t":"sort","q":"Gleichzeitig (-(y)ken) oder nacheinander (nicht -ken)? Ordne die deutschen Sätze zu.","cats":["gleichzeitig (-(y)ken)","nacheinander (nicht -ken)"],"items":[["Ich höre Musik, während ich koche.",0],["Als ich ankam, war er schon weg.",1],["Als Kind war ich oft krank.",0],["Nachdem er gegessen hatte, ging er schlafen.",1],["Während wir spazieren gingen, begann es zu regnen.",0],["Sobald sie ankommt, ruft sie an.",1]],"why":{"Ich höre Musik, während ich koche.":"Beides läuft zugleich: yemek yaparken müzik dinliyorum.","Als ich ankam, war er schon weg.":"Erst war er weg, dann kam ich: eine Reihenfolge, kein -ken.","Als Kind war ich oft krank.":"Ein Zeitraum: çocukken sık sık hastaydım.","Nachdem er gegessen hatte, ging er schlafen.":"Hintereinander: yemek yedikten sonra yattı.","Während wir spazieren gingen, begann es zu regnen.":"Gleichzeitig: yürürken yağmur başladı.","Sobald sie ankommt, ruft sie an.":"Erst ankommen, dann anrufen: -(y)IncA."},"e":"-ken = zwei Dinge geschehen **zugleich**. Folgt eine Handlung auf die andere, brauchst du eine andere Form."},
    { id: "tr-b1-08.19", t: "listen", say: "Yolda yürürken eski bir arkadaşımla karşılaştım.", q: "Hör zu: Wo traf die Person ihren alten Freund?",
      o: ["Beim Gehen auf der Straße.", "Im Café.", "Bei sich zu Hause.", "Im Bus."], a: 0,
      why: { 1: "Von einem Café ist nicht die Rede.", 2: "*yolda* heißt „auf dem Weg/auf der Straße“, nicht zu Hause.", 3: "Vom Bus ist nicht die Rede." },
      e: "„Während ich auf der Straße ging, bin ich einem alten Freund begegnet.“ *yürürken* = beim Gehen (yürü- + r + ken)." },
    { id: "tr-b1-08.20", t: "dictation", say: "Hastayken işe gitmek istemedim, ama çalışmam gerekiyordu.", a: ["Hastayken işe gitmek istemedim, ama çalışmam gerekiyordu."],
      wrong: { "Hastaken işe gitmek istemedim, ama çalışmam gerekiyordu.": "*hasta* endet auf Vokal → Puffer-**y**: hasta**yken**.", "Hastayken işe gitmek istemedim, ama çalışmem gerekiyordu.": "Letzter Vokal von *çalış-* ist **ı** → çalış**mam** (a).", "Hastayken işe gitmek istemedim, ama çalışmam gerekiyor.": "Der Satz steht in der Vergangenheit: gerek**iyordu**." },
      e: "„Als ich krank war, wollte ich nicht zur Arbeit gehen, aber ich musste arbeiten.“ *hastayken* = hasta + y + ken." },
    { id: "tr-b1-08.21", t: "speak", say: "Eve giderken markete uğradım.",
      e: "„Auf dem Heimweg bin ich beim Markt vorbeigegangen.“ *giderken*: g wie im Deutschen, r gerollt. *markete*: e kurz am Ende. *uğradım*: ğ nach u dehnt den Vokal: u-ra-dım. Typischer Fehler: *gitirken* mit t statt d." },
    { id: "tr-b1-08.22", t: "speak", say: "Çocukken her yaz denize giderdik.",
      e: "„Als Kinder fuhren wir jeden Sommer ans Meer.“ *çocukken*: ç wie „tsch“, kk deutlich zwei k. *giderdik*: g wie in „gehen“. Typischer Fehler: *çocuken* mit nur einem k." },
    { id: "tr-b1-08.23", t: "speak", say: "Yemek yerken televizyon izlemeyi sevmem.",
      e: "„Beim Essen sehe ich nicht gern fern.“ *yerken*: y wie „j“, r gerollt. *sevmem*: v wie „w“. Typischer Fehler: *yeken* ohne das r." },
    { id: "tr-b1-08.24", t: "respond", say: "Yolda yürürken ya da yemek yerken neler yaparsın?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -(y)ken.",
      chunks: ["Yolda yürürken …", "Yemek yerken …", "Çocukken …", "Hastayken …"],
      models: ["Yolda yürürken genellikle müzik dinlerim. Yemek yerken telefona bakmam, çünkü bunu sevmem. Hastayken evde yatar ve çok çay içerim.", "Çocukken yemek yerken sürekli konuşurdum ve annem bana kızardı. Şimdi yürürken podcast dinliyorum."],
      modelsN: ["Beim Gehen auf der Straße höre ich meistens Musik. Beim Essen schaue ich nicht aufs Handy, denn das mag ich nicht. Wenn ich krank bin, liege ich zu Hause und trinke viel Tee.", "Als Kind habe ich beim Essen ständig geredet, und meine Mutter hat mit mir geschimpft. Jetzt höre ich beim Gehen Podcasts."],
      e: "-(y)ken beschreibt, was gleichzeitig passiert: yürü**rken**, yer**ken**, çocuk**ken**, hasta**yken**. Bei Verben steht der Aorist davor, bei Nomen nach Vokal der Puffer-y. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-09', {
  lesson: [
    { p: "Im Deutschen heißt es „**als** ich ankam“ (einmalig in der Vergangenheit) und „**wenn** ich ankomme“ (Zukunft oder wiederholt). Türkisch macht beides mit einem **Verbalnomen + Kasus**: *Eve geldiğimde* oder mit **-(y)IncA**: *Eve gelince*. Es gibt keinen Nebensatz mit Konjunktion – das Verb wird zur Zeitangabe." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutscher Nebensatz", "Bauplan", "Türkisch"], rows: [
      ["Als/Wenn ich nach Hause komme/kam, …", "Stamm + **-DIk** + Possessiv + **-DA**", "eve geldiğ**imde**"],
      ["Wenn/Als ich nach Hause komme/kam, … (gleichwertig)", "Stamm + -DIk + Possessiv + **zaman**", "eve geldiğ**im zaman**"],
      ["Sobald/Als er die Nachricht hörte, …", "Stamm + **-(y)IncA** (ohne Person)", "haberi duy**unca**"],
      ["Wenn er nicht kommt / Weil er nicht kam, …", "Stamm + -mA- + -(y)IncA", "gel**meyince**"]
    ] } },
    { h: "-DIğIndA: mit Person" },
    { table: { head: ["Person", "-DIğIndA (gelmek)", "-DIğI zaman"], rows: [
      ["ben", "geldiğ**imde**", "geldiğ**im zaman**"],
      ["sen", "geldiğ**inde**", "geldiğ**in zaman**"],
      ["o", "geldiğ**inde**", "geldiğ**i zaman**"],
      ["biz", "geldiğ**imizde**", "geldiğ**imiz zaman**"],
      ["siz", "geldiğ**inizde**", "geldiğ**iniz zaman**"],
      ["onlar", "geldik**lerinde**", "geldik**leri zaman**"]
    ] } },
    { p: "Die Possessiv-Endung zeigt, **wer** handelt (wie bei den Partizipien). Bei „du“ und „er/sie“ ist die Form gleich (*geldiğinde*), das Subjekt sagt dir den Unterschied. Das Subjekt steht meist im **Nominativ**: *Sen geldiğinde ben uyuyordum.* Ein Genitiv (*Senin geldiğinde …*) ist selten und nicht nötig. Wie überall: k → ğ vor Vokal (*geldiğ-*), aber *geldik-leri* bleibt k; d → t nach f, s, t, k, ç, ş, h, p (*yaptığımda, gittiğimde, konuştuğumda*)." },
    { h: "-(y)IncA: kürzer und ohne Person" },
    { p: "Die Endung -(y)IncA hat vier Formen (ı/i/u/ü): *gelince, bakınca, okuyunca, görünce*. Nach Vokal Puffer-**y**: *oku-y-unca, söyle-y-ince*. t wird vor dem Vokal zu d: *gidince*. Eine Personalendung gibt es **nicht**: Wer handelt, erkennt man am Zusammenhang oder am ausdrücklichen Subjekt: *Annem eve girince telefon çaldı.* Verneinung: -mA- vor der Endung (*gelmeyince*)." },
    { tip: "**Unterschied:** -DIğIndA/-DIğI zaman heben die **Person** hervor und klingen schriftlicher; -(y)IncA ist kompakter, oft **kurz hintereinander** („sobald, als“) und kann auch einen Grund andeuten: *Haberi duyunca çok sevindim.* (Als/Da ich die Nachricht hörte, freute ich mich sehr.)" },
    { tip: "Im Unterschied zu -(y)ken bedeutet -DIğIndA/-(y)IncA einen **Zeitpunkt**: *Eve girerken* (während des Hineingehens) gegenüber *Eve girince / girdiğimde* (als ich drin war)." },
    { warn: "Typische Fehler: *„geldim zaman“* (zaman braucht -DIğI: geldiğ**im** zaman), *„geldiğimden“* statt *geldiğimde* (-DAn heißt „seit/weil“), *„geldikimde“* (k wird vor Vokal zu ğ) und falsche Harmonie bei -(y)IncA (*bak-ınca*, aber *gel-ince*)." },
    { ex: [
      ["Eve geldiğimde annem yemek yapıyordu.", "Als ich nach Hause kam, kochte meine Mutter."],
      ["Türkiye’ye gittiğim zaman hep baklava yerim.", "Wenn ich in die Türkei fahre, esse ich immer Baklava."],
      ["Haberi duyunca çok sevindim.", "Als ich die Nachricht hörte, habe ich mich sehr gefreut."],
      ["Sen geldiğinde ben uyuyordum.", "Als du kamst, schlief ich."],
      ["Mesajıma cevap vermeyince endişelendim.", "Als du auf meine Nachricht nicht geantwortet hast, habe ich mir Sorgen gemacht."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-09.1", t: "gap", q: "Eve ___ seni arayacağım. (gelmek, ben – Wenn ich nach Hause komme, rufe ich dich an. Form auf -DIğIndA)", a: ["geldiğimde", "geldiğim zaman", "gelince"],
      wrong: { "geldiğinde": "-inde = „du/er/sie“. Hier handelt „ich“: -im-de.", "geldiğimden": "-DAn (Ablativ) heißt „seit/weil“. „Wenn/als“ braucht -DA.", "geldikimde": "k wird vor Vokal-Endung zu **ğ**: geldi**ğ**imde.", "geldiğim": "Es fehlt -DA oder *zaman*: geldiğim**de** / geldiğim **zaman**." },
      e: "gel- + **diğ** + **im** (ich) + **de** = **geldiğimde**. Auch *geldiğim zaman* und *gelince* sind richtig." },
    { id: "tr-b1-09.2", t: "gap", q: "Ankara’ya gittiğ___ beni ara. (Wenn du nach Ankara fährst, ruf mich an.)", a: ["inde"],
      wrong: { "imde": "-im = „ich“. Hier handelt „du“: -in-de.", "ında": "Letzter Vokal von *gittiğ-* ist **i** → -in**de** (mit Punkt).", "inden": "-DAn heißt „seit/weil“. Du willst „wenn“: -DA.", "imizde": "-imiz = „wir“. Gemeint ist „du“." },
      e: "gittiğ- + **in** (du) + **de** = **gittiğinde**. -DIk nach t: gittiğ (t bleibt)." },
    { id: "tr-b1-09.3", t: "gap", q: "Haberi duy___ çok sevindi. (duymak – Als er die Nachricht hörte, freute er sich sehr.)", a: ["unca"],
      wrong: { "ınca": "Letzter Vokal von *duy-* ist **u** → -**unca**.", "yunca": "*duy-* endet auf **y** (Konsonant) → kein Puffer-y nötig.", "ince": "Letzter Vokal **u** → -unca, nicht -ince." },
      e: "duy- + **unca** = **duyunca**. Nach Konsonant direkt; Vokalharmonie u → unca." },
    { id: "tr-b1-09.4", t: "gap", q: "Sen ___ ben sofrayı hazırlamıştım. (gelmek – Als du kamst, hatte ich den Tisch schon gedeckt.)", a: ["geldiğinde", "geldiğin zaman", "gelince"],
      wrong: { "geldiğimde": "-im = „ich“. Hier handelt „du“ (*Sen*): -in-de.", "geldiğine": "-A (Dativ) bedeutet nicht „als“. Du brauchst -DA.", "geldiğinden": "-DAn heißt „seit/weil“.", "geldikinde": "k wird vor Vokal-Endung zu **ğ**: geldi**ğ**inde." },
      e: "gel- + **diğ** + **in** (du) + **de** = **geldiğinde**. Das Subjekt *Sen* steht im Nominativ." },
    { id: "tr-b1-09.5", t: "gap", q: "Türkiye’ye gittiğim ___ hep baklava yerim. (Wenn ich in die Türkei fahre, esse ich immer Baklava.)", a: ["zaman"],
      wrong: { "zamanda": "Nach -DIğI steht *zaman* ohne weitere Endung.", "zamanlar": "*zaman* bleibt im Singular.", "zamanı": "Kein Akkusativ-/Possessiv-Zusatz: gittiğim **zaman**." },
      e: "gittiğim + **zaman** = „wenn/als ich fuhr“. Gleichwertig mit *gittiğimde*." },
    { id: "tr-b1-09.6", t: "gap", q: "Sen mesajıma cevap ver___ endişelendim. (vermek – Als du auf meine Nachricht nicht geantwortet hast, habe ich mir Sorgen gemacht.)", a: ["meyince", "mediğinde", "mediğin zaman"],
      wrong: { "meince": "*ver-me-* endet auf Vokal → Puffer-**y**: verme**y**ince.", "mayınca": "Letzter Vokal von *ver-* ist **e** → -me**y**ince.", "mediğimde": "-im = „ich“. Hier handelt „du“ (*Sen*)." },
      e: "ver- + **me** (Verneinung) + **y** + **ince** = **vermeyince**. Mit Person: *vermediğinde*." },
    { id: "tr-b1-09.7", t: "mc", q: "„Als ich ankam, schlief er schon.“", o: ["Ben geldiğimde o uyuyordu.", "Ben geldiğimden o uyuyordu.", "Ben geldiğimi o uyuyordu.", "Ben geldikimde o uyuyordu."], a: 0,
      why: { 1: "-DAn heißt „seit/weil“; für „als“ brauchst du -DA.", 2: "Der Akkusativ (-I) macht daraus ein Objekt („dass ich kam“).", 3: "k wird vor Vokal zu **ğ**: geldiğ-imde." },
      e: "gel- + **diğ** + **im** + **de** = **geldiğimde**." },
    { id: "tr-b1-09.8", t: "mc", q: "„Sobald ich die Tür öffnete, rannte die Katze hinaus.“", o: ["Kapıyı açınca kedi dışarı kaçtı.", "Kapıyı açarken kedi dışarı kaçtı.", "Kapıyı açıyınca kedi dışarı kaçtı.", "Kapıyı açmakınca kedi dışarı kaçtı."], a: 0,
      why: { 1: "*açarken* = während des Öffnens (gleichzeitig), nicht „sobald“.", 2: "*aç-* endet auf Konsonant ç → kein Puffer-y.", 3: "Nach dem Infinitiv steht nicht -(y)IncA." },
      e: "aç- + **ınca** = **açınca**. Eine Handlung löst die nächste aus." },
    { id: "tr-b1-09.9", t: "mc", q: "„Wenn ich in der Türkei bin, esse ich immer Baklava.“", o: ["Türkiye’de olduğum zaman hep baklava yerim.", "Türkiye’de olduğu zaman hep baklava yerim.", "Türkiye’de olduk zaman hep baklava yerim.", "Türkiye’de olduğum zamanda hep baklava yerim."], a: 0,
      why: { 1: "-ı/-i = „er/sie“, aber hier ist „ich“ gemeint.", 2: "Die Possessiv-Endung fehlt (olduk), außerdem fehlt ğ.", 3: "*zaman* steht ohne Kasus." },
      e: "ol- + **duğ** + **um** + **zaman** = **olduğum zaman**." },
    { id: "tr-b1-09.10", t: "mc", q: "Was bedeutet: *Annem eve girince telefon çaldı.*", o: ["Sobald meine Mutter hereinkam, klingelte das Telefon.", "Das Telefon klingelte, bevor sie hereinkam.", "Meine Mutter kam herein, weil das Telefon klingelte.", "Meine Mutter kam herein und rief an."], a: 0,
      why: { 1: "-(y)IncA nennt die erste Handlung, die zweite folgt danach.", 2: "-(y)IncA ist keine Ursache („weil“), sondern Zeitfolge.", 3: "Das Telefon klingelt, die Mutter ruft nicht an." },
      e: "gir- + **ince**: Zuerst kommt die Mutter herein, dann klingelt das Telefon." },
    { id: "tr-b1-09.11", t: "mc", q: "„Als ich ihn sah, konnte ich ihn nicht erkennen.“", o: ["Onu görünce tanıyamadım.", "Onu gördünce tanıyamadım.", "Onu görürünce tanıyamadım.", "Onu görmek tanıyamadım."], a: 0,
      why: { 1: "-(y)IncA hängt direkt am Stamm, ohne Zeitendung -DI.", 2: "Ohne Aorist: -(y)IncA folgt unmittelbar dem Stamm.", 3: "Nach dem Infinitiv steht nicht -(y)IncA." },
      e: "gör- + **ünce** (ö → ü) = **görünce**." },
    { id: "tr-b1-09.12", t: "mc", q: "„Wenn du morgen kommst (sobald du angekommen bist), ruf mich an.“", o: ["Yarın geldiğinde beni ara.", "Yarın gelirken beni ara.", "Yarın geldiğine beni ara.", "Yarın geldiğinden beni ara."], a: 0,
      why: { 1: "*gelirken* = während des Kommens, nicht „wenn du angekommen bist“.", 2: "-A (Dativ) bedeutet nicht „wenn“.", 3: "-DAn heißt „seit/weil“." },
      e: "-DIğIndA kann auch für die Zukunft stehen: *yarın geldiğinde* = wenn du morgen kommst." },
    { id: "tr-b1-09.13", t: "order", q: "Bilde den Satz: „Als ich nach Hause kam, schlief mein Bruder schon.“", w: ["Eve", "geldiğimde", "kardeşim", "uyuyordu"], a: ["Eve geldiğimde kardeşim uyuyordu", "Kardeşim eve geldiğimde uyuyordu"],
      e: "Der Zeitsatz *eve geldiğimde* steht vor dem Hauptsatz (oder in der Mitte). Das Prädikat *uyuyordu* bleibt am Ende." },
    { id: "tr-b1-09.14", t: "order", q: "Bilde den Satz: „Sobald er die Nachricht hörte, rief er mich an.“", w: ["Haberi", "duyunca", "beni", "aradı"], a: ["Haberi duyunca beni aradı"],
      e: "*haberi duyunca* (Objekt + -(y)IncA) – dann *beni aradı*. Das Objekt *haberi* steht im Akkusativ." },
    { id: "tr-b1-09.15", t: "order", q: "Bilde den Satz: „Wenn ich in der Türkei bin, esse ich immer Baklava.“", w: ["Türkiye’de", "olduğum", "zaman", "hep", "baklava", "yerim"], a: ["Türkiye’de olduğum zaman hep baklava yerim", "Türkiye’de olduğum zaman baklava hep yerim"],
      e: "*olduğum zaman* ist der Zeitsatz, *hep baklava yerim* der Hauptsatz." },
    { id: "tr-b1-09.16", t: "match", q: "Wer handelt? Ordne die Form zu:", p: [["geldiğimde", "als ich kam"], ["geldiğinde", "als du/er/sie kam"], ["geldiğimizde", "als wir kamen"], ["geldiğinizde", "als ihr/Sie kamt/kamen"], ["geldiklerinde", "als sie (mehrere) kamen"]],
      e: "Nur bei „sie (mehrere)“ bleibt das k (geldik-lerinde), sonst wird es zu ğ." },
    {"id":"tr-b1-09.17","t":"cloze","q":"Ergänze die Zeitsätze.","text":"Dün ben eve geldiğ{1} kimse kapıyı açmadı. Zili çal{2} içeriden bir ses duydum. Telefon çaldığ{3} çok korktum.","gaps":{"1":{"a":["imde"],"wrong":{"inde":"-in = „du/er/sie“. Das Subjekt ist *ben*: -imde.","ime":"Dativ bedeutet nicht „als“: -DA.","imden":"-DAn heißt „seit/weil“."}},"2":{"a":["ınca"],"wrong":{"unca":"Letzter Vokal von *çal-* ist **a** → -ınca.","yınca":"*çal-* endet auf Konsonant → kein Puffer-y.","ince":"Letzter Vokal **a** → -ınca."}},"3":{"a":["ında"],"wrong":{"inde":"Letzter Vokal von *çaldığ-* ist **ı** → -ında.","ımda":"-ım = „ich“. Das Telefon klingelt, es handelt: -ı + n + da.","ından":"-DAn heißt „seit/weil“; „als“ braucht -DA."}}},"e":"-DIğIndA mit Person (geldiğimde, çaldığında) und -(y)IncA ohne Person (çalınca). Das Subjekt von *çaldığında* ist das Telefon: 3. Person -ı + -nda."},
    {"id":"tr-b1-09.18","t":"sort","q":"-DIğIndA/-(y)IncA oder -(y)ken? Ordne die deutschen Sätze zu.","cats":["Zeitpunkt / nacheinander (-(y)IncA, -DIğIndA)","gleichzeitig (-(y)ken)"],"items":[["Sobald ich ankomme, rufe ich an.",0],["Während ich koche, höre ich Radio.",1],["Als ich die Tür öffnete, bellte der Hund.",0],["Als Kind wohnte ich auf dem Land.",1],["Als ich ihn sah, freute ich mich.",0],["Während wir spazieren gingen, trafen wir Freunde.",1]],"why":{"Sobald ich ankomme, rufe ich an.":"Erst ankommen, dann anrufen: geldiğimde / gelince.","Während ich koche, höre ich Radio.":"Gleichzeitig: yemek yaparken radyo dinliyorum.","Als ich die Tür öffnete, bellte der Hund.":"Öffnen löst das Bellen aus: kapıyı açınca.","Als Kind wohnte ich auf dem Land.":"Ein Zeitraum: çocukken.","Als ich ihn sah, freute ich mich.":"Sehen löst die Freude aus: onu görünce.","Während wir spazieren gingen, trafen wir Freunde.":"Gleichzeitig: yürürken."},"e":"-(y)IncA/-DIğIndA = Zeitpunkt oder Folge. -(y)ken = zwei Dinge zugleich."},
    { id: "tr-b1-09.19", t: "listen", say: "Ben eve geldiğimde annem yemek yapıyordu.", q: "Hör zu: Was tat die Mutter, als die Person nach Hause kam?",
      o: ["Sie kochte.", "Sie schlief.", "Sie war einkaufen.", "Sie rief an."], a: 0,
      why: { 1: "*uyuyordu* hieße „schlief“; hier steht *yemek yapıyordu*.", 2: "Von Einkaufen ist nicht die Rede.", 3: "Von einem Anruf ist nicht die Rede." },
      e: "„Als ich nach Hause kam, kochte meine Mutter.“ *geldiğimde* = Zeitpunkt, *yapıyordu* = Kulisse." },
    { id: "tr-b1-09.20", t: "dictation", say: "Haberi duyunca çok sevindi ve hemen beni aradı.", a: ["Haberi duyunca çok sevindi ve hemen beni aradı."],
      wrong: { "Haberi duyinca çok sevindi ve hemen beni aradı.": "Letzter Vokal von *duy-* ist **u** → duy**unca**.", "Haberi duyunca çok sevindı ve hemen beni aradı.": "Letzter Vokal von *sevin-* ist **i** → sevin**di**.", "Haberi duyunca çok sevindi ve hemen beni aradi.": "Letzter Vokal von *ara-* ist **a** → ara**dı** (ohne Punkt)." },
      e: "„Als er die Nachricht hörte, freute er sich sehr und rief mich sofort an.“ *duyunca* = duy + unca." },
    { id: "tr-b1-09.21", t: "speak", say: "Eve geldiğimde kimse yoktu.",
      e: "„Als ich nach Hause kam, war niemand da.“ *geldiğimde*: ğ nach i klingt wie ein leichtes j: gel-di-yim-de. *kimse*: i mit Punkt. Typischer Fehler: *geldigimde* mit hartem g." },
    { id: "tr-b1-09.22", t: "speak", say: "Haberi duyunca çok sevindim.",
      e: "„Als ich die Nachricht hörte, habe ich mich sehr gefreut.“ *duyunca*: du-yun-ca, c wie „dsch“. *sevindim*: v wie „w“. Typischer Fehler: *duyunka* mit k statt c." },
    { id: "tr-b1-09.23", t: "speak", say: "Tatile gittiğim zaman hep deniz kenarında kalırım.",
      e: "„Wenn ich in den Urlaub fahre, bleibe ich immer am Meer.“ *gittiğim*: ğ nach i klingt wie ein leichtes j: git-ti-yim. *kenarında*: ı dumpf. Typischer Fehler: *gitdigim* mit d statt tt." },
    { id: "tr-b1-09.24", t: "respond", say: "Eve geldiğinde ilk ne yaparsın?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -DIğIndA, -DIğI zaman oder -(y)IncA.",
      chunks: ["Eve geldiğimde …", "Sonra …", "Hafta sonu eve gelince …", "Çok yorgun olduğum zaman …"],
      models: ["Eve geldiğimde önce ayakkabılarımı çıkarırım. Sonra bir çay yaparım ve biraz dinlenirim. Çok yorgun olduğum zaman hemen duş alırım.", "Eve gelince ilk önce telefonumu şarja takarım. Sonra yemek yapmaya başlarım. Hafta sonu eve gelince çocuklarla oynarım."],
      modelsN: ["Wenn ich nach Hause komme, ziehe ich zuerst meine Schuhe aus. Dann koche ich Tee und ruhe mich etwas aus. Wenn ich sehr müde bin, dusche ich sofort.", "Wenn ich nach Hause komme, stecke ich zuerst das Handy ans Ladegerät. Dann fange ich an zu kochen. Wenn ich am Wochenende heimkomme, spiele ich mit den Kindern."],
      e: "Zeitpunkte mit **-DIğIndA** (geldiğimde), **-DIğI zaman** (olduğum zaman) und **-(y)IncA** (gelince). Der Hauptsatz folgt mit dem Verb am Ende. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-16', {
  lesson: [
    { p: "Drei häufige deutsche Konjunktionen für Zeitverläufe: „**bis**“ („Ich warte, bis du kommst“), „**je mehr … desto mehr**“ / „immer wenn“ („Je mehr ich lerne, desto besser …“) und „**seit**“ („Seit ich hier wohne, …“). Türkisch löst alle drei mit festen Verbformen auf: **-(y)IncAyA kadar** (bis), **-DIkçA** (je mehr, immer wenn) und **-DIğIndAn beri** (seit)." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutscher Nebensatz", "Bauplan", "Türkisch"], rows: [
      ["Ich warte, bis du kommst.", "Stamm + **-(y)IncAyA kadar** oder **-(y)AnA kadar**", "Sen gel**inceye kadar** / gel**ene kadar** bekleyeceğim."],
      ["Je mehr ich lerne, desto besser verstehe ich.", "Stamm + **-DIkçA**", "Öğren**dikçe** daha iyi anlıyorum."],
      ["Seit ich hier wohne, …", "Stamm + -DIk + Poss. + **-DAn beri**", "Burada otur**duğumdan beri** …"],
      ["Es ist ein Jahr her, dass ich hier wohne.", "Stamm + **-AlI** + Zeitangabe + oldu", "Buraya gel**eli** bir yıl oldu."],
      ["Solange du nicht kommst, …", "Stamm + -mA-**dIkçA**", "Sen gel**medikçe** …"]
    ] } },
    { p: "**bis – -(y)IncAyA kadar:** Das ist -(y)IncA (gelince) plus -yA kadar: *gel-ince-ye kadar*, *oku-y-unca-ya kadar*. Kürzer und sehr üblich: **-(y)AnA kadar** (*gel-en-e kadar*, *oku-y-an-a kadar*). Die Person steht nicht an der Form: *Sen gelene kadar bekledim.* (Ich habe gewartet, bis du kamst.) Verneint wird mit -mA-: *gelmeyinceye kadar* heißt „bis er kommt“ (also nicht „solange er nicht kommt“; das wäre *gelmedikçe*); umgangssprachlich sagt man dafür einfach *gelinceye kadar*." },
    { p: "**je mehr – -DIkçA:** Stamm + -DIk + çA. Der Vokal folgt der Harmonie (ı/i/u/ü), d → t nach f, s, t, k, ç, ş, h, p: *okudukça, geldikçe, yaptıkça, çalıştıkça, konuştukça*. Keine Person. Oft mit *daha*: *Çalıştıkça daha iyi oluyorum.* Das Wort heißt auch **„immer wenn“**: *Onu gördükçe seviniyorum.* Verneint: **-mAdIkçA** = solange nicht: *Sen gelmedikçe başlamayacağız.*" },
    { p: "**seit – -DIğIndAn beri:** -DIk + **Possessiv** (Person!) + **-DAn beri**. Der Ablativ -DAn ist nötig: *geldiğim**den** beri*, *taşındığımdan beri*. Alternative für „vor einer Zeitspanne“: **-AlI** (ohne Person): *Taşınalı iki yıl oldu.* (Seit dem Umzug sind zwei Jahre vergangen.)" },
    { warn: "Typische Fehler: *„geldiğimda beri“* (für „seit“ braucht man den Ablativ: geldiğim**den** beri), *„öğrenincekçe“* (-DIkçA hängt direkt an -DIk: öğren**dikçe**), *„gelince kadar“* (kadar braucht den Dativ: gelince**ye** kadar), *„yapdıkça“* statt *yaptıkça* (p ist stimmlos → t)." },
    { tip: "Merkhilfe: **kadar** = Ziel („bis“), **-DIkçA** = Wiederholung/Steigerung („je mehr“), **beri** = Ausgangspunkt („seit“)." },
    { ex: [
      ["Sen gelene kadar burada bekleyeceğim.", "Ich werde hier warten, bis du kommst."],
      ["Çalıştıkça daha iyi öğreniyorum.", "Je mehr ich arbeite, desto besser lerne ich."],
      ["Ben Türkiye’ye geldiğimden beri Türkçem çok gelişti.", "Seit ich in die Türkei gekommen bin, hat sich mein Türkisch sehr verbessert."],
      ["Bu şehre geleli üç yıl oldu.", "Es sind drei Jahre her, seit ich in diese Stadt gekommen bin."],
      ["Sen gelmedikçe başlamayacağız.", "Solange du nicht kommst, fangen wir nicht an."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-16.1", t: "gap", q: "Sen ___ kadar burada bekleyeceğim. (gelmek – Ich warte hier, bis du kommst.)", a: ["gelinceye", "gelene"],
      wrong: { "gelince": "*kadar* verlangt den Dativ: gelince**ye** kadar.", "gelinceya": "Letzter Vokal von *gelince* ist **e** → -ye (nicht -ya).", "geldiğine": "Das wäre „dass du kamst“ – für „bis“ nimmt man -(y)IncAyA oder -(y)AnA.", "gelen": "Hinter *gelen* fehlt der Dativ: gelen**e** kadar." },
      e: "gel- + **ince** + **ye** = **gelinceye** (kadar). Kürzer: gel- + **en** + **e** = **gelene** (kadar)." },
    { id: "tr-b1-16.2", t: "gap", q: "Yağmur ___ kadar evde kaldık. (dinmek – Wir blieben zu Hause, bis der Regen aufhörte.)", a: ["dinene", "dininceye"],
      wrong: { "dinince": "*kadar* verlangt den Dativ: dinince**ye** kadar.", "dinen": "Hinter dem Partizip fehlt der Dativ: dinen**e** kadar.", "dindikçe": "-DIkçA = „je mehr / immer wenn“. Für „bis“ nimmt man -(y)IncAyA oder -(y)AnA." },
      e: "din- + **en** + **e** = **dinene** kadar, oder din- + **inceye** = **dininceye** kadar." },
    { id: "tr-b1-16.3", t: "gap", q: "Çok çalış___ daha iyi oluyorum. (Je mehr ich arbeite, desto besser werde ich.)", a: ["tıkça"],
      wrong: { "dıkça": "*çalış-* endet auf **ş** (stimmlos) → d wird **t**: çalış**tık**ça.", "tikçe": "Letzter Vokal von *çalış-* ist **ı** → -tıkça (ohne Punkt, a).", "ınca": "-(y)IncA = „sobald/als“. Für „je mehr“ nimmt man -DIkçA." },
      e: "çalış- + **tık** + **ça** = **çalıştıkça**. d → t nach ş." },
    { id: "tr-b1-16.4", t: "gap", q: "Türkçe konuş___ korkum azalıyor. (Je mehr ich Türkisch spreche, desto weniger Angst habe ich.)", a: ["tukça"],
      wrong: { "tıkça": "Letzter Vokal von *konuş-* ist **u** → -tukça.", "dukça": "*konuş-* endet auf **ş** (stimmlos) → d wird **t**.", "tukçe": "Letzter Vokal **u** → -çA wird -ça (kleine Harmonie)." },
      e: "konuş- + **tuk** + **ça** = **konuştukça**." },
    { id: "tr-b1-16.5", t: "gap", q: "Ben Türkiye’ye taşın___ beri Türkçem çok gelişti. (Seit ich in die Türkei gezogen bin, hat sich mein Türkisch sehr verbessert.)", a: ["dığımdan"],
      wrong: { "dığımda": "-DA heißt „als/wenn“. Für „seit“ braucht man den Ablativ: -DAn beri.", "dığım": "Es fehlt der Ablativ: taşındığım**dan** beri.", "dığından": "-ın = „du/er/sie“. Hier handelt „ich“ (*Ben*): -ım.", "tığımdan": "*taşın-* endet auf **n** (stimmhaft) → d bleibt: taşın**dığ**ımdan." },
      e: "taşın- + **dık** → ğ + **ım** + **dan** = **taşındığımdan** beri." },
    { id: "tr-b1-16.6", t: "gap", q: "Bu şehre ___ üç yıl oldu. (gelmek – Es sind drei Jahre vergangen, seit ich in diese Stadt gekommen bin.)", a: ["geleli"],
      wrong: { "gelince": "-(y)IncA = „sobald/als“. Für „seit“ mit Zeitspanne nimmt man -AlI.", "geldiğimden": "Hier fehlt *beri*. Mit -AlI geht es kürzer: gel**eli** üç yıl oldu.", "gelinceye": "-(y)IncAyA kadar = „bis“. Hier geht es um „seit“." },
      e: "gel- + **eli** = **geleli**. -AlI nennt den Ausgangspunkt; *üç yıl oldu* nennt die vergangene Zeit. Keine Personalendung." },
    { id: "tr-b1-16.7", t: "mc", q: "„Ich habe gewartet, bis du kamst.“", o: ["Sen gelene kadar bekledim.", "Sen geldiğinde kadar bekledim.", "Sen gelince kadar bekledim.", "Sen gelirken kadar bekledim."], a: 0,
      why: { 1: "*kadar* verlangt Verbformen auf -(y)AnA oder -(y)IncAyA, nicht -DIğIndA.", 2: "Bei -(y)IncA muss der Dativ folgen: gelince**ye** kadar.", 3: "-ken (gleichzeitig) passt nicht zu *kadar*." },
      e: "gel- + **en** + **e** + kadar = **gelene kadar**." },
    { id: "tr-b1-16.8", t: "mc", q: "„Je mehr ich lerne, desto mehr verstehe ich.“", o: ["Öğrendikçe daha çok anlıyorum.", "Öğrenirken daha çok anlıyorum.", "Öğrenince daha çok anlıyorum.", "Öğrendiğimden beri daha çok anlıyorum."], a: 0,
      why: { 1: "*öğrenirken* = während ich lerne, ohne Steigerung.", 2: "*öğrenince* = sobald ich gelernt habe (einmalig).", 3: "*öğrendiğimden beri* = seit ich gelernt habe." },
      e: "öğren- + **dik** + **çe** = **öğrendikçe**. -DIkçA = Steigerung/Wiederholung." },
    { id: "tr-b1-16.9", t: "mc", q: "„Seit ich hier arbeite, bin ich glücklicher.“", o: ["Burada çalıştığımdan beri daha mutluyum.", "Burada çalıştığımda beri daha mutluyum.", "Burada çalıştıkça beri daha mutluyum.", "Burada çalışınca beri daha mutluyum."], a: 0,
      why: { 1: "*beri* braucht den Ablativ: çalıştığım**dan** beri.", 2: "-DIkçA und *beri* passen nicht zusammen.", 3: "-(y)IncA verträgt kein *beri*." },
      e: "çalış- + **tık** → ğ + **ım** + **dan** + beri." },
    { id: "tr-b1-16.10", t: "mc", q: "„Es ist ein Jahr her, dass er ausgezogen ist.“", o: ["Taşınalı bir yıl oldu.", "Taşınınca bir yıl oldu.", "Taşındıkça bir yıl oldu.", "Taşınırken bir yıl oldu."], a: 0,
      why: { 1: "-(y)IncA = „sobald“. Für „seit“ + Zeitspanne nimmt man -AlI.", 2: "-DIkçA = „je mehr / immer wenn“.", 3: "-ken = „während“." },
      e: "taşın- + **alı** = **taşınalı**. -AlI + Zeitangabe + *oldu*." },
    { id: "tr-b1-16.11", t: "mc", q: "„Je öfter ich sie sehe, desto mehr mag ich sie.“", o: ["Onu gördükçe daha çok seviyorum.", "Onu görünce daha çok seviyorum.", "Onu görürken daha çok seviyorum.", "Onu gördüğümden daha çok seviyorum."], a: 0,
      why: { 1: "-(y)IncA meint ein einmaliges „sobald/als“, nicht die Steigerung „je öfter“.", 2: "-ken = gleichzeitig, ohne Steigerung.", 3: "-DAn nennt Grund oder Ausgangspunkt, nicht „je öfter“." },
      e: "gör- + **dük** + **çe** = **gördükçe** (ö → ü Harmonie)." },
    { id: "tr-b1-16.12", t: "mc", q: "Was bedeutet: *İstanbul’a geldiğimden beri iki yıl geçti.*", o: ["Seit ich nach Istanbul gekommen bin, sind zwei Jahre vergangen.", "Bis ich nach Istanbul komme, vergehen zwei Jahre.", "Je öfter ich komme, desto länger dauert es.", "Als ich in Istanbul war, gingen zwei Jahre vorbei."], a: 0,
      why: { 1: "*beri* nennt den Ausgangspunkt („seit“), nicht das Ziel („bis“).", 2: "Steigerung („je öfter“) wäre -DIkçA.", 3: "„Als“ wäre -DIğIndA, nicht -DIğIndAn beri." },
      e: "gel- + **diğ** + **im** + **den** + **beri** = seit ich kam." },
    { id: "tr-b1-16.13", t: "order", q: "Bilde den Satz: „Ich warte hier, bis du kommst.“", w: ["Sen", "gelene", "kadar", "burada", "bekleyeceğim"], a: ["Sen gelene kadar burada bekleyeceğim", "Burada sen gelene kadar bekleyeceğim"],
      e: "Der Nebensatz *sen gelene kadar* steht vor dem Hauptverb *bekleyeceğim*. Das Subjekt *sen* steht ausdrücklich da, weil es von „ich“ verschieden ist." },
    { id: "tr-b1-16.14", t: "order", q: "Bilde den Satz: „Je mehr ich arbeite, desto müder werde ich.“", w: ["Çalıştıkça", "daha", "yorgun", "oluyorum"], a: ["Çalıştıkça daha yorgun oluyorum"],
      e: "*Çalıştıkça* leitet den Satz ein, *daha* verstärkt die Steigerung. *yorgun oluyorum* bleibt am Ende." },
    { id: "tr-b1-16.15", t: "order", q: "Bilde den Satz: „Seit ich in Deutschland bin, esse ich viel Brot.“", w: ["Almanya’ya", "geldiğimden", "beri", "çok", "ekmek", "yiyorum"], a: ["Almanya’ya geldiğimden beri çok ekmek yiyorum"],
      e: "*geldiğimden beri* = seit ich gekommen bin. Das Objekt *ekmek* ist unbestimmt und steht ohne Akkusativ." },
    { id: "tr-b1-16.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["gelinceye kadar", "bis er kommt"], ["geldikçe", "immer wenn / je öfter er kommt"], ["geldiğinden beri", "seit er gekommen ist"], ["geleli iki yıl oldu", "es ist zwei Jahre her, dass er kam"], ["gelmedikçe", "solange er nicht kommt"]],
      e: "kadar = bis, -DIkçA = je mehr/immer wenn, beri = seit. -AlI nennt die vergangene Zeit; -mAdIkçA heißt „solange nicht“." },
    {"id":"tr-b1-16.17","t":"cloze","q":"Ergänze die Zeitformen.","text":"Ben Türkiye’ye gel{1} beri Türkçe öğreniyorum. Çok konuş{2} daha iyi anlıyorum. Sınavı geç{3} kadar çalışacağım.","gaps":{"1":{"a":["diğimden"],"wrong":{"diğimde":"-DA heißt „als/wenn“. Für „seit“ braucht man den Ablativ -DAn.","diğinden":"-in = „du/er/sie“. Das Subjekt ist *Ben*: -im.","dikimden":"k wird vor Vokal zu ğ: geldi**ğ**imden."}},"2":{"a":["tukça"],"wrong":{"tıkça":"Letzter Vokal von *konuş-* ist **u** → -tukça.","dukça":"*konuş-* endet auf **ş** (stimmlos) → t.","tukçe":"Nach u steht -ça, nicht -çe."}},"3":{"a":["inceye","ene"],"wrong":{"ince":"*kadar* verlangt den Dativ: geçince**ye** kadar.","unca":"Letzter Vokal von *geç-* ist **e** → -ince.","iğimden":"Das wäre „seit“. Für „bis“ nimmt man -(y)IncAyA oder -(y)AnA."}}},"e":"beri → -DIğIndAn (Person!). -DIkçA → Steigerung. kadar → -(y)IncAyA / -(y)AnA (Dativ!). Die Vokalharmonie entscheidet bei den Endungen."},
    {"id":"tr-b1-16.18","t":"sort","q":"Zeitpunkt oder Steigerung? Ordne die deutschen Sätze zu.","cats":["Ziel oder Ausgangspunkt (kadar, beri)","Steigerung / Wiederholung (-DIkçA)"],"items":[["Ich warte, bis du kommst.",0],["Je mehr ich lese, desto mehr lerne ich.",1],["Seit ich hier wohne, bin ich glücklich.",0],["Immer wenn ich ihn sehe, lächle ich.",1],["Es regnete, bis es dunkel wurde.",0],["Je älter sie wird, desto weiser wird sie.",1]],"why":{"Ich warte, bis du kommst.":"Ziel der Wartezeit: gelene kadar.","Je mehr ich lese, desto mehr lerne ich.":"Steigerung: okudukça daha çok öğreniyorum.","Seit ich hier wohne, bin ich glücklich.":"Ausgangspunkt: burada oturduğumdan beri.","Immer wenn ich ihn sehe, lächle ich.":"Wiederholung: onu gördükçe gülümsüyorum.","Es regnete, bis es dunkel wurde.":"Endpunkt: hava kararana kadar.","Je älter sie wird, desto weiser wird sie.":"Steigerung: yaşlandıkça daha bilge oluyor."},"e":"kadar und beri markieren Anfang und Ende einer Zeitspanne, -DIkçA beschreibt, wie sich etwas bei Wiederholung steigert."},
    { id: "tr-b1-16.19", t: "listen", say: "Sen gelene kadar burada bekleyeceğim.", q: "Hör zu: Was sagt die Person?",
      o: ["Sie wartet hier, bis der andere kommt.", "Sie wartet nur fünf Minuten.", "Sie geht, bevor der andere kommt.", "Sie war schon da, als der andere kam."], a: 0,
      why: { 1: "Von fünf Minuten ist nicht die Rede.", 2: "*gelene kadar bekleyeceğim* = ich werde warten, bis du kommst, nicht „gehen“.", 3: "*bekleyeceğim* ist Zukunft, nicht Vergangenheit." },
      e: "„Ich werde hier warten, bis du kommst.“ *gelene kadar*: Dativ nach *kadar*." },
    { id: "tr-b1-16.20", t: "dictation", say: "Türkçe konuştukça kendime daha çok güveniyorum.", a: ["Türkçe konuştukça kendime daha çok güveniyorum."],
      wrong: { "Türkçe konuştıkça kendime daha çok güveniyorum.": "Letzter Vokal von *konuş-* ist **u** → konuş**tuk**ça.", "Türkçe konuşdukça kendime daha çok güveniyorum.": "*ş* ist stimmlos → d wird **t**: konuş**t**ukça.", "Türkçe konuşunca kendime daha çok güveniyorum.": "*konuşunca* = sobald ich spreche. „Je mehr“ braucht -DIkçA." },
      e: "„Je mehr ich Türkisch spreche, desto mehr Selbstvertrauen habe ich.“ *konuş-* + tukça; *güvenmek* → güveniyorum (güven- + iyor: Bindevokal nach Harmonie)." },
    { id: "tr-b1-16.21", t: "speak", say: "Sen gelene kadar burada bekleyeceğim.",
      e: "„Ich werde hier warten, bis du kommst.“ *gelene*: e kurz, g wie in „gehen“. *bekleyeceğim*: c wie „dsch“, ğ nach e klingt wie ein leichtes j: bek-le-ye-ce-yim. Typischer Fehler: *gelen kadar* ohne -e." },
    { id: "tr-b1-16.22", t: "speak", say: "Çalıştıkça daha iyi öğreniyorum.",
      e: "„Je mehr ich arbeite, desto besser lerne ich.“ *çalıştıkça*: ç = „tsch“, ş = „sch“, ı dumpf; kç in -kça nicht zu „k-sch“ verschmelzen. *öğreniyorum*: das ğ nach ö wird nicht gesprochen und dehnt den Vokal: gesprochen öö-re-ni-yo-rum, ohne j. Typischer Fehler: ç wie „sch“ statt „tsch“ sprechen." },
    { id: "tr-b1-16.23", t: "speak", say: "Bu şehre geleli iki yıl oldu.",
      e: "„Es sind zwei Jahre, seit ich in diese Stadt gekommen bin.“ *şehre*: ş = „sch“, e kurz. *geleli*: ge-le-li, kurze Vokale. *oldu*: Betonung auf der letzten Silbe, ol-DU. Typischer Fehler: *gelelı* mit dumpfem ı." },
    { id: "tr-b1-16.24", t: "respond", say: "Ne zamandan beri Türkçe öğreniyorsun?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -DIğIndAn beri, -AlI … oldu oder -DIkçA.",
      chunks: ["… -DIğImdAn beri …", "… -AlI … oldu.", "Çalıştıkça …", "… kadar …"],
      models: ["Türkçe öğrenmeye başladığımdan beri bir yıl geçti. Çalıştıkça daha çok anlıyorum. İyi konuşana kadar her gün biraz çalışacağım.", "Türkçe öğreneli sekiz ay oldu. Konuştukça özgüvenim artıyor. Bir sonraki sınava kadar düzenli tekrar yapacağım."],
      modelsN: ["Seit ich angefangen habe, Türkisch zu lernen, ist ein Jahr vergangen. Je mehr ich arbeite, desto mehr verstehe ich. Bis ich gut spreche, werde ich jeden Tag ein bisschen üben.", "Ich lerne seit acht Monaten Türkisch. Je mehr ich spreche, desto größer wird mein Selbstvertrauen. Bis zur nächsten Prüfung werde ich regelmäßig wiederholen."],
      e: "**seit** = -DIğIndAn beri (başladığımdan beri) oder -AlI … oldu (öğreneli sekiz ay oldu); **je mehr** = -DIkçA (çalıştıkça); **bis** = -(y)AnA/-(y)IncAyA kadar (konuşana kadar). Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-12', {
  lesson: [
    { p: "Im Deutschen sagst du „er kam **rennend**“, „**indem** ich Filme schaue“, „er ging, **ohne** etwas zu sagen“ oder „**bevor** ich esse“. Türkisch hat dafür zwei kompakte Verbformen: **-arak/-erek** (Art und Weise, Mittel) und **-mAdAn** (ohne zu / bevor). Beide hängen direkt am Stamm, haben **keine Person** und beziehen sich meist auf dasselbe Subjekt wie der Hauptsatz." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutsche Konstruktion", "Bauplan", "Türkisch"], rows: [
      ["Er kam rennend. (Art und Weise)", "Stamm + **-arak/-erek**", "koş**arak** geldi"],
      ["Ich lerne Türkisch, indem ich Filme schaue.", "Stamm + -arak/-erek", "film izle**yerek** Türkçe öğreniyorum"],
      ["Er ging, ohne etwas zu sagen.", "Stamm + **-mAdAn**", "bir şey söyle**meden** gitti"],
      ["Bevor ich esse, wasche ich die Hände.", "Stamm + -mAdAn + **önce**", "yemek ye**meden önce** ellerimi yıkarım"],
      ["Nachdem ich gegessen habe, …", "Stamm + -DIktAn + **sonra**", "yemek ye**dikten sonra** …"],
      ["Er arbeitet als Lehrer.", "Nomen + **olarak**", "öğretmen **olarak** çalışıyor"]
    ] } },
    { p: "**-arak/-erek** hat zwei Vokalformen: **-arak** nach a, ı, o, u und **-erek** nach e, i, ö, ü. Nach **Vokal** steht der Puffer-y: *yürü-**y**erek* (zu Fuß), *oku-**y**arak, izle-**y**erek, söyle-**y**erek*. t wird vor dem Vokal zu d (*giderek*). Verneint heißt es **-mayarak/-meyerek** und bleibt bei Art und Weise/Mittel: *kimseye söylemeyerek* (ohne es jemandem zu sagen). Für „ohne zu“ und „bevor“ nimmt man dagegen **-mAdAn**: *Ben gelmeden gitme.*" },
    { p: "**-mAdAn** hat nur die Formen -madan / -meden (kleine Harmonie): *yapmadan, gelmeden, söylemeden*. Es steht für „ohne zu …“: *Kapıyı çalmadan girdi.* (Er trat ein, ohne zu klopfen.) Das Subjekt darf wechseln: *Kimse fark etmeden çıktı.* (Er ging hinaus, ohne dass es jemand merkte.) Dazu gehört auch **-mAdAn önce** („bevor“): *Çıkmadan önce beni ara.* — das Gegenstück ist **-DIktAn sonra** („nachdem“): *yedikten sonra*." },
    { p: "**olarak** ist eine feste Verbindung: Nomen + **olarak** = „als“: *Turist olarak geldim.* (Ich kam als Tourist.) *Öğretmen olarak çalışıyor.* Dazu: *genel olarak* (im Allgemeinen). Vergleich: *öğretmen **gibi*** = „wie ein Lehrer“." },
    { warn: "Typische Fehler: *„yürürek“* (nach Vokal ü braucht -arak/-erek den Puffer-y: yürü**yerek**), *„yürüyarak“* (Vokal ü → -erek), *„gelmedan“* (e → -meden)." },
    { tip: "Ob **-arak/-erek** oder **-ken**? -ken = gleichzeitig, ohne Mittel/Weise: *yürürken konuştuk* (während wir gingen, sprachen wir). -arak/-erek = Art oder Mittel: *yürüyerek gittik* (wir gingen zu Fuß)." },
    { ex: [
      ["Çocuklar şarkı söyleyerek bahçeye koştu.", "Die Kinder rannten singend in den Garten."],
      ["Her gün işe yürüyerek gidiyorum.", "Ich gehe jeden Tag zu Fuß zur Arbeit."],
      ["Hiçbir şey söylemeden evden çıktı.", "Er verließ das Haus, ohne etwas zu sagen."],
      ["Yemek yemeden önce ellerimi yıkarım.", "Bevor ich esse, wasche ich mir die Hände."],
      ["Doktor olarak hastanede çalışıyor.", "Sie arbeitet als Ärztin im Krankenhaus."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-12.1", t: "gap", q: "Okula yürü___ gidiyorum. (yürümek – Ich gehe zu Fuß zur Schule.)", a: ["yerek"],
      wrong: { "erek": "*yürü-* endet auf Vokal → der Puffer-**y** ist nötig: yürü**yerek**.", "yarak": "Letzter Vokal von *yürü-* ist **ü** → -**erek**, nicht -arak.", "yürek": "Das ist ein anderes Wort („Herz“). Hier brauchst du -arak/-erek.", "ken": "-ken heißt „während“. „Zu Fuß“ ist die Art: -arak/-erek." },
      e: "yürü- + **y** + **erek** = **yürüyerek**. „zu Fuß“ = auf gehende Weise." },
    { id: "tr-b1-12.2", t: "gap", q: "Çocuk gül___ koştu. (gülmek – Das Kind rannte lachend.)", a: ["erek"],
      wrong: { "yerek": "*gül-* endet auf Konsonant l → kein Puffer-y: gül**erek**.", "arak": "Letzter Vokal von *gül-* ist **ü** → -**erek**.", "ip": "-Ip meint „und dann“; hier beschreibst du die Art: -arak/-erek." },
      e: "gül- + **erek** = **gülerek**. Nach Konsonant direkt, Harmonie ü → erek." },
    { id: "tr-b1-12.3", t: "gap", q: "Film izle___ Türkçe öğreniyorum. (izlemek – Ich lerne Türkisch, indem ich Filme schaue.)", a: ["yerek"],
      wrong: { "erek": "*izle-* endet auf Vokal e → Puffer-**y**: izle**yerek**.", "yarak": "Letzter Vokal von *izle-* ist **e** → -**erek**.", "dikçe": "-DIkçA = „je mehr“. Hier geht es um das Mittel „indem“." },
      e: "izle- + **y** + **erek** = **izleyerek**." },
    { id: "tr-b1-12.4", t: "gap", q: "Bana haber ver___ gitti. (vermek – Er ging, ohne mir Bescheid zu sagen.)", a: ["meden"],
      wrong: { "madan": "Letzter Vokal von *ver-* ist **e** → -**meden**.", "yerek": "-arak/-erek heißt „indem/…end“. Für „ohne“ nimmt man -mAdAn.", "medin": "Die Endung heißt -mAdAn (mit -n am Ende)." },
      e: "ver- + **me** + **den** = **vermeden**. „Ohne zu …“ = -mAdAn." },
    { id: "tr-b1-12.5", t: "gap", q: "Yemek ye___ önce ellerini yıka. (yemek – Wasch dir die Hände, bevor du isst.)", a: ["meden"],
      wrong: { "dikten": "-DIktAn braucht *sonra* (nachdem), nicht *önce*.", "yerek": "-arak/-erek heißt „indem“. „Bevor“ = -mAdAn önce.", "medin": "Die Endung heißt -mAdAn (…den am Ende)." },
      e: "ye- + **me** + **den** + önce = **yemeden önce** (bevor man isst)." },
    { id: "tr-b1-12.6", t: "gap", q: "Dört yıldır Berlin’de öğretmen ___ çalışıyorum. (Seit vier Jahren arbeite ich in Berlin als Lehrer.)", a: ["olarak"],
      wrong: { "gibi": "*gibi* heißt „wie“ – „wie ein Lehrer“, nicht „als Lehrer“.", "diye": "*diye* leitet Zitate oder Gründe ein.", "ile": "*ile* heißt „mit“." },
      e: "öğretmen + **olarak** = **als Lehrer** (Funktion/Eigenschaft)." },
    { id: "tr-b1-12.7", t: "mc", q: "„Er kam rennend.“", o: ["Koşarak geldi.", "Koşan geldi.", "Koşmadan geldi.", "Koşmak geldi."], a: 0,
      why: { 1: "*koşan* = „der, der rennt“ (Partizip als Subjekt).", 2: "*koşmadan* = „ohne zu rennen“.", 3: "Der Infinitiv sagt nicht, wie er kam." },
      e: "koş- + **arak** = **koşarak** (Art und Weise)." },
    { id: "tr-b1-12.8", t: "mc", q: "„Sie ging, ohne etwas zu sagen.“", o: ["Hiçbir şey söylemeden gitti.", "Hiçbir şey söyleyerek gitti.", "Hiçbir şey söylemek gitti.", "Hiçbir şey söylemiyor gitti."], a: 0,
      why: { 1: "-arak/-erek heißt „indem/…end“, nicht „ohne“.", 2: "Der Infinitiv kann nicht allein stehen.", 3: "*söylemiyor* ist ein finites Verb und verbindet keine Sätze." },
      e: "söyle- + **me** + **den** = **söylemeden**. Die Verneinung steckt in -mAdAn." },
    { id: "tr-b1-12.9", t: "mc", q: "„indem man viel liest“", o: ["çok okuyarak", "çok okurak", "çok okuyerek", "çok okumadan"], a: 0,
      why: { 1: "*oku-* endet auf Vokal → Puffer-y: oku**yarak**.", 2: "Letzter Vokal von *oku-* ist **u** → -arak, nicht -erek.", 3: "*okumadan* = „ohne zu lesen“." },
      e: "oku- + **y** + **arak** = **okuyarak**." },
    { id: "tr-b1-12.10", t: "mc", q: "„Bevor ich esse, wasche ich die Hände.“", o: ["Yemek yemeden önce ellerimi yıkarım.", "Yemek yedikten sonra ellerimi yıkarım.", "Yemek yiyerek ellerimi yıkarım.", "Yemek yiyince ellerimi yıkarım."], a: 0,
      why: { 1: "*yedikten sonra* = nachdem ich gegessen habe.", 2: "*yiyerek* = indem ich esse (Mittel).", 3: "*yiyince* = sobald ich esse/gegessen habe." },
      e: "ye- + **me** + **den** + önce = bevor man isst." },
    { id: "tr-b1-12.11", t: "mc", q: "„Als Ärztin arbeitet sie im Krankenhaus.“", o: ["Doktor olarak hastanede çalışıyor.", "Doktor gibi hastanede çalışıyor.", "Doktor diye hastanede çalışıyor.", "Doktorken hastanede çalışıyor."], a: 0,
      why: { 1: "*gibi* = „wie eine Ärztin“, nicht „als Ärztin“.", 2: "*diye* leitet Zitate oder Gründe ein.", 3: "*doktorken* = „solange sie Ärztin ist/war“, ein Zeitraum." },
      e: "doktor + **olarak** = in der Funktion als Ärztin." },
    { id: "tr-b1-12.12", t: "mc", q: "„Nachdem ich gegessen hatte“", o: ["Yemek yedikten sonra", "Yemek yiyerek sonra", "Yemek yemeden sonra", "Yemek yerken sonra"], a: 0,
      why: { 1: "-arak/-erek heißt „indem“, nicht „nachdem“.", 2: "-mAdAn heißt „ohne/bevor“.", 3: "-ken heißt „während“." },
      e: "ye- + **dik** + **ten** + sonra = **yedikten sonra** (k bleibt: -DIktAn)." },
    { id: "tr-b1-12.13", t: "order", q: "Bilde den Satz: „Ich gehe jeden Tag zu Fuß zur Arbeit.“", w: ["Her", "gün", "yürüyerek", "işe", "gidiyorum"], a: ["Her gün işe yürüyerek gidiyorum", "Her gün yürüyerek işe gidiyorum"],
      e: "*yürüyerek* steht direkt vor dem Verb oder vor dem Ziel – wichtig ist, dass *gidiyorum* am Ende bleibt." },
    { id: "tr-b1-12.14", t: "order", q: "Bilde den Satz: „Er ging hinaus, ohne die Tür zu schließen.“", w: ["Kapıyı", "kapatmadan", "dışarı", "çıktı"], a: ["Kapıyı kapatmadan dışarı çıktı"],
      e: "*kapıyı kapatmadan* = ohne die Tür zu schließen. Das Objekt *kapıyı* steht im Akkusativ vor dem Verb." },
    { id: "tr-b1-12.15", t: "order", q: "Bilde den Satz: „Ich lerne Türkisch, indem ich viel spreche.“", w: ["Çok", "konuşarak", "Türkçe", "öğreniyorum"], a: ["Çok konuşarak Türkçe öğreniyorum", "Türkçe çok konuşarak öğreniyorum"],
      e: "*çok konuşarak* = indem ich viel spreche. *Türkçe* ist Objekt ohne Akkusativ (allgemein)." },
    { id: "tr-b1-12.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["koşarak", "rennend"], ["haber vermeden", "ohne Bescheid zu sagen"], ["yedikten sonra", "nachdem man gegessen hat"], ["yemeden önce", "bevor man isst"], ["öğretmen olarak", "als Lehrer"]],
      e: "-arak/-erek = Art/Mittel, -mAdAn = ohne/bevor, -DIktAn sonra = nachdem, olarak = als." },
    {"id":"tr-b1-12.17","t":"cloze","q":"Ergänze die Formen.","text":"Ali bana haber ver{1} geldi. Çocuklar şarkı söyle{2} bahçeye koştu. Yemek ye{3} önce ellerimizi yıkadık.","gaps":{"1":{"a":["meden"],"wrong":{"madan":"Letzter Vokal von *ver-* ist **e** → -**meden**.","erek":"-arak/-erek heißt „indem“, nicht „ohne“.","dikten":"Das heißt „nachdem“ und braucht *sonra*."}},"2":{"a":["yerek"],"wrong":{"erek":"*söyle-* endet auf Vokal → Puffer-**y**.","yarak":"Letzter Vokal von *söyle-* ist **e** → -yerek.","meden":"-mAdAn heißt „ohne“. Hier geht es um die Art."}},"3":{"a":["meden"],"wrong":{"dikten":"-DIktAn braucht *sonra* (nachdem), nicht *önce*.","yerek":"-arak/-erek heißt „indem“. „Bevor“ = -mAdAn önce.","madan":"Letzter Vokal von *ye-* ist **e** → -meden."}}},"e":"ohne = -mAdAn (haber vermeden), Art = -arak/-erek (söyleyerek), bevor = -mAdAn önce (yemeden önce)."},
    {"id":"tr-b1-12.18","t":"sort","q":"Art und Weise oder „ohne/bevor“? Ordne die deutschen Sätze zu.","cats":["-arak/-erek (Art und Weise, Mittel)","-mAdAn (ohne zu / bevor)"],"items":[["Sie kam lachend herein.",0],["Er ging, ohne sich zu verabschieden.",1],["Ich lerne Türkisch, indem ich Serien schaue.",0],["Bevor du gehst, ruf mich an.",1],["Er antwortete, ohne nachzudenken.",1],["Sie fuhr singend nach Hause.",0]],"why":{"Sie kam lachend herein.":"Art: gülerek içeri girdi.","Er ging, ohne sich zu verabschieden.":"ohne zu: veda etmeden gitti.","Ich lerne Türkisch, indem ich Serien schaue.":"Mittel: dizi izleyerek.","Bevor du gehst, ruf mich an.":"bevor: gitmeden önce.","Er antwortete, ohne nachzudenken.":"ohne zu: düşünmeden cevap verdi.","Sie fuhr singend nach Hause.":"Art: şarkı söyleyerek eve gitti."},"e":"-arak/-erek beschreibt, *wie* oder *womit* etwas geschieht; -mAdAn sagt, was *nicht* oder *noch nicht* geschieht."},
    { id: "tr-b1-12.19", t: "listen", say: "Hiçbir şey söylemeden evden çıktı.", q: "Hör zu: Was tat die Person?",
      o: ["Sie verließ das Haus, ohne etwas zu sagen.", "Sie sagte etwas und ging.", "Sie kam ins Haus, ohne zu sprechen.", "Sie rief an, bevor sie ging."], a: 0,
      why: { 1: "*söylemeden* heißt „ohne zu sagen“, sie hat nichts gesagt.", 2: "*evden çıktı* = sie ging aus dem Haus, nicht hinein.", 3: "Von einem Anruf ist nicht die Rede." },
      e: "„Sie verließ das Haus, ohne etwas zu sagen.“ *söyle-me-den*; *evden çıktı* = ging aus dem Haus." },
    { id: "tr-b1-12.20", t: "dictation", say: "Her sabah işe yürüyerek gidiyorum, çünkü hava çok güzel.", a: ["Her sabah işe yürüyerek gidiyorum, çünkü hava çok güzel."],
      wrong: { "Her sabah işe yürürek gidiyorum, çünkü hava çok güzel.": "Nach Vokal ü braucht -arak/-erek den Puffer-**y**: yürü**y**erek.", "Her sabah işe yürüyarak gidiyorum, çünkü hava çok güzel.": "Letzter Vokal ist **ü** → -**erek**, nicht -arak.", "Her sabah işe yürüyerek gidiyorum, çünkü hava çok güzeldi.": "Der Satz steht im Präsens: *güzel* (nicht güzeldi)." },
      e: "„Jeden Morgen gehe ich zu Fuß zur Arbeit, weil das Wetter sehr schön ist.“ *yürüyerek* = zu Fuß." },
    { id: "tr-b1-12.21", t: "speak", say: "Çocuklar şarkı söyleyerek bahçeye koştu.",
      e: "„Die Kinder rannten singend in den Garten.“ *söyleyerek*: ö wie in „schön“, y wie „j“. *bahçeye*: ç = „tsch“, h hörbar. Typischer Fehler: *söyleyarak* mit a statt e." },
    { id: "tr-b1-12.22", t: "speak", say: "Hiçbir şey söylemeden evden çıktı.",
      e: "„Er verließ das Haus, ohne etwas zu sagen.“ *hiçbir*: h hörbar, ç = „tsch“. *söylemeden*: ö kurz, e kurz. Typischer Fehler: *şey* wie deutsches „sei“ statt „schej“ sprechen." },
    { id: "tr-b1-12.23", t: "speak", say: "Yemek yemeden önce ellerimi yıkarım.",
      e: "„Bevor ich esse, wasche ich mir die Hände.“ *yemeden*: y wie „j“, d zwischen Vokalen. *ellerimi*: ll deutlich lang. *yıkarım*: ı dumpf. Typischer Fehler: *yemedan* mit a (Harmonie: e → -meden)." },
    { id: "tr-b1-12.24", t: "respond", say: "Türkçeyi nasıl öğreniyorsun?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -arak/-erek, -mAdAn und olarak.",
      chunks: ["Film izleyerek …", "Çok konuşarak …", "Kelime çalışmadan …", "Ben … olarak …"],
      models: ["Ben Türkçeyi film izleyerek ve şarkı dinleyerek öğreniyorum. Her gün biraz konuşmadan uyumuyorum. Öğrenci olarak da haftada iki ders alıyorum.", "Çok konuşarak ve kelime yazarak öğreniyorum. Kitap okumadan önce yeni kelimelere bakıyorum. Hobi olarak Türkçe şarkı söylüyorum."],
      modelsN: ["Ich lerne Türkisch, indem ich Filme schaue und Lieder höre. Ich gehe nicht schlafen, ohne jeden Tag ein bisschen zu sprechen. Als Student nehme ich außerdem zwei Stunden pro Woche Unterricht.", "Ich lerne, indem ich viel spreche und Wörter aufschreibe. Bevor ich ein Buch lese, sehe ich mir die neuen Wörter an. Als Hobby singe ich türkische Lieder."],
      e: "**-arak/-erek** für das Mittel (izleyerek, konuşarak), **-mAdAn** für „ohne/bevor“ (konuşmadan, okumadan önce), **olarak** für „als“ (öğrenci olarak). Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-13', {
  lesson: [
    { p: "Argumentieren heißt: Gründe nennen („weil“, „da“) und Gegengründe zugeben („obwohl“, „trotzdem“). Im Deutschen leiten Konjunktionen den Nebensatz ein. Türkisch macht daraus eine **Verbform mit festem Anhängsel**: Der Nebensatz steht vor dem Hauptsatz, hat kein Komma-Wort am Anfang und endet auf *için*, *-DIğIndAn*, *rağmen* oder *halde*." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutscher Nebensatz", "Bauplan", "Türkisch"], rows: [
      ["Weil ich müde bin, …", "Stamm + **-DIk** + Possessiv + **için**", "Yorgun ol**duğum için** …"],
      ["Weil es regnet, …", "Stamm + -DIk + Poss. + için", "Yağmur yağ**dığı için** …"],
      ["Weil er nicht kam, …", "Stamm + **-mA-DIk** + Poss. + için", "O gel**mediği için** …"],
      ["Da das Wetter schlecht war, … (formell)", "Stamm + -DIk + Poss. + **-DAn**", "Hava kötü ol**duğundan** …"],
      ["Obwohl es regnet, …", "Stamm + **-mA** + Poss. + Dativ (**-nA**) + **rağmen**", "Yağmur yağ**masına rağmen** …"],
      ["Obwohl er müde war, …", "Stamm + -DIk + Poss. + **halde**", "Yorgun ol**duğu halde** …"]
    ] } },
    { p: "**Grund: -DIğI için.** Du nimmst die Partizipform auf -DIk, hängst die Possessivendung an (sie zeigt, **wer** handelt) und setzt *için* dahinter. Das k wird vor einem Vokal zu **ğ**: *geldiğim için, geldiğin için, geldiği için, geldiğimiz için, geldiğiniz için, geldikleri için*. Die Form steht für Gegenwart **und** Vergangenheit: *Hasta olduğum için gelmedim.* (Weil ich krank bin/war, bin ich nicht gekommen.) Für Zukünftiges nimmst du -(y)AcAk: *Yarın erken kalkacağım için bugün erken yatıyorum.* Verneint: -mA- vor -DIk: *gelmediği için*." },
    { p: "**Formeller: -DIğIndAn.** Mit dem Ablativ (*-DAn*) klingt der Grund geschriebener, etwa in Mitteilungen: *Hava kötü olduğundan maç iptal edildi.* Oft sagt man auch *olduğundan dolayı* oder *olması nedeniyle*. In der Alltagssprache ist *-DIğI için* üblicher." },
    { p: "**Gegengrund: rağmen und halde.** *rağmen* verlangt den **Dativ**: *Yağmur yağmasına rağmen …* Dazu passen beide Formen: **-mAsInA rağmen** (*çalışmasına rağmen*) und **-DIğInA rağmen** (*çalıştığına rağmen*), beide sind richtig und häufig. Mit **-DIğI halde** sagst du dasselbe ohne Dativ: *Yorgun olduğu halde çalıştı.* Auch hier zeigt die Possessivendung die Person: *olmama rağmen* (obwohl ich …), *olduğun halde* (obwohl du …)." },
    { p: "**Subjekt im Nebensatz:** Steht ein eigenes Subjekt davor, steht es bei -DIğI için und -DIğI halde meist im Nominativ (*Hava soğuk olduğu için …*). Bei -mAsInA rağmen siehst du oft den Genitiv: *Ali’nin çok çalışmasına rağmen …*; im Alltag lässt man ihn auch weg, wenn das Subjekt klar ist. Unbestimmte oder Natur-Subjekte (*yağmur, hava*) bleiben im Nominativ: *Yağmur yağmasına rağmen …*." },
    { warn: "Typische Fehler: *„hasta olmak için“* (das heißt „um krank zu werden“, ein Zweck; für „weil ich krank bin“ brauchst du -DIğI için), *„yağmur yağdığı rağmen“* (rağmen braucht den Dativ: yağdığı**na** rağmen oder yağma**sına** rağmen), *„geldiği için“* für „weil ich kam“ (die Possessivendung muss zur handelnden Person passen: geldiğ**im** için) und *„olduğ için“* (die Possessivendung darf nicht fehlen)." },
    { tip: "Unterscheide **Grund** und **Zweck**: *Geç kaldığım için özür dilerim* (weil ich mich verspätet habe) – *Geç kalmamak için erken çıktım* (um nicht zu spät zu kommen) – *Geç kalmaman için seni aradım* (damit du nicht zu spät kommst)." },
    { ex: [
      ["Hasta olduğum için bugün işe gidemedim.", "Weil ich krank bin, konnte ich heute nicht zur Arbeit gehen."],
      ["Otobüs gelmediği için taksiye bindik.", "Weil der Bus nicht kam, nahmen wir ein Taxi."],
      ["Hava kötü olduğundan toplantı ertelendi.", "Da das Wetter schlecht war, wurde die Besprechung verschoben."],
      ["Yağmur yağmasına rağmen yürüyüşe çıktık.", "Obwohl es regnete, gingen wir spazieren."],
      ["Yorgun olduğu halde çalışmaya devam etti.", "Obwohl sie müde war, arbeitete sie weiter."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-13.1", t: "gap", q: "Hasta ol___ için işe gelmedi. (olmak – Weil er krank ist, ist er nicht zur Arbeit gekommen.)", a: ["duğu"],
      wrong: { "du": "Es fehlt die Possessivendung, die zeigt, wer handelt: olduğ**u** için.", "dığı": "Letzter Vokal von *ol-* ist **o** → -duğu (u), nicht -dığı.", "duğum": "-um = „ich“. Hier handelt „er“: -u.", "ması": "-mAsI için meint einen Zweck („damit er krank ist“), keinen Grund." },
      e: "ol- + **duk** → ğ + **u** = **olduğu** için. Die Possessivendung -u steht für „er/sie“." },
    { id: "tr-b1-13.2", t: "gap", q: "Yağmur yağ___ için maç ertelendi. (yağmak – Weil es regnete, wurde das Spiel verschoben.)", a: ["dığı"],
      wrong: { "dı": "Bei -DIğI için fehlt hier die Endung: yağ**dığı** için.", "dığın": "-ın = „du“. Hier „es regnet“: -ı.", "ması": "-mAsI için meint einen Zweck („damit es regnet“), keinen Grund.", "tığı": "*yağ-* endet auf **ğ** (stimmhaft) → d bleibt: yağ**dığı**." },
      e: "yağ- + **dık** → ğ + **ı** = **yağdığı** için. Letzter Vokal **a** → ı." },
    { id: "tr-b1-13.3", t: "gap", q: "Çok çalış___ rağmen sınavı geçemedi. (Obwohl er viel gearbeitet hat, hat er die Prüfung nicht bestanden.)", a: ["masına", "tığına"],
      wrong: { "ması": "*rağmen* verlangt den Dativ: çalış**masına** rağmen.", "mesine": "Letzter Vokal von *çalış-* ist **ı** → -masına (a), nicht -mesine.", "tığı": "Auch hier fehlt der Dativ: çalıştığ**ına** rağmen.", "dığına": "*çalış-* endet auf **ş** (stimmlos) → d wird **t**: çalış**tığına**." },
      e: "çalış- + **ma** + **sı** + **na** = **çalışmasına** rağmen. Genauso richtig: çalış- + **tık** → ğ + **ı** + **na** = **çalıştığına** rağmen." },
    { id: "tr-b1-13.4", t: "gap", q: "Yorgun ol___ halde çalışmaya devam ettik. (Obwohl wir müde waren, arbeiteten wir weiter.)", a: ["duğumuz"],
      wrong: { "duğu": "-u = „er/sie“. Hier handelt „wir“: -umuz.", "dığımız": "Letzter Vokal von *ol-* ist **o** → -duğumuz (u).", "duk": "Die Possessivendung fehlt: olduğ**umuz** halde.", "masına": "Mit *halde* steht -DIğI, nicht -mAsInA (das gehört zu *rağmen*)." },
      e: "ol- + **duk** → ğ + **umuz** = **olduğumuz** halde." },
    { id: "tr-b1-13.5", t: "gap", q: "Otobüs geç gel___ için derse geç kaldım. (Weil der Bus spät kam, kam ich zu spät zum Unterricht.)", a: ["diği"],
      wrong: { "dığı": "Letzter Vokal von *gel-* ist **e** → -diği (i), nicht -dığı.", "diki": "Das k wird vor einem Vokal zu **ğ**: geldi**ği**.", "di": "Die Possessivendung fehlt: geldiğ**i** için.", "ince": "-(y)IncA heißt „als/sobald“ und nimmt kein *için*." },
      e: "gel- + **dik** → ğ + **i** = **geldiği** için. Der Bus (3. Person) → -i." },
    { id: "tr-b1-13.6", t: "gap", q: "Bu konuyu bil___ için toplantıda konuşmadım. (Weil ich dieses Thema nicht kannte, habe ich in der Besprechung nichts gesagt.)", a: ["mediğim"],
      wrong: { "madığım": "Letzter Vokal von *bil-* ist **i** → -mediğim (e), nicht -madığım.", "medim": "Das ist nur „ich kannte nicht“. Vor *için* braucht man -DIk + Possessiv.", "mediği": "-i = „er/sie“. Hier handelt „ich“: -im.", "meyen": "Das Partizip auf -(y)An hat keine Possessivendung und passt nicht vor *için*." },
      e: "bil- + **me** + **dik** → ğ + **im** = **bilmediğim** için. Die Verneinung -mA- steht vor -DIk." },
    { id: "tr-b1-13.7", t: "mc", q: "„Obwohl er Fieber hat, geht er zur Arbeit.“", o: ["Ateşi olmasına rağmen işe gidiyor.", "Ateşi olduğu için işe gidiyor.", "Ateşi olmadığı halde işe gidiyor.", "Ateşi olsa işe gidiyor."], a: 0,
      why: { 1: "*için* heißt „weil“: „Weil er Fieber hat, geht er zur Arbeit“ ergibt hier keinen Sinn.", 2: "*olmadığı* = „nicht hat“; gemeint ist aber „Fieber hat“.", 3: "-sA bedeutet „wenn“, nicht „obwohl“." },
      e: "ol- + **ma** + **sı** + **na** + rağmen = **olmasına rağmen** (obwohl er hat). Auch *ateşi olduğu halde* wäre möglich." },
    { id: "tr-b1-13.8", t: "mc", q: "„Weil wir den Zug verpasst haben, kamen wir zu spät.“", o: ["Treni kaçırdığımız için geç kaldık.", "Treni kaçırmamıza rağmen geç kaldık.", "Treni kaçırdığımızdan rağmen geç kaldık.", "Treni kaçırmak için geç kaldık."], a: 0,
      why: { 1: "*rağmen* = „obwohl“; die Aussage soll aber einen Grund nennen.", 2: "*rağmen* verlangt den Dativ und passt nicht zum Ablativ (-dan).", 3: "-mAk için = „um zu“, ein Zweck, kein Grund." },
      e: "kaçır- + **dık** → ğ + **ımız** + için = **kaçırdığımız için**." },
    { id: "tr-b1-13.9", t: "mc", q: "Welcher Satz nennt einen Gegengrund („obwohl“)?", o: ["Yorgun olduğu halde çalıştı.", "Yorgun olduğu için çalışmadı.", "Yorgun olduğundan dinlendi.", "Yorgun olduğu için erken yattı."], a: 0,
      why: { 1: "*için* nennt den Grund, hier für das Nicht-Arbeiten.", 2: "*-DIğIndAn* nennt einen Grund („da er müde war“).", 3: "*için* nennt einen Grund (müde → früh ins Bett)." },
      e: "*-DIğI halde* und *rağmen* widersprechen der Erwartung (müde, aber er arbeitete). *için* und *-DIğIndAn* nennen den Grund." },
    { id: "tr-b1-13.10", t: "mc", q: "Was ist der Unterschied zwischen *Gelmediği için* und *Gelmemesi için*?", o: ["gelmediği için = weil er nicht kam; gelmemesi için = damit er nicht kommt", "Es gibt keinen Unterschied.", "gelmediği için = damit er nicht kommt; gelmemesi için = weil er nicht kam", "Beide heißen „obwohl er nicht kam“."], a: 0,
      why: { 1: "Doch: Die eine Form nennt einen Grund (-DIğI), die andere einen Zweck (-mAsI).", 2: "Es ist genau umgekehrt.", 3: "„obwohl“ heißt *rağmen* oder *halde*." },
      e: "-DIğI için = Grund (Vergangenes/Tatsächliches). -mAsI için = Zweck („damit“), dort passiert noch nichts." },
    { id: "tr-b1-13.11", t: "mc", q: "„Da das Wetter schlecht war, wurde das Spiel abgesagt.“ (formell)", o: ["Hava kötü olduğundan maç iptal edildi.", "Hava kötü olmasına maç iptal edildi.", "Hava kötü olduğunda rağmen maç iptal edildi.", "Hava kötü olduğu halde maç iptal edildi."], a: 0,
      why: { 1: "-mAsInA nennt allein keinen Grund; mit *rağmen* hieße es „obwohl“.", 2: "*rağmen* heißt „obwohl“ und braucht den Dativ, nicht den Lokativ (-DA).", 3: "*halde* = „obwohl“; gemeint ist aber „da/weil“." },
      e: "ol- + **duk** → ğ + **u** + **n** + **dan** = **olduğundan** (formeller Grund)." },
    { id: "tr-b1-13.12", t: "mc", q: "„Obwohl du es mir gesagt hast, habe ich es vergessen.“", o: ["Sen bana söylediğin halde unuttum.", "Sen bana söylediğim halde unuttum.", "Sen bana söylemesine rağmen unuttum.", "Sen bana söylediğin için unuttum."], a: 0,
      why: { 1: "-im = „ich“. Hier hat „du“ gesprochen: -in.", 2: "-sI = „er/sie“, aber das Subjekt ist *sen* (du).", 3: "*için* = „weil“, nicht „obwohl“." },
      e: "söyle- + **dik** → ğ + **in** + halde = **söylediğin halde**. Die Possessivendung passt zu *sen*." },
    { id: "tr-b1-13.13", t: "order", q: "Bilde den Satz: „Weil ich krank war, bin ich zu Hause geblieben.“", w: ["Hasta", "olduğum", "için", "evde", "kaldım"], a: ["Hasta olduğum için evde kaldım"],
      e: "Der Nebensatz *hasta olduğum için* steht vor dem Hauptsatz *evde kaldım*; das Verb bleibt am Ende." },
    { id: "tr-b1-13.14", t: "order", q: "Bilde den Satz: „Obwohl es regnete, gingen wir spazieren.“", w: ["Yağmur", "yağmasına", "rağmen", "yürüyüşe", "çıktık"], a: ["Yağmur yağmasına rağmen yürüyüşe çıktık"],
      e: "*yağmur yağmasına rağmen* = obwohl es regnete. Der Dativ -(s)ına steht vor *rağmen*." },
    { id: "tr-b1-13.15", t: "order", q: "Bilde den Satz: „Obwohl sie müde war, arbeitete sie weiter.“", w: ["Yorgun", "olduğu", "halde", "çalışmaya", "devam", "etti"], a: ["Yorgun olduğu halde çalışmaya devam etti", "Çalışmaya yorgun olduğu halde devam etti"],
      e: "*yorgun olduğu halde* leitet den Gegengrund ein, *çalışmaya devam etti* (arbeitete weiter) folgt mit dem Verb am Ende." },
    { id: "tr-b1-13.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["geç kaldığım için", "weil ich mich verspätet habe"], ["geç kaldığımdan", "da ich mich verspätet habe (formeller)"], ["geç kalmasına rağmen", "obwohl er sich verspätet"], ["geç kalmamak için", "um nicht zu spät zu kommen"], ["geç kalmaman için", "damit du nicht zu spät kommst"]],
      e: "-DIğI için = Grund, -DIğIndAn = formeller Grund, rağmen = Gegengrund. -mAk için und -mAsI için drücken einen Zweck aus." },
    {"id":"tr-b1-13.17","t":"cloze","q":"Ergänze die Endungen.","text":"Hava çok soğuk ol{1} için dışarı çıkmadık. Hasta ol{2} rağmen işe gitti. Yorgun ol{3} halde çalıştım.","gaps":{"1":{"a":["duğu"],"wrong":{"du":"Die Possessivendung fehlt: olduğ**u** için.","dığı":"Letzter Vokal von *ol-* ist **o** → -duğu (u).","ması":"-mAsI için = Zweck („damit es kalt ist“), kein Grund."}},"2":{"a":["masına","duğuna"],"wrong":{"ması":"*rağmen* verlangt den Dativ: olmasına rağmen.","masını":"Der Akkusativ passt nicht zu *rağmen*; es braucht den Dativ -na.","mesine":"Letzter Vokal von *ol-* ist **o** → -masına (a)."}},"3":{"a":["duğum"],"wrong":{"duğu":"-u = „er/sie“. Hier handelt „ich“ (*çalıştım*): -um.","dığım":"Letzter Vokal von *ol-* ist **o** → -duğum (u).","duk":"Die Possessivendung fehlt: olduğ**um** halde."}}},"e":"için → -DIğI için; rağmen → -mAsInA oder -DIğInA (Dativ!); halde → -DIğI mit Possessivendung, die zur handelnden Person passt."},
    {"id":"tr-b1-13.18","t":"sort","q":"Grund oder Gegengrund? Ordne die Sätze zu.","cats":["Grund (weil, da)","Gegengrund (obwohl)"],"items":[["Yorgun olduğu için erken yattı.",0],["Yorgun olduğu halde işe gitti.",1],["Yağmur yağmasına rağmen maç oynandı.",1],["Yağmur yağdığı için maç iptal edildi.",0],["Bilet pahalı olduğundan gitmedik.",0],["Bilet pahalı olmasına rağmen aldık.",1]],"why":{"Yorgun olduğu için erken yattı.":"*için* nennt den Grund: Weil er müde war, ging er früh schlafen.","Yorgun olduğu halde işe gitti.":"*halde* nennt den Gegengrund: Obwohl er müde war, ging er zur Arbeit.","Yağmur yağmasına rağmen maç oynandı.":"*rağmen* = obwohl: Es regnete, trotzdem wurde gespielt.","Yağmur yağdığı için maç iptal edildi.":"*için* = weil: Der Regen ist der Grund der Absage.","Bilet pahalı olduğundan gitmedik.":"*-DIğIndAn* = da/weil: Der Preis hielt uns ab.","Bilet pahalı olmasına rağmen aldık.":"*rağmen* = obwohl: Wir kauften trotz des Preises."},"e":"için und -DIğIndAn nennen die Ursache, rağmen und halde widersprechen der Erwartung."},
    { id: "tr-b1-13.19", t: "listen", say: "Yağmur yağmasına rağmen yürüyüşe çıktık.", q: "Hör zu: Was ist passiert?",
      o: ["Sie sind trotz des Regens spazieren gegangen.", "Sie sind wegen des Regens zu Hause geblieben.", "Sie sind spazieren gegangen, damit es regnet.", "Nach dem Spaziergang hat es geregnet."], a: 0,
      why: { 1: "*rağmen* heißt „trotz“, nicht „wegen“. Sie sind gegangen.", 2: "Das wäre ein Zweck (-mAsI için); gesagt wird aber „trotz Regens“.", 3: "Der Regen kommt nicht erst danach; es regnet schon während des Spaziergangs." },
      e: "„Obwohl es regnete, gingen wir spazieren.“ *yağmasına rağmen* = trotz des Regens. *yürüyüşe çıktık* = wir gingen spazieren." },
    { id: "tr-b1-13.20", t: "dictation", say: "Sınavı geçemediği için çok üzgündü.", a: ["Sınavı geçemediği için çok üzgündü."],
      wrong: { "Sınavı geçemedi için çok üzgündü.": "Vor *için* braucht man -DIk + Possessiv: geçemedi**ği** için.", "Sınavı geçemediğiçin çok üzgündü.": "*için* wird getrennt geschrieben.", "Sınavı geçemediği için çok üzgün.": "Der Satz steht in der Vergangenheit: üzgün**dü**." },
      e: "„Weil sie die Prüfung nicht bestanden hat, war sie sehr traurig.“ geç- + **e** + **me** + **dik** → ğ + **i** + için. *üzgündü* = war traurig." },
    { id: "tr-b1-13.21", t: "speak", say: "Hasta olduğum için bugün işe gidemedim.",
      e: "„Weil ich krank bin, konnte ich heute nicht zur Arbeit gehen.“ *olduğum*: das ğ nach u wird nicht gesprochen, es dehnt den Vokal, also ol-duum. *gidemedim*: g wie in „gehen“, e kurz. Typischer Fehler: *oldukum* mit hartem k." },
    { id: "tr-b1-13.22", t: "speak", say: "Yorgun olduğu halde çalışmaya devam etti.",
      e: "„Obwohl sie müde war, arbeitete sie weiter.“ *halde*: h hörbar, hal-de. *çalışmaya*: ç = „tsch“, ş = „sch“, ı dumpf. Typischer Fehler: *yorgun* mit deutschem „-gun“ ohne klares u." },
    { id: "tr-b1-13.23", t: "speak", say: "Hava soğuk olduğu için kalın giyindik.",
      e: "„Weil es kalt war, haben wir uns dick angezogen.“ *soğuk*: ğ nach o dehnt den Vokal, also soo-uk (langes o), nicht „sog-uk“. *kalın*: ı dumpf, nicht „kalin“. Typischer Fehler: *giyindik* mit langem i statt kurzem." },
    { id: "tr-b1-13.24", t: "respond", say: "Neden Türkçe öğreniyorsun?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -DIğI için, rağmen oder -DIğI halde.",
      chunks: ["… olduğum için …", "… -mAsInA rağmen …", "… olduğu halde …", "Çünkü …"],
      models: ["Türkiye’de çok arkadaşım olduğu için Türkçe öğreniyorum. Dil zor olduğu halde her gün çalışıyorum. Yorgun olmama rağmen akşamları biraz tekrar yapıyorum.", "Türkçe konuşmak istediğim için bir kursa yazıldım. Zamanım az olmasına rağmen haftada üç kez derse gidiyorum."],
      modelsN: ["Ich lerne Türkisch, weil ich in der Türkei viele Freunde habe. Obwohl die Sprache schwer ist, übe ich jeden Tag. Obwohl ich müde bin, wiederhole ich abends ein bisschen.", "Weil ich Türkisch sprechen möchte, habe ich mich für einen Kurs angemeldet. Obwohl ich wenig Zeit habe, gehe ich dreimal pro Woche zum Unterricht."],
      e: "**weil** = -DIğI için (olduğum için), **obwohl** = -mAsInA rağmen oder -DIğI halde. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-04', {
  lesson: [
    { p: "Mit „wenn“ und „falls“ machst du eine Bedingung. Im Türkischen gibt es dafür **keine Konjunktion am Satzanfang**: Die Endung **-sA** wird ans Verb (oder ans Nomen) gehängt und trägt die Person: *gelirsen* = wenn du kommst. Das Wort **eğer** kannst du davorsetzen, es ist aber nur Verstärkung („falls“) und kann immer wegfallen." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutscher Nebensatz", "Bauplan", "Türkisch"], rows: [
      ["Wenn du kommst, …", "Aorist + **-sA** + Person", "(Eğer) gel**irsen** …"],
      ["Wenn es morgen regnet, …", "Aorist + -sA", "Yarın yağmur yağ**arsa** …"],
      ["Wenn du nicht kommst, …", "Verneinter Aorist (-mAz) + -sA", "Gel**mezsen** …"],
      ["Wenn du müde bist, …", "Nomen/Adjektiv + **-(y)sA** + Person", "Yorgun**san** …; Hasta**ysan** …"],
      ["Wenn du Zeit hast, …", "var/yok + -sA", "Vakti**n varsa** …"],
      ["Auch wenn es regnet, …", "Stamm + **-sA bile**", "Yağmur yağ**sa bile** …"]
    ] } },
    { p: "**Bedingung am Verb:** Meist hängst du -sA an die **Aorist-Form** (*gelir-sen, yağar-sa, yaparsanız, gelmezse*). Die Personalendungen nach -sA sind: **-m, -n, –, -k, -nIz, -lAr** (*gelirsem, gelirsen, gelirse, gelirsek, gelirseniz, gelirlerse*). Beim Aorist steht -lAr vor -sA (*gelirlerse*); bei -sA direkt am Stamm kommt es dahinter (*gelseler*). Die Vokalharmonie ist die kleine: **-sa** nach a, ı, o, u; **-se** nach e, i, ö, ü. Verneint: Aorist-Verneinung + -sA (*gelmezsen, yapmazsa*). Das ist die Standardform für **reale oder mögliche** Bedingungen." },
    { p: "**Bedingung am Nomen: -(y)sA.** Nach Vokal steht der Puffer-y: *hasta-**y**sam, hasta-**y**san, evde-**y**sen*; nach Konsonant nicht: *yorgun-san*. Mit *var/yok*: *vaktin varsa* (wenn du Zeit hast), *param yoksa* (wenn ich kein Geld habe). Auch *olursa* geht: *vaktin olursa*. Verneint: *hasta değilsen*." },
    { p: "**-sA direkt am Stamm:** Neben *gelirsen* gibt es **gelsen**. Das klingt oft nach „wenn du kämest“, also hypothetischer; manchmal schwingt auch ein Wunsch mit. Außerdem kann -sA an andere Zeitformen treten: *geliyorsan* (wenn du gerade kommst), *gideceksem* (wenn ich gehen werde), *gelmişse* (wenn er gekommen ist)." },
    { p: "**-sA bile = „auch wenn“:** Stamm + -sA + *bile*: *Yağmur yağsa bile giderim.* (Auch wenn es regnet, gehe ich.) Auch mit Nomen: *Pahalı olsa bile alırım.* Hier steht fast immer -sA direkt am Stamm. Der Aorist (*yağarsa bile*) ist ebenfalls möglich." },
    { warn: "Typische Fehler: *„hastasan“* (nach Vokal braucht -(y)sA den Puffer-y: hasta**y**san), *„gelmersen“* (die Verneinung im Aorist heißt -mAz: gel**mez**sen) und *„vaktin varsan“* (die Personalendung steht schon in *vaktin*, bei *var* kommt keine zweite dazu: vaktin varsa)." },
    { tip: "Kurzer Check: Hat dein deutscher Satz „wenn“ und eine **mögliche** Zukunft („wenn es regnet“)? Dann nimm Aorist + -sA. Geht es um „auch wenn“? Dann *-sA bile*. Geht es um „sobald“? Dann ist es eher -(y)IncA (Thema „wenn/als“)." },
    { ex: [
      ["Eğer vaktin varsa, bana yardım eder misin?", "Falls du Zeit hast, hilfst du mir?"],
      ["Yarın yağmur yağarsa evde kalırız.", "Wenn es morgen regnet, bleiben wir zu Hause."],
      ["Yorgunsan biraz dinlen.", "Wenn du müde bist, ruh dich ein bisschen aus."],
      ["Sen gelmezsen ben de gelmem.", "Wenn du nicht kommst, komme ich auch nicht."],
      ["Pahalı olsa bile bu ceketi alırım.", "Auch wenn sie teuer ist, kaufe ich diese Jacke."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-04.1", t: "gap", q: "Sen gel___ ben de gelirim. (gelmek – Wenn du kommst, komme ich auch.)", a: ["irsen", "sen"],
      wrong: { "irsin": "Nach -sA lautet die Endung für „du“ **-n**: gelirse**n**, nicht -sin.", "ırsan": "Letzter Vokal von *gel-* ist **e** → -irsen, nicht -ırsan.", "ince": "-(y)IncA heißt „sobald/als“; für „wenn“ braucht man -sA." },
      e: "gel- + **ir** + **se** + **n** = **gelirsen** (Aorist + -sA + du). Auch *gelsen* geht, klingt aber eher nach „wenn du kämest“." },
    { id: "tr-b1-04.2", t: "gap", q: "Hava güzel ol___ yürüyüşe çıkarız. (olmak – Wenn das Wetter schön ist, gehen wir spazieren.)", a: ["ursa", "sa"],
      wrong: { "ırsa": "Letzter Vokal von *ol-* ist **o** → *olursa* (u), nicht -ırsa.", "ursan": "-n = „du“. Hier „das Wetter“: keine Personalendung.", "unca": "-(y)IncA heißt „sobald“ und steht nicht für eine mögliche Bedingung." },
      e: "ol- + **ur** + **sa** = **olursa**. *olmak* hat den Aorist auf -ur. Auch *olsa* ist möglich, klingt aber hypothetischer." },
    { id: "tr-b1-04.3", t: "gap", q: "Çok yorgun___ erken yat. (Wenn du sehr müde bist, geh früh schlafen.)", a: ["san"],
      wrong: { "ysan": "*yorgun* endet auf Konsonant n → kein Puffer-y: yorgun**san**.", "sen": "Letzter Vokal von *yorgun* ist **u** → -sa (nicht -se).", "sın": "Die Endung lautet -sA + n: yorgun**san**; -sın wäre „du bist“." },
      e: "yorgun + **sa** + **n** = **yorgunsan** (wenn du müde bist). Nach Konsonant steht kein Puffer-y." },
    { id: "tr-b1-04.4", t: "gap", q: "Yarın gel___ lütfen önceden haber ver. (Wenn du morgen nicht kommst, gib bitte vorher Bescheid.)", a: ["mezsen", "mesen"],
      wrong: { "mazsan": "Letzter Vokal von *gel-* ist **e** → -mezsen (e).", "mersen": "Die Verneinung im Aorist heißt -mAz: gel**mez**sen, nicht -mer.", "meyince": "-(y)IncA heißt „sobald“; hier steht eine Bedingung." },
      e: "gel- + **mez** + **sen** = **gelmezsen** (Aorist-Verneinung + -sA + du). Auch *gelmesen* ist möglich, klingt aber hypothetischer." },
    { id: "tr-b1-04.5", t: "gap", q: "Yağmur yağ___ bile yürüyüşe çıkacağım. (Auch wenn es regnet, gehe ich spazieren.)", a: ["sa", "arsa"],
      wrong: { "se": "Letzter Vokal von *yağ-* ist **a** → -sa (nicht -se).", "ınca": "-(y)IncA heißt „sobald“; für „auch wenn“ braucht man -sA bile.", "dığı": "-DIğI halde wäre „obwohl“; mit *bile* steht -sA." },
      e: "yağ- + **sa** + bile = **yağsa bile** (auch wenn es regnet). Mit Aorist: *yağarsa bile* ist ebenfalls möglich." },
    { id: "tr-b1-04.6", t: "gap", q: "___ bana yardım eder misin? (Wenn du Zeit hast, hilfst du mir?)", a: ["Vaktin varsa", "Vaktin olursa", "Zamanın varsa", "Zamanın olursa"],
      wrong: { "Vaktin var": "Es fehlt -sA: Vaktin var**sa**.", "Vaktim varsa": "-im = „ich“. Hier hast „du“ Zeit: vakti**n**.", "Vaktin varsan": "Die Person steht schon in *vaktin*; *var* bekommt nur -sA (varsa)." },
      e: "vakit + **in** (dein) + var + **sa** = **vaktin varsa**. Das t in *vakit* fällt vor der Endung weg (vaktin)." },
    { id: "tr-b1-04.7", t: "mc", q: "„Wenn du nicht kommst, gehe ich allein.“", o: ["Gelmezsen yalnız giderim.", "Gelmediğin için yalnız giderim.", "Gelmeden yalnız giderim.", "Gelirsen yalnız giderim."], a: 0,
      why: { 1: "*için* nennt einen Grund („weil du nicht kommst“), keine Bedingung.", 2: "-mAdAn heißt „ohne zu / bevor“.", 3: "*gelirsen* = „wenn du kommst“; es fehlt die Verneinung." },
      e: "gel- + **mez** + **sen** = **gelmezsen** (wenn du nicht kommst)." },
    { id: "tr-b1-04.8", t: "mc", q: "„Wenn du krank bist, bleib zu Hause.“", o: ["Hastaysan evde kal.", "Hastasan evde kal.", "Hasta olduğun için evde kal.", "Hastaysın evde kal."], a: 0,
      why: { 1: "Nach dem Vokal a braucht -(y)sA den Puffer-y: hasta**y**san.", 2: "*olduğun için* nennt einen Grund („weil du krank bist“), keine Bedingung.", 3: "*hastaysın* wäre „du bist krank“ (-sIn ist die Personalendung der Aussage)." },
      e: "hasta + **y** + **sa** + **n** = **hastaysan**." },
    { id: "tr-b1-04.9", t: "mc", q: "„Auch wenn es teuer ist, kaufe ich es.“", o: ["Pahalı olsa bile alırım.", "Pahalı olduğu için alırım.", "Pahalıysa alırım.", "Pahalı olduğundan alırım."], a: 0,
      why: { 1: "*için* = „weil“; das nimmt den Gegensatz „auch wenn“ nicht auf.", 2: "*pahalıysa* = „wenn es teuer ist“, ohne das „auch“.", 3: "*-DIğIndAn* = „da es teuer ist“, ein Grund." },
      e: "ol- + **sa** + **bile** = **olsa bile** (auch wenn es ist)." },
    { id: "tr-b1-04.10", t: "mc", q: "Welcher Satz enthält eine Bedingung?", o: ["Vaktim olursa gelirim.", "Vaktim olduğu için geldim.", "Vaktim olmasına rağmen gelmedim.", "Vaktim olduğundan geldim."], a: 0,
      why: { 1: "*için* nennt einen Grund („weil“).", 2: "*rağmen* nennt einen Gegengrund („obwohl“).", 3: "*-DIğIndAn* nennt einen Grund („da“)." },
      e: "**Aorist + -sA** (*olursa*) = Bedingung („wenn ich Zeit habe, komme ich“)." },
    { id: "tr-b1-04.11", t: "mc", q: "Wofür steht *eğer* in *Eğer yarın gelirsen sevinirim*?", o: ["Es verstärkt die Bedingung („falls“) und kann weggelassen werden.", "Es ist Pflicht, sonst ist der Satz falsch.", "Es ersetzt die Endung -sA.", "Es steht immer hinter dem Verb."], a: 0,
      why: { 1: "*Yarın gelirsen sevinirim* ist ohne *eğer* völlig richtig.", 2: "*eğer* ersetzt -sA nicht; -sA bleibt nötig.", 3: "*eğer* steht normalerweise am Anfang des Nebensatzes." },
      e: "Die Bedingung steckt allein in -sA. *eğer* heißt „falls“ und macht den Satz nur deutlicher." },
    { id: "tr-b1-04.12", t: "mc", q: "„Wenn wir zu spät kommen, …“", o: ["Geç kalırsak …", "Geç kalırsan …", "Geç kalırsam …", "Geç kalırsanız …"], a: 0,
      why: { 1: "-sAn = „du“.", 2: "-sAm = „ich“.", 3: "-sAnIz = „ihr/Sie“." },
      e: "geç kal- + **ır** + **sa** + **k** = **geç kalırsak** (wir)." },
    { id: "tr-b1-04.13", t: "order", q: "Bilde den Satz: „Wenn du Zeit hast, ruf mich an.“", w: ["Vaktin", "varsa", "beni", "ara"], a: ["Vaktin varsa beni ara"],
      e: "Der Nebensatz *vaktin varsa* steht vorn, der Imperativ *ara* am Ende." },
    { id: "tr-b1-04.14", t: "order", q: "Bilde den Satz: „Wenn es morgen regnet, bleiben wir zu Hause.“", w: ["Yarın", "yağmur", "yağarsa", "evde", "kalırız"], a: ["Yarın yağmur yağarsa evde kalırız", "Yağmur yarın yağarsa evde kalırız"],
      e: "*yağarsa* ist Aorist + -sA; das Verb des Hauptsatzes *kalırız* steht am Ende." },
    { id: "tr-b1-04.15", t: "order", q: "Bilde den Satz: „Auch wenn es teuer ist, kaufe ich es.“", w: ["Pahalı", "olsa", "bile", "alırım"], a: ["Pahalı olsa bile alırım"],
      e: "*olsa bile* = auch wenn. Das Wort *bile* kommt direkt hinter die -sA-Form." },
    { id: "tr-b1-04.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["gelirsen", "wenn du kommst"], ["gelmezsen", "wenn du nicht kommst"], ["hastaysan", "wenn du krank bist"], ["vaktin varsa", "wenn du Zeit hast"], ["gelsen bile", "auch wenn du kämest"]],
      e: "-sA + Person trägt die Bedingung. *-sA bile* = „auch wenn“; mit *var* und Nomen nimmst du -(y)sA." },
    {"id":"tr-b1-04.17","t":"cloze","q":"Ergänze die Endungen.","text":"Yarın hava güzel ol{1} yürüyüşe çıkarız. Sen de gel{2} sevinirim. Yorgun{3} biraz dinlen.","gaps":{"1":{"a":["ursa","sa"],"wrong":{"ırsa":"Letzter Vokal von *ol-* ist **o** → olursa.","ursan":"-n = „du“; hier „das Wetter“.","unca":"-(y)IncA heißt „sobald“."}},"2":{"a":["irsen","sen"],"wrong":{"irsem":"-m = „ich“. Hier „du“ (*Sen*): -n.","ırsan":"Letzter Vokal von *gel-* ist **e** → gelirsen.","ince":"-(y)IncA heißt „sobald“; für „wenn“ braucht man -sA."}},"3":{"a":["san"],"wrong":{"ysan":"*yorgun* endet auf Konsonant → kein Puffer-y.","sen":"Letzter Vokal **u** → -sa.","sın":"-sIn wäre „du bist“, hier steht -sA + n."}}},"e":"Aorist + -sA + Person (olursa, gelirsen). Am Nomen: -(y)sA + Person (yorgunsan; nach Vokal mit y)."},
    {"id":"tr-b1-04.18","t":"sort","q":"Bedingung oder Einräumung? Ordne die Sätze zu.","cats":["Mögliche Bedingung (wenn)","Einräumung (auch wenn)"],"items":[["Yağmur yağarsa evde kalırız.",0],["Yağmur yağsa bile gideriz.",1],["Vaktin varsa gel.",0],["Vaktim olsa bile gelmem.",1],["Hastaysan doktora git.",0],["Pahalı olsa bile alırım.",1]],"why":{"Yağmur yağarsa evde kalırız.":"Aorist + -sA: Wenn es regnet, bleiben wir zu Hause.","Yağmur yağsa bile gideriz.":"*-sA bile*: Auch wenn es regnet, gehen wir.","Vaktin varsa gel.":"*varsa*: Wenn du Zeit hast, komm.","Vaktim olsa bile gelmem.":"*olsa bile*: Auch wenn ich Zeit hätte, käme ich nicht.","Hastaysan doktora git.":"*hastaysan*: Wenn du krank bist, geh zum Arzt.","Pahalı olsa bile alırım.":"*olsa bile*: Auch wenn es teuer ist, kaufe ich es."},"e":"-sA allein nennt die Bedingung, -sA + *bile* räumt ein („auch wenn“)."},
    { id: "tr-b1-04.19", t: "listen", say: "Yarın yağmur yağarsa evde kalırız.", q: "Hör zu: Was wird gesagt?",
      o: ["Falls es morgen regnet, bleiben wir zu Hause.", "Weil es gestern geregnet hat, blieben wir zu Hause.", "Auch bei Regen gehen wir hinaus.", "Wir bleiben zu Hause, damit es regnet."], a: 0,
      why: { 1: "*yarın* heißt „morgen“, und *yağarsa* ist keine Vergangenheit.", 2: "„Auch bei Regen“ wäre *yağsa bile*.", 3: "Das wäre ein Zweck (-mAsI için)." },
      e: "„Wenn es morgen regnet, bleiben wir zu Hause.“ *yağarsa* = Aorist + -sA." },
    { id: "tr-b1-04.20", t: "dictation", say: "Vaktin varsa bana yardım eder misin?", a: ["Vaktin varsa bana yardım eder misin?"],
      wrong: { "Vaktin varsan bana yardım eder misin?": "Die Person steht schon in *vaktin*, bei *var* gibt es kein zweites -n.", "Vaktin varsa bana yardım edermisin?": "*mi* wird getrennt geschrieben: eder **mi**sin.", "Vaktin var bana yardım eder misin?": "Es fehlt -sA: var**sa**." },
      e: "„Wenn du Zeit hast, hilfst du mir?“ *vakit* + in + *varsa*; *eder misin* = Aorist + Fragepartikel + Person." },
    { id: "tr-b1-04.21", t: "speak", say: "Yarın hava güzel olursa yürüyüşe çıkarız.",
      e: "„Wenn das Wetter morgen schön ist, gehen wir spazieren.“ *olursa*: das s ist immer stimmlos wie in „Haus“, nie weich wie in „Sonne“. *yürüyüşe*: y wie „j“, ü gerundet wie in „Brücke“, ş = „sch“. Typischer Fehler: *olursa* mit „-ırsa“." },
    { id: "tr-b1-04.22", t: "speak", say: "Yorgunsan biraz dinlenebilirsin.",
      e: "„Wenn du müde bist, kannst du dich ein bisschen ausruhen.“ *yorgunsan*: g wie in „gehen“, u kurz. *dinlenebilirsin*: ein langes Wort, in Silben: din-le-ne-bi-lir-sin. Typischer Fehler: *yorgunsun* statt *yorgunsan*." },
    { id: "tr-b1-04.23", t: "speak", say: "Pahalı olsa bile bu ceketi alırım.",
      e: "„Auch wenn sie teuer ist, kaufe ich diese Jacke.“ *pahalı*: h deutlich hörbar, ı dumpf: pa-ha-lı. *ceketi*: c wie „dsch“. Typischer Fehler: *pahalı* ohne h." },
    { id: "tr-b1-04.24", t: "respond", say: "Hafta sonu hava güzel olursa ne yapacaksın?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze -sA (Aorist + -sA oder -(y)sA) und möglichst einmal -sA bile.",
      chunks: ["Hava güzel olursa …", "Vaktim varsa …", "… olsa bile …", "Yorgunsam …"],
      models: ["Hava güzel olursa arkadaşlarımla parka giderim. Vaktim varsa biraz da bisiklete binerim. Yağmur yağsa bile bir kafeye gideceğim.", "Hafta sonu hava güzel olursa ailemle yürüyüşe çıkarız. Yorgunsam evde kalır, kitap okurum."],
      modelsN: ["Wenn das Wetter schön ist, gehe ich mit Freunden in den Park. Wenn ich Zeit habe, fahre ich auch ein bisschen Rad. Auch wenn es regnet, gehe ich in ein Café.", "Wenn das Wetter am Wochenende schön ist, gehen wir mit der Familie spazieren. Wenn ich müde bin, bleibe ich zu Hause und lese ein Buch."],
      e: "**wenn** = Aorist + -sA (olursa, giderse) oder -(y)sA am Nomen (yorgunsam). **auch wenn** = -sA bile. Deine Antwort darf ganz anders sein." }
  ]
});

K.add('tr-b1-15', {
  lesson: [
    { p: "Zwei Dinge, die man im Alltag ständig tut: sich etwas **wünschen oder bedauern** („Hätte ich doch mehr Zeit!“, „Wäre ich doch früher gegangen!“) und **etwas vermuten** („Er ist wohl zu Hause.“). Das Deutsche nutzt dafür Konjunktiv, „doch“, „wohl“, „vielleicht“. Türkisch hat feste Bausteine dafür: **keşke** + -sA / -sAydI für Wünsche, **-DIr, herhalde, galiba** und **-(y)Abilir** für Vermutungen." },
    { h: "Der Bauplan" },
    { table: { head: ["Deutsch", "Bauplan", "Türkisch"], rows: [
      ["Hätte ich doch mehr Zeit!", "**keşke** + Stamm + **-sA** + Person", "Keşke daha çok vaktim ol**sa**!"],
      ["Wäre ich doch gestern gekommen!", "keşke + Stamm + **-sAydI** + Person", "Keşke dün gel**seydim**!"],
      ["Er ist wohl zu Hause.", "Nomen/Ort + **-DIr** oder **herhalde**", "Herhalde evde**dir**."],
      ["Ich glaube, es regnet morgen.", "**galiba** + Satz", "Galiba yarın yağmur yağacak."],
      ["Es kann sein, dass es regnet.", "Stamm + **-(y)Abilir**", "Yağmur yağ**abilir**."]
    ] } },
    { p: "**Wunsch: keşke + -sA.** Für Gegenwart und Zukunft hängst du -sA **direkt an den Stamm** (kein Aorist!) und setzt die Person dahinter: *Keşke daha çok param olsa.* (Hätte ich doch mehr Geld.) *Keşke yarın gelse.* (Wenn er doch morgen käme.) Die Personalendungen nach -sA: -m, -n, –, -k, -nIz, -lAr (*olsam, olsan, olsa, olsak, olsanız, olsalar*)." },
    { p: "**Bedauern in der Vergangenheit: keşke + -sAydI.** Wenn etwas nicht geschehen ist und du das bedauerst, nimmst du **-sAydI** mit Person: *Keşke dün erken yatsaydım.* (Wäre ich doch gestern früh schlafen gegangen.) Die Formen: **-saydım, -saydın, -saydı, -saydık, -saydınız, -saydılar** (nach a, ı, o, u) und **-seydim, -seydin …** (nach e, i, ö, ü). Auch für Gegenwart sagt man oft *-sAydI*: *Keşke burada olsaydın.* (Wärst du doch hier.)" },
    { p: "**Vermutung: -DIr.** **-DIr** hat zwei Gesichter: Es drückt sichere oder formelle Feststellungen aus (*Ankara Türkiye’nin başkentidir.*) und Vermutungen, vor allem bei Verben und Zuständen oder zusammen mit *herhalde* (*Ali şimdi evdedir.* = Ali ist jetzt wohl zu Hause). Die Form folgt der **großen** Harmonie: **-dir/-dır/-dur/-dür**, nach stimmlosem Konsonant **-tir/-tır/-tur/-tür** (*hastadır, güzeldir, yorgundur, kitaptır*). Am Verb: *gitmiştir* (er ist wohl gegangen), *gelecektir* (er wird wohl kommen). Im Alltag stützt man die Vermutung oft mit **herhalde** („wohl, vermutlich“) oder **galiba** („wohl, ich glaube“): *Herhalde yorgunsun.* – *Galiba yağmur yağacak.*" },
    { p: "**Möglichkeit: -(y)Abilir / olabilir.** *Yağmur yağabilir.* (Es kann regnen.) *Bu doğru olabilir.* (Das kann stimmen.) Das ist schwächer als -DIr oder herhalde. Mit **belki** (vielleicht) wird es noch offener: *Belki yağmur yağar.*" },
    { warn: "Typische Fehler: *„Keşke olursa“* (mit keşke steht -sA direkt am Stamm: ol**sa**, nicht der Aorist), *„Keşke dün gelsem“* (-sAm gilt für Gegenwart und Zukunft; für Vergangenes -sAydIm: gel**seydim**), *„evdetir“* (nach Vokal steht -dir: evde**dir**; -tir/-tır gibt es nur nach stimmlosem Konsonanten wie in *kitap**tır***) und die Harmonie bei -sAydI (*gelsaydım* ist falsch: gel**seydim**)." },
    { tip: "Merksatz: **-sA** = „wenn doch (jetzt/später)“, **-sAydI** = „wäre doch (damals)“. Eine Vermutung klingt meist schwächer mit *olabilir*, stärker mit *galiba* oder *herhalde*; *-DIr* kommt oft zusammen mit *herhalde* vor." },
    { ex: [
      ["Keşke daha çok param olsa.", "Hätte ich doch mehr Geld."],
      ["Keşke dün erken yatsaydım.", "Wäre ich doch gestern früher schlafen gegangen."],
      ["Annem şimdi herhalde evdedir.", "Meine Mutter ist jetzt wohl zu Hause."],
      ["Galiba yarın yağmur yağacak.", "Ich glaube, morgen wird es regnen."],
      ["Bu yol kapalı olabilir.", "Diese Straße kann gesperrt sein."]
    ] }
  ],
  exercises: [
    { id: "tr-b1-15.1", t: "gap", q: "Keşke daha çok param ol___. (olmak – Hätte ich doch mehr Geld!)", a: ["sa", "saydı"],
      wrong: { "ursa": "Mit *keşke* steht -sA direkt am Stamm, nicht am Aorist: ol**sa**.", "sam": "Die Person steht schon in *param* (mein Geld); nach *olsa* kommt keine weitere Endung.", "sun": "Die Endung heißt -sA (nicht -sU): ol**sa**." },
      e: "ol- + **sa** = **olsa**. Auch *olsaydı* ist möglich, es klingt noch etwas stärker bedauernd." },
    { id: "tr-b1-15.2", t: "gap", q: "Keşke dün erken yat___. (yatmak – Wäre ich doch gestern früh schlafen gegangen!)", a: ["saydım"],
      wrong: { "sam": "-sAm bezieht sich auf Gegenwart oder Zukunft. Für Vergangenes braucht man -sAydIm.", "seydim": "Letzter Vokal von *yat-* ist **a** → -saydım (a), nicht -seydim.", "saydın": "-ın = „du“. Hier handelt „ich“: -ım." },
      e: "yat- + **say** + **dım** = **yatsaydım**. -sAydI + Person drückt das Bedauern über Vergangenes aus." },
    { id: "tr-b1-15.3", t: "gap", q: "Keşke sen de bizimle gel___. (gelmek – Wärst du doch mit uns gekommen!)", a: ["seydin"],
      wrong: { "seydim": "-im = „ich“. Hier wird „du“ angesprochen (*sen*): -in.", "saydın": "Letzter Vokal von *gel-* ist **e** → -seydin (e).", "sen": "-sen = „wenn du kommst/kämest“ (Gegenwart, Zukunft); für Vergangenes braucht man -sAydIn." },
      e: "gel- + **sey** + **din** = **gelseydin**." },
    { id: "tr-b1-15.4", t: "gap", q: "Ali şimdi evde___. (Ali ist jetzt wohl zu Hause.)", a: ["dir"],
      wrong: { "dır": "Letzter Vokal von *evde* ist **e** → -dir (i), nicht -dır.", "tir": "*evde* endet auf einen Vokal; -tir steht nur nach stimmlosem Konsonanten.", "dur": "-dur steht nach o oder u." },
      e: "evde + **dir** = **evdedir**. -DIr drückt aus, dass man etwas vermutet („wohl“)." },
    { id: "tr-b1-15.5", t: "gap", q: "Bu çanta herhalde çok pahalı___. (Diese Tasche ist vermutlich sehr teuer.)", a: ["dır"],
      wrong: { "dir": "Letzter Vokal von *pahalı* ist **ı** → -dır (ı), nicht -dir.", "tır": "*pahalı* endet auf einen Vokal; -tır steht nur nach stimmlosem Konsonanten.", "dar": "Die Endung heißt -DIr (mit i/ı/u/ü), nicht -dar." },
      e: "pahalı + **dır** = **pahalıdır**. *herhalde* stützt die Vermutung." },
    { id: "tr-b1-15.6", t: "gap", q: "___ yarın yağmur yağacak. (Vermutlich wird es morgen regnen.)", a: ["Galiba", "Herhalde", "Belki", "Muhtemelen", "Sanırım"],
      wrong: { "Keşke": "*keşke* drückt einen Wunsch aus („hätte ich doch“), keine Vermutung.", "Çünkü": "*çünkü* heißt „weil“ und leitet einen Grund ein.", "Ne zaman": "*ne zaman* heißt „wann“ und stellt eine Frage." },
      e: "*galiba*, *herhalde*, *muhtemelen* und *sanırım* = „wohl/vermutlich/ich glaube“. *belki* heißt „vielleicht“ und ist offener." },
    { id: "tr-b1-15.7", t: "mc", q: "„Hätte ich doch mehr Zeit!“", o: ["Keşke daha çok vaktim olsa!", "Keşke daha çok vaktim olacak!", "Keşke daha çok vaktim vardır!", "Keşke daha çok vaktim olursa!"], a: 0,
      why: { 1: "*olacak* ist Futur („wird sein“); *keşke* verlangt -sA.", 2: "*vardır* ist eine Aussage/Vermutung.", 3: "*olursa* ist eine Bedingung („wenn ich habe“), kein Wunsch." },
      e: "keşke + ol- + **sa** (Wunsch, Gegenwart/Zukunft)." },
    { id: "tr-b1-15.8", t: "mc", q: "„Wäre ich doch gestern gekommen!“", o: ["Keşke dün gelseydim!", "Keşke dün gelsem!", "Keşke dün geliyorum!", "Keşke dün geldim!"], a: 0,
      why: { 1: "-sAm gilt für Gegenwart oder Zukunft („käme ich doch“). Für gestern braucht man -sAydIm.", 2: "*geliyorum* ist eine Aussage im Präsens.", 3: "*geldim* ist eine Aussage („ich kam“), kein Bedauern." },
      e: "gel- + **sey** + **dim** = **gelseydim** (-sAydI + Person für Vergangenes)." },
    { id: "tr-b1-15.9", t: "mc", q: "„Er ist wohl schon gegangen.“", o: ["Herhalde gitmiştir.", "Herhalde gidecektir.", "Keşke gitmiştir.", "Herhalde gitsin."], a: 0,
      why: { 1: "*gidecektir* = „er wird wohl gehen“, also Zukunft.", 2: "*keşke* drückt einen Wunsch aus.", 3: "*gitsin* = „er soll gehen“ (Aufforderung)." },
      e: "git- + **miş** + **tir** = **gitmiştir** (vermutlich schon geschehen). *herhalde* verstärkt die Vermutung." },
    { id: "tr-b1-15.10", t: "mc", q: "Welcher Satz drückt eine Vermutung aus?", o: ["Ali herhalde evdedir.", "Keşke Ali evde olsa.", "Ali evde olursa ararım.", "Ali evde olduğu için aradım."], a: 0,
      why: { 1: "*keşke … olsa* ist ein Wunsch.", 2: "*olursa* = Bedingung („wenn er zu Hause ist“).", 3: "*olduğu için* = „weil er zu Hause ist“, ein Grund." },
      e: "*herhalde* und -DIr zeigen: Der Sprecher vermutet, ist aber nicht ganz sicher." },
    { id: "tr-b1-15.11", t: "mc", q: "„Die Tasche ist vermutlich in der Küche.“ Çanta herhalde mutfakta ___.", o: ["-dır", "-tır", "-dur", "-dir"], a: 0,
      why: { 1: "*mutfakta* endet auf **a**, nicht auf einen stimmlosen Konsonanten: -tır gehört nach f, s, t, k, ç, ş, h, p.", 2: "-dur steht nur nach o oder u.", 3: "Letzter Vokal von *mutfakta* ist **a** → -dır, nicht -dir." },
      e: "mutfakta + **dır** = **mutfaktadır**. Die große Harmonie (ı/i/u/ü) richtet sich nach dem letzten Vokal." },
    { id: "tr-b1-15.12", t: "mc", q: "„Es kann sein, dass er krank ist.“", o: ["Hasta olabilir.", "Hasta olsun.", "Hasta olsa bile gelir.", "Keşke hasta olmasa."], a: 0,
      why: { 1: "*olsun* = „er soll sein / möge sein“ (Wunsch/Aufforderung).", 2: "*olsa bile* = „auch wenn er krank ist“.", 3: "*keşke … olmasa* = „wäre er doch nicht krank“, ein Wunsch." },
      e: "ol- + **abil** + **ir** = **olabilir** (es ist möglich)." },
    { id: "tr-b1-15.13", t: "order", q: "Bilde den Satz: „Hätte ich doch mehr Zeit!“", w: ["Keşke", "daha", "çok", "vaktim", "olsa"], a: ["Keşke daha çok vaktim olsa", "Keşke vaktim daha çok olsa"],
      e: "*keşke* steht am Anfang, *olsa* am Ende. *daha çok* gehört zu *vaktim*." },
    { id: "tr-b1-15.14", t: "order", q: "Bilde den Satz: „Wäre ich doch gestern früher gegangen!“", w: ["Keşke", "dün", "daha", "erken", "çıksaydım"], a: ["Keşke dün daha erken çıksaydım"],
      e: "*çıksaydım* = çık- + saydım (Vergangenes, bedauert). Das Verb steht am Ende." },
    { id: "tr-b1-15.15", t: "order", q: "Bilde den Satz: „Ali ist jetzt wohl zu Hause.“", w: ["Ali", "herhalde", "şimdi", "evdedir"], a: ["Ali herhalde şimdi evdedir", "Herhalde Ali şimdi evdedir", "Ali şimdi herhalde evdedir", "Ali şimdi evdedir herhalde"],
      e: "*herhalde* kann mehrere Plätze vor dem Prädikat einnehmen; in der Umgangssprache steht es oft auch nachgestellt (*… evdedir herhalde*)." },
    { id: "tr-b1-15.16", t: "match", q: "Ordne die Form der Bedeutung zu:", p: [["keşke gelse", "wenn er doch käme"], ["keşke gelseydi", "wäre er doch gekommen"], ["herhalde gelmiştir", "er ist wohl gekommen"], ["galiba yağmur yağacak", "ich glaube, es wird regnen"], ["yağmur yağabilir", "es kann regnen"]],
      e: "keşke + -sA/-sAydI = Wunsch/Bedauern; herhalde, -DIr, galiba = Vermutung; -(y)Abilir = Möglichkeit." },
    {"id":"tr-b1-15.17","t":"cloze","q":"Ergänze die Endungen.","text":"Keşke daha çok param ol{1}. Keşke ben dün sana yardım et{2}. Annem şimdi herhalde evde{3}.","gaps":{"1":{"a":["sa","saydı"],"wrong":{"ursa":"Mit *keşke* steht -sA direkt am Stamm: ol**sa**.","sam":"Die Person steht schon in *param*.","sun":"Die Endung heißt -sA, nicht -sU."}},"2":{"a":["seydim"],"wrong":{"saydım":"Letzter Vokal von *et-* ist **e** → -seydim.","sem":"-sAm bezieht sich auf Gegenwart/Zukunft; für gestern braucht man -sAydIm.","seydin":"-in = „du“; hier handelt „ich“: -im."}},"3":{"a":["dir"],"wrong":{"dır":"Letzter Vokal von *evde* ist **e** → -dir.","tir":"*evde* endet auf Vokal → -dir, nicht -tir.","sa":"-sA wäre eine Bedingung; die Vermutung braucht -DIr."}}},"e":"Wunsch: keşke + -sA / -sAydI + Person. Vermutung: -DIr in der großen Harmonie, hinter Vokal -dir/-dır."},
    {"id":"tr-b1-15.18","t":"sort","q":"Wunsch oder Vermutung? Ordne die Sätze zu.","cats":["Wunsch / Bedauern","Vermutung / Möglichkeit"],"items":[["Keşke yarın gelse.",0],["Herhalde evdedir.",1],["Keşke dün çalışsaydım.",0],["Galiba hastadır.",1],["Yağmur yağabilir.",1],["Keşke daha çok param olsa.",0]],"why":{"Keşke yarın gelse.":"*keşke … -sA* = Wenn er doch morgen käme (Wunsch).","Herhalde evdedir.":"*herhalde … -DIr* = Er ist wohl zu Hause (Vermutung).","Keşke dün çalışsaydım.":"*keşke … -sAydIm* = Hätte ich doch gestern gearbeitet (Bedauern).","Galiba hastadır.":"*galiba … -DIr* = Er ist wohl krank (Vermutung).","Yağmur yağabilir.":"*-(y)Abilir* = Es kann regnen (Möglichkeit).","Keşke daha çok param olsa.":"*keşke … -sA* = Hätte ich doch mehr Geld (Wunsch)."},"e":"keşke + -sA / -sAydI drückt Wunsch und Bedauern aus; herhalde, galiba, -DIr und -(y)Abilir drücken Vermutung und Möglichkeit aus."},
    { id: "tr-b1-15.19", t: "listen", say: "Keşke dün daha erken yatsaydım.", q: "Hör zu: Was bedauert die Person?",
      o: ["Sie ist gestern nicht früh genug ins Bett gegangen.", "Sie ist heute zu früh ins Bett gegangen.", "Sie will morgen früh ins Bett gehen.", "Sie ist gestern zu früh aufgestanden."], a: 0,
      why: { 1: "*dün* heißt „gestern“, nicht „heute“.", 2: "-sAydIm bedauert Vergangenes und nennt keinen Plan für morgen.", 3: "*yatmak* heißt „ins Bett gehen“, nicht „aufstehen“." },
      e: "„Wäre ich doch gestern früher ins Bett gegangen.“ *yatsaydım* = yat- + saydım (Bedauern)." },
    { id: "tr-b1-15.20", t: "dictation", say: "Galiba bu akşam yağmur yağacak.", a: ["Galiba bu akşam yağmur yağacak."],
      wrong: { "Galiba bu akşam yağmur yağıcak.": "Geschrieben wird -acak nach a: yağ**acak**.", "Galiba bu akşam yağmur yağcak.": "In der Schrift braucht das Futur den Bindevokal: yağ**acak**.", "Galiba bu aksam yağmur yağacak.": "*akşam* wird mit ş geschrieben." },
      e: "„Ich glaube, heute Abend wird es regnen.“ *yağ- + acak* (Futur); *galiba* = wohl." },
    { id: "tr-b1-15.21", t: "speak", say: "Keşke daha çok vaktim olsa.",
      e: "„Hätte ich doch mehr Zeit.“ *keşke*: ş = „sch“, e kurz: kesch-ke. *vaktim*: v wie „w“, kt-Gruppe deutlich. Typischer Fehler: *keske* mit s." },
    { id: "tr-b1-15.22", t: "speak", say: "Keşke dün erken yatsaydım.",
      e: "„Wäre ich doch gestern früh schlafen gegangen.“ *yatsaydım*: y wie „j“, ı dumpf. Betonung auf -say-: yat-SAY-dım (-dım bleibt unbetont, wie bei gel-SEY-dim). Typischer Fehler: *yatseydim* mit e." },
    { id: "tr-b1-15.23", t: "speak", say: "Herhalde annem şimdi evdedir.",
      e: "„Meine Mutter ist jetzt wohl zu Hause.“ *herhalde*: zweimal h hörbar, her-hal-de. *evdedir*: v wie „w“, d zwischen Vokalen. Typischer Fehler: *herhalde* ohne das erste h." },
    { id: "tr-b1-15.24", t: "respond", say: "Hayatında neyi farklı yapmak isterdin?",
      q: "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze keşke + -sA/-sAydI und mindestens eine Vermutung (herhalde, galiba, -DIr).",
      chunks: ["Keşke … olsa.", "Keşke … -sAydIm.", "Herhalde …", "Galiba …"],
      models: ["Keşke daha çok seyahat etseydim. Keşke şimdi daha çok vaktim olsa. Galiba ileride daha çok zamanım olacak.", "Keşke gençken yabancı dil öğrenseydim. Herhalde bu yüzden şimdi Türkçeyi daha zor öğreniyorum."],
      modelsN: ["Wäre ich doch mehr gereist. Hätte ich jetzt doch mehr Zeit. Ich glaube, ich werde später mehr Zeit haben.", "Hätte ich doch als junger Mensch eine Fremdsprache gelernt. Wahrscheinlich lerne ich deshalb jetzt Türkisch schwerer."],
      e: "**Wunsch** = keşke + -sA (Gegenwart/Zukunft) oder -sAydI (Vergangenheit); **Vermutung** = herhalde, galiba, -DIr. Deine Antwort darf ganz anders sein." }
  ]
});

K.add("tr-b1-05", {
  lesson: [{"p": "Im Deutschen sagst du „die Tür **wird geöffnet**“, „der Brief **wurde geschrieben**“ oder „hier **darf** nicht **geraucht werden**“. Türkisch bildet das Passiv mit einem **Suffix direkt am Verbstamm**: -Il, -In oder -n. Es gibt keine Hilfsverben wie „werden“. Der Handelnde bleibt meist ungenannt; wenn du ihn nennst, nimmst du **tarafından** („von“)."}, {"h": "Der Bauplan"}, {"table": {"head": ["Deutsch", "Bauplan", "Türkisch"], "rows": [["Der Brief wurde geschrieben.", "Stamm auf Konsonant + **-Il** + Zeit", "Mektup yaz**ıl**dı."], ["Die Tür wird geöffnet.", "Stamm + -Il + -Iyor", "Kapı aç**ıl**ıyor."], ["Das Buch wird viel gelesen.", "Stamm auf **Vokal** + **-n**", "Kitap çok oku**n**uyor."], ["Das Paket wurde abgeholt.", "Stamm auf **l** + **-In**", "Paket al**ın**dı."], ["Hier wird Türkisch gesprochen.", "Stamm + -Il + Aorist", "Burada Türkçe konuş**ul**ur."], ["Das Fenster wurde vom Kind zerbrochen.", "… **tarafından** + Passiv", "Cam çocuk **tarafından** kır**ıl**dı."]]}}, {"p": "**Welches Suffix?** Die Vokalharmonie entscheidet über ı/i/u/ü: *yap-ıl-mak, gör-ül-mek, konuş-ul-mak*. Endet der Stamm auf einen **Vokal**, steht nur **-n**: *oku-n-mak, imzala-n-mak*. Endet er auf **l**, steht **-In**: *al-ın-mak, bil-in-mek, bul-un-mak*. In allen anderen Fällen nimmst du **-Il**."}, {"p": "**Das Subjekt** des Passivsatzes steht im Nominativ, ohne Akkusativendung: *Mektup yazıldı* (nicht *mektubu yazıldı*). Typisch türkisch ist das **unpersönliche Passiv** mit „man“: *Burada sigara içilmez.* (Hier wird nicht geraucht / Hier darf man nicht rauchen.) *Türkiye’de çay çok içilir.* Im Alltag sagt man oft auch aktiv, z. B. *„Burada Türkçe konuşuyorlar“* (man spricht hier Türkisch)."}, {"warn": "Typische Fehler: *„Kapıyı açıldı“* (das Subjekt des Passivs ist nicht Objekt: Kapı açıldı), *„okulur“* (nach Vokal nur -n: oku**n**ur), *„bililmek“* (nach l steht -In: bil**in**mek), *„yazıldı tarafından Ali“* (tarafından steht **nach** dem Handelnden, vor dem Verb: Ali tarafından yazıldı)."}, {"tip": "Merkregel: Vokal → **-n**, l → **-In**, sonst → **-Il**. *Aç-ıl-mak* (geöffnet werden) ≠ *aç-mak* (öffnen). Was im Deutschen „wird … -t“ ist, ist im Türkischen ein einziges Wort."}, {"ex": [["Mektup dün akşam yazıldı.", "Der Brief wurde gestern Abend geschrieben."], ["Burada Türkçe konuşulur.", "Hier wird Türkisch gesprochen."], ["Bu kitap çok okunuyor.", "Dieses Buch wird viel gelesen."], ["Paket postadan alındı.", "Das Paket wurde bei der Post abgeholt."], ["Cam çocuk tarafından kırıldı.", "Das Fenster wurde vom Kind zerbrochen."]]}],
  exercises: [
    {"id": "tr-b1-05.1", "t": "gap", "q": "Mektup dün akşam yaz___. (Der Brief wurde gestern Abend geschrieben.)", "a": ["ıldı"], "wrong": {"ildi": "Letzter Vokal von *yaz-* ist **a** → -ıl (nicht -il).", "ındı": "*yaz-* endet auf z, nicht auf l: Es braucht -Il, nicht -In.", "ıyor": "*yazıyor* = er/sie schreibt (aktiv); es fehlt das Passiv und *dün akşam* verlangt die Vergangenheit."}, "e": "yaz- + **ıl** + **dı** = **yazıldı**. Konsonant am Stammende → -Il."},
    {"id": "tr-b1-05.2", "t": "gap", "q": "Burada Türkçe konuş___. (Hier wird Türkisch gesprochen.)", "a": ["ulur", "uluyor"], "wrong": {"ılır": "Letzter Vokal von *konuş-* ist **u** → -ul (nicht -ıl).", "unur": "*konuş-* endet auf Konsonant ş: -n steht nur nach Vokal.", "uyor": "Dann fehlt das Passiv-Suffix -Il: *konuşuyor* = er/sie spricht."}, "e": "konuş- + **ul** + **ur** = **konuşulur**. Auch *konuşuluyor* ist richtig."},
    {"id": "tr-b1-05.3", "t": "gap", "q": "Paket dün postadan al___. (Das Paket wurde gestern bei der Post abgeholt.)", "a": ["ındı"], "wrong": {"ıldı": "*al-* endet auf **l** → -In, nicht -Il.", "indi": "Letzter Vokal von *al-* ist **a** → -ın (nicht -in).", "andı": "Das Passiv-Suffix ist -In (mit Vokal ı), nicht -an."}, "e": "al- + **ın** + **dı** = **alındı**. Stamm auf l → -In."},
    {"id": "tr-b1-05.4", "t": "gap", "q": "Bu kitap çok oku___. (Dieses Buch wird viel gelesen.)", "a": ["nur", "nuyor"], "wrong": {"ulur": "*oku-* endet auf Vokal → nur -n: oku**n**ur.", "ınır": "Letzter Vokal von *oku-* ist **u** → -nur (nicht -nır).", "ur": "Dann fehlt das Passiv-Suffix: *okur* = er/sie liest."}, "e": "oku- + **n** + **ur** = **okunur**. Vokal am Stammende → nur -n."},
    {"id": "tr-b1-05.5", "t": "gap", "q": "Cam çocuk ___ kırıldı. (Das Fenster wurde vom Kind zerbrochen.)", "a": ["tarafından"], "wrong": {"için": "*için* heißt „für/weil“, nicht „von (dem Handelnden)“.", "ile": "*ile* heißt „mit“.", "tarafı": "Für den Handelnden braucht man den Ablativ -ndan: tarafın**dan**."}, "e": "çocuk **tarafından** = vom Kind. *tarafından* nennt den Handelnden im Passiv."},
    {"id": "tr-b1-05.6", "t": "gap", "q": "Burada sigara iç___. (Hier darf nicht geraucht werden.)", "a": ["ilmez", "ilmiyor"], "wrong": {"ilir": "Das wäre „wird geraucht“ ohne Verneinung.", "ınmaz": "*iç-* endet auf Konsonant ç: -n steht nur nach Vokal.", "ulmaz": "Letzter Vokal von *iç-* ist **i** → -il (nicht -ul)."}, "e": "iç- + **il** + **mez** = **içilmez** (allgemeines Verbot). Auch *içilmiyor* ist richtig: Es beschreibt, dass hier nicht geraucht wird (Zustand, nicht Regel)."},
    {"id": "tr-b1-05.7", "t": "mc", "q": "„Die Tür wird geöffnet.“", "o": ["Kapı açılıyor.", "Kapıyı açılıyor.", "Kapı açıldı.", "Kapı açar."], "a": 0, "why": {"1": "Das Subjekt des Passivs steht im Nominativ: *Kapı*, nicht *Kapıyı*.", "2": "*açıldı* ist Vergangenheit („wurde geöffnet“).", "3": "*açar* = „er/sie öffnet“ (aktiv), nicht „wird geöffnet“."}, "e": "aç- + **ıl** + **ıyor** = **açılıyor** (Passiv, Präsens)."},
    {"id": "tr-b1-05.8", "t": "mc", "q": "„Der Brief wurde vom Direktor unterschrieben.“", "o": ["Mektup müdür tarafından imzalandı.", "Mektup müdür tarafından imzalıldı.", "Mektubu müdür tarafından imzalandı.", "Mektup müdür imzaladı."], "a": 0, "why": {"1": "*imzala-* endet auf Vokal → -n, nicht -Il.", "2": "Das Subjekt des Passivs hat keine Akkusativendung.", "3": "*imzaladı* ist aktiv („er unterschrieb“); der Handelnde wäre dann das Subjekt."}, "e": "imzala- + **n** + **dı** = **imzalandı**. *tarafından* nennt den Direktor."},
    {"id": "tr-b1-05.9", "t": "mc", "q": "„Hier darf nicht geraucht werden.“", "o": ["Burada sigara içilmez.", "Burada sigara içmez.", "Burada sigara içilir.", "Burada sigarayı içilmez."], "a": 0, "why": {"1": "*içmez* = „er/sie raucht nicht“ (aktiv).", "2": "*içilir* = „es wird geraucht“ (ohne Verneinung).", "3": "Beim Passiv steht das Objekt im Nominativ: *sigara*, nicht *sigarayı*."}, "e": "iç- + **il** + **mez** = **içilmez**."},
    {"id": "tr-b1-05.10", "t": "mc", "q": "Wie lautet das Passiv von *bilmek* (wissen)?", "o": ["bilinmek", "bililmek", "bilnmek", "bilmek"], "a": 0, "why": {"1": "*bil-* endet auf **l** → -In, nicht -Il.", "2": "-n allein steht nur nach Vokal; *bil-* endet auf Konsonant.", "3": "*bilmek* ist das Aktiv (wissen)."}, "e": "bil- + **in** + **mek** = **bilinmek** (bekannt sein, gewusst werden)."},
    {"id": "tr-b1-05.11", "t": "mc", "q": "Welcher Satz ist ein Passivsatz?", "o": ["Çorba sıcak içilir.", "Çorba içiyorum.", "Çorba içen çocuk güldü.", "Çorbayı sıcak içer."], "a": 0, "why": {"1": "*içiyorum* = „ich trinke“ (aktiv).", "2": "*içen* = „der trinkt“ (Partizip, aktiv).", "3": "*içer* = „er/sie trinkt“ (aktiv, mit Akkusativ)."}, "e": "iç- + **il** + **ir** = **içilir**: Suppe wird heiß gegessen/getrunken."},
    {"id": "tr-b1-05.12", "t": "mc", "q": "„Der Kuchen wurde von meiner Mutter gebacken.“", "o": ["Pasta annem tarafından yapıldı.", "Pasta annem yapıldı.", "Pasta annemi tarafından yapıldı.", "Pasta annem tarafından yaptı."], "a": 0, "why": {"1": "Der Handelnde braucht *tarafından*; ohne es ist der Satz unvollständig.", "2": "Vor *tarafından* steht das Nomen ohne Kasusendung (annem); nur Pronomen nehmen den Genitiv (benim tarafımdan).", "3": "*yaptı* ist aktiv; im Passiv steht *yapıldı*."}, "e": "yap- + **ıl** + **dı** = **yapıldı**; *annem tarafından* nennt die Handelnde."},
    {"id": "tr-b1-05.13", "t": "order", "q": "Bilde den Satz: „Der Brief wurde gestern Abend geschrieben.“", "w": ["Mektup", "dün", "akşam", "yazıldı"], "a": ["Mektup dün akşam yazıldı", "Dün akşam mektup yazıldı"], "e": "Das Subjekt *mektup* steht im Nominativ, das Passiv-Verb *yazıldı* am Ende."},
    {"id": "tr-b1-05.14", "t": "order", "q": "Bilde den Satz: „Hier wird Türkisch gesprochen.“", "w": ["Burada", "Türkçe", "konuşulur"], "a": ["Burada Türkçe konuşulur", "Türkçe burada konuşulur"], "e": "*konuşulur* ist das unpersönliche Passiv („man spricht“). Es steht am Ende."},
    {"id": "tr-b1-05.15", "t": "order", "q": "Bilde den Satz: „Das Fenster wurde vom Kind zerbrochen.“", "w": ["Cam", "çocuk", "tarafından", "kırıldı"], "a": ["Cam çocuk tarafından kırıldı"], "e": "*çocuk tarafından* steht direkt vor dem Verb *kırıldı*."},
    {"id": "tr-b1-05.16", "t": "match", "q": "Ordne die Form der Bedeutung zu:", "p": [["yapılmak", "gemacht werden"], ["açılmak", "geöffnet werden"], ["okunmak", "gelesen werden"], ["bilinmek", "bekannt sein, gewusst werden"], ["konuşulmak", "gesprochen werden"]], "e": "Vokal am Stammende → -n (okunmak); Stamm auf l → -In (bilinmek, alınmak); sonst -Il (yapılmak, açılmak, konuşulmak)."},
    {"id": "tr-b1-05.17", "t": "cloze", "q": "Ergänze die Endungen.", "text": "Mektup dün yaz{1}. Cam çocuk tarafından kır{2}. Paket postadan al{3}.", "gaps": {"1": {"a": ["ıldı"], "wrong": {"ındı": "*yaz-* endet auf z, nicht auf l: -Il.", "ıyor": "*yazıyor* = er/sie schreibt (aktiv) und steht im Präsens; *dün* verlangt die Vergangenheit."}}, "2": {"a": ["ıldı"], "wrong": {"ındı": "*kır-* endet auf r, nicht auf l: -Il.", "ildi": "Letzter Vokal von *kır-* ist **ı** → -ıl."}}, "3": {"a": ["ındı"], "wrong": {"ıldı": "*al-* endet auf l → -In.", "andı": "Das Passiv-Suffix hat den Vokal ı: -ın."}}}, "e": "Konsonant → -Il (yazıldı, kırıldı); l → -In (alındı)."},
    {"id": "tr-b1-05.18", "t": "sort", "q": "Passiv oder Aktiv? Ordne die Sätze zu.", "cats": ["Passiv (Handelnder unwichtig)", "Aktiv (der Handelnde ist Subjekt)"], "items": [["Kapı açıldı.", 0], ["Çocuk kapıyı açtı.", 1], ["Burada çay içilir.", 0], ["Biz çay içeriz.", 1], ["Mektup yazıldı.", 0], ["Annem mektubu yazdı.", 1]], "why": {"Kapı açıldı.": "*açıldı* = wurde geöffnet; der Handelnde fehlt.", "Çocuk kapıyı açtı.": "*açtı* = er/sie öffnete; *çocuk* ist das Subjekt.", "Burada çay içilir.": "*içilir* = es wird getrunken (man trinkt).", "Biz çay içeriz.": "*içeriz* = wir trinken (aktiv).", "Mektup yazıldı.": "*yazıldı* = wurde geschrieben.", "Annem mektubu yazdı.": "*yazdı* = er/sie schrieb; *annem* ist das Subjekt."}, "e": "Das Passiv erkennst du am Suffix -Il/-In/-n; im Aktiv steht der Handelnde als Subjekt, das Objekt oft im Akkusativ."},
    {"id": "tr-b1-05.19", "t": "listen", "say": "Mektup dün akşam yazıldı.", "q": "Hör zu: Was wird gesagt?", "o": ["Der Brief wurde gestern Abend geschrieben.", "Der Brief wird morgen geschrieben.", "Jemand schreibt gerade einen Brief.", "Der Brief wurde gelesen."], "a": 0, "why": {"1": "*dün akşam* = gestern Abend, nicht morgen.", "2": "*yazıldı* ist Vergangenheit, kein Präsens.", "3": "*yazıldı* = geschrieben, nicht gelesen (okundu)."}, "e": "„Der Brief wurde gestern Abend geschrieben.“ yaz-ıl-dı = Passiv."},
    {"id": "tr-b1-05.20", "t": "dictation", "say": "Türkiye’de çay her yerde içilir.", "a": ["Türkiye’de çay her yerde içilir."], "wrong": {"Türkiye’de çay her yerde içülür.": "Letzter Vokal von *iç-* ist **i** → -il, nicht -ül.", "Türkiye’de çay her yerde içer.": "*içer* ist aktiv (er trinkt); hier steht das Passiv *içilir*.", "Türkiye’de çay her yerde içilmez.": "*içilmez* = wird nicht getrunken; gehört wurde *içilir*."}, "e": "„In der Türkei wird überall Tee getrunken.“ iç- + il + ir = içilir."},
    {"id": "tr-b1-05.21", "t": "speak", "say": "Burada Türkçe konuşulur.", "e": "„Hier wird Türkisch gesprochen.“ *konuşulur*: ş = „sch“, u kurz, Betonung auf der letzten Silbe (ko-nu-şu-LUR). Typischer Fehler: *konuşılur* mit dumpfem ı statt u."},
    {"id": "tr-b1-05.22", "t": "speak", "say": "Mektup dün akşam yazıldı.", "e": "„Der Brief wurde gestern Abend geschrieben.“ *yazıldı*: z stimmhaft wie in „Sonne“, ı dumpf, Betonung auf -DI. Typischer Fehler: *yazıldı* mit hartem s („yasıldı“)."},
    {"id": "tr-b1-05.23", "t": "speak", "say": "Bu kitap herkes tarafından okunuyor.", "e": "„Dieses Buch wird von allen gelesen.“ *tarafından*: ta-ra-fın-DAN, ı dumpf. *okunuyor*: o-ku-nu-YOR. Typischer Fehler: *herkez* mit weichem z (es heißt herkes mit stimmlosem s)."},
    {"id": "tr-b1-05.24", "t": "respond", "say": "Senin ülkende hangi dil konuşulur?", "q": "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze das Passiv (-Il/-In/-n).", "chunks": ["Bizde … konuşulur.", "… yapılır.", "… içilir.", "… öğretilir."], "models": ["Bizim ülkemizde Almanca konuşulur. Tabii birçok yabancı dil de öğrenilir. Okullarda İngilizce öğretilir.", "Bizde en çok Türkçe konuşulur. Evde genellikle çay içilir ve akşam yemeği birlikte yenir."], "modelsN": ["In unserem Land wird Deutsch gesprochen. Natürlich werden auch viele Fremdsprachen gelernt. In den Schulen wird Englisch unterrichtet.", "Bei uns wird am meisten Türkisch gesprochen. Zu Hause wird meist Tee getrunken, und das Abendessen wird gemeinsam gegessen."], "e": "Das **Passiv** bildest du mit -Il/-In/-n (konuşulur, öğrenilir, yenir). Deine Antwort darf ganz anders sein."}
  ]
});

K.add("tr-b1-17", {
  lesson: [{"p": "Im Deutschen stehen „**sich** waschen“, „**sich** anziehen“ (reflexiv) und „**sich** treffen“, „**einander** helfen“ (reziprok) mit dem Pronomen „sich/einander“. Türkisch braucht dafür **Suffixe am Verbstamm**: **-(I)n** für Reflexives (*yıka-n-mak* = sich waschen) und **-(I)ş** für Gegenseitiges (*gör-üş-mek* = sich treffen/sprechen). Ein Reflexivpronomen wie „sich“ gibt es dabei nicht."}, {"h": "Der Bauplan"}, {"table": {"head": ["Deutsch", "Bauplan", "Türkisch"], "rows": [["Das Kind zieht sich an.", "Stamm + **-(I)n**", "Çocuk giy**in**iyor."], ["Meine Mutter kämmt sich.", "Vokal-Stamm + **-n**", "Annem tara**n**ıyor."], ["Wir treffen uns morgen.", "Stamm + **-(I)ş**", "Yarın bulu**ş**uruz."], ["Wir haben uns kennengelernt.", "Vokal-Stamm + **-ş**", "Tanı**ş**tık."], ["Ich spreche morgen mit dem Arzt.", "Stamm + -Iş + **ile**", "Yarın doktorla gör**üş**eceğim."], ["Wir verstehen uns gut.", "Vokal-Stamm + **-ş**", "İyi anla**ş**ıyoruz."]]}}, {"p": "**Reflexiv (-(I)n):** *yıkanmak, giyinmek, taranmak, hazırlanmak, sevinmek*. Nach Vokal steht nur **-n** (*tara-n-mak*), nach Konsonant **-In** (*giy-in-mek*). Das Subjekt tut etwas an sich selbst oder für sich. Achtung: Die Form sieht aus wie das **Passiv** (Thema Passiv): *Çocuk yıkandı* kann „das Kind hat sich gewaschen“ oder „wurde gewaschen“ heißen; der Zusammenhang entscheidet."}, {"p": "**Reziprok (-(I)ş):** *görüşmek, buluşmak, tanışmak, anlaşmak, barışmak, yazışmak*. Nach Vokal steht **-ş** (*tanı-ş-mak, anla-ş-mak*), nach Konsonant **-Iş** mit großer Harmonie (*bul-uş-mak, gör-üş-mek*). Der Partner steht oft mit **ile/-(y)lA**: *Doktorla görüştüm.* Auch ohne Partner im Satz ist die Gegenseitigkeit klar: *Yarın görüşürüz* (wir sprechen/sehen uns morgen). Das Pronomen *birbirini* („einander“) gibt es zusätzlich: *Birbirimizi iyi tanıyoruz.*"}, {"warn": "Typische Fehler: *„Yarın burada buluruz“* (*bulmak* = finden; für „sich treffen“ braucht man buluşmak), *„tanıdık“* statt *tanıştık* (*tanımak* = kennen; *tanıdık* wäre „wir kannten“), *„görüşdük“* statt *görüştük* (ş ist stimmlos, danach folgt -tı/-tük) und *„kendimi giyindim“* (das Suffix -In macht schon reflexiv; *kendimi* ist überflüssig)."}, {"tip": "Frage dich: Tut jemand etwas **an sich selbst** (→ -(I)n) oder tun es **mehrere miteinander** (→ -(I)ş)? *Giyindi* = er zog sich an; *buluştular* = sie trafen sich. „Einander waschen“ sagt man mit *birbirini yıkamak*."}, {"ex": [["Çocuk kendi başına giyiniyor.", "Das Kind zieht sich allein an."], ["Annem aynada taranıyor.", "Meine Mutter kämmt sich im Spiegel."], ["Yarın saat altıda burada buluşuruz.", "Wir treffen uns morgen um sechs hier."], ["Dün yeni komşularımızla tanıştık.", "Gestern haben wir unsere neuen Nachbarn kennengelernt."], ["Yarın doktorla görüşeceğim.", "Morgen spreche ich mit dem Arzt."]]}],
  exercises: [
    {"id": "tr-b1-17.1", "t": "gap", "q": "Çocuk kendi başına giy___. (giyinmek – Das Kind zieht sich allein an.)", "a": ["inir", "iniyor"], "wrong": {"ilir": "*-Il* ist das Passiv („wird angezogen“); für „sich anziehen“ braucht man -In.", "ir": "Dann fehlt das Reflexiv-Suffix: *giyer* = er/sie zieht (etwas) an.", "unur": "Letzter Vokal von *giy-* ist **i** → -in, nicht -un."}, "e": "giy- + **in** + **ir** = **giyinir**. Reflexiv: Der Handelnde zieht sich selbst an."},
    {"id": "tr-b1-17.2", "t": "gap", "q": "Yarın burada bulu___. (buluşmak – Morgen treffen wir uns hier.)", "a": ["şuruz", "şacağız", "şuyoruz"], "wrong": {"ruz": "Ohne -ş heißt es *buluruz*: wir finden. Für „sich treffen“ braucht man -Iş: bulu**ş**uruz.", "nuruz": "-n macht reflexiv/passiv („gefunden werden“), nicht reziprok.", "şırız": "Letzter Vokal von *bul-* ist **u** → -uş, nicht -ış."}, "e": "bul- + **uş** + **uruz** = **buluşuruz**. Reziprok: sich gegenseitig treffen."},
    {"id": "tr-b1-17.3", "t": "gap", "q": "Dün yeni komşularımızla tanı___. (tanışmak – Gestern haben wir unsere neuen Nachbarn kennengelernt.)", "a": ["ştık"], "wrong": {"ştım": "-ım = „ich“; hier handelt „wir“: -ık.", "ıştık": "*tanı-* endet auf Vokal → nur -ş, nicht -Iş.", "dık": "Dann fehlt das Reziprok-Suffix: *tanıdık* = wir kannten."}, "e": "tanı- + **ş** + **tık** = **tanıştık**. Nach Vokal: -ş; nach ş wird -dı zu -tı."},
    {"id": "tr-b1-17.4", "t": "gap", "q": "Yarın doktorla gör___. (görüşmek – Morgen spreche ich mit dem Arzt.)", "a": ["üşeceğim", "üşürüm", "üşüyorum"], "wrong": {"eceğim": "Ohne -Iş heißt es *göreceğim*: ich werde sehen. Für „sprechen/treffen“ braucht man -üş.", "ışeceğim": "Letzter Vokal von *gör-* ist **ö** → -üş (ü), nicht -ış.", "üneceğim": "-n wäre Reflexiv/Passiv, nicht gegenseitig."}, "e": "gör- + **üş** + **eceğim** = **görüşeceğim**. Die Gegenseitigkeit „ich und der Arzt“ steckt im -üş."},
    {"id": "tr-b1-17.5", "t": "gap", "q": "Kardeşimle çok iyi anla___. (anlaşmak – Ich verstehe mich gut mit meinem Bruder.)", "a": ["şıyorum", "şırım"], "wrong": {"şiyorum": "Letzter Vokal von *anla-* ist **a** → -şı (ı), nicht -şi.", "yorum": "Dann fehlt -ş: *anlıyorum* = ich verstehe.", "nıyorum": "-n macht reflexiv/passiv („verstanden werden“), nicht reziprok."}, "e": "anla- + **ş** + **ıyorum** = **anlaşıyorum**. Nach Vokal nur -ş."},
    {"id": "tr-b1-17.6", "t": "gap", "q": "Annem aynada tara___. (taranmak – Meine Mutter kämmt sich im Spiegel.)", "a": ["nıyor", "nır"], "wrong": {"ınıyor": "*tara-* endet auf Vokal → nur -n, nicht -ın.", "ıyor": "Ohne -n heißt es *tarıyor*: sie kämmt (etwas/jemanden), nicht sich selbst.", "şıyor": "-ş wäre reziprok („sie kämmen einander“)."}, "e": "tara- + **n** + **ıyor** = **taranıyor**. Reflexiv nach Vokal: -n."},
    {"id": "tr-b1-17.7", "t": "mc", "q": "„Wir treffen uns morgen.“", "o": ["Yarın buluşuruz.", "Yarın buluruz.", "Yarın bulunur.", "Yarın buluşmayız."], "a": 0, "why": {"1": "*buluruz* = wir finden.", "2": "*bulunur* = man findet / es befindet sich (Passiv).", "3": "*buluşmayız* = wir treffen uns nicht."}, "e": "bul- + **uş** + **uruz** = **buluşuruz** (reziprok)."},
    {"id": "tr-b1-17.8", "t": "mc", "q": "„Sie haben sich gestern kennengelernt.“", "o": ["Dün tanıştılar.", "Dün tanıdılar.", "Dün tanındılar.", "Dün tanıttılar."], "a": 0, "why": {"1": "*tanıdılar* = sie kannten/erkannten (jemanden).", "2": "*tanındılar* = sie wurden erkannt (Passiv/Reflexiv von tanımak).", "3": "*tanıttılar* = sie stellten (jemanden) vor (Kausativ)."}, "e": "tanı- + **ş** + **tı** + **lar** = **tanıştılar**."},
    {"id": "tr-b1-17.9", "t": "mc", "q": "„Der Junge zieht sich schnell an.“", "o": ["Çocuk çabuk giyiniyor.", "Çocuk çabuk giyiliyor.", "Çocuk çabuk giyiyor.", "Çocuk çabuk giydiriyor."], "a": 0, "why": {"1": "*giyiliyor* = wird angezogen (Passiv).", "2": "*giyiyor* = er zieht (etwas) an, ohne Reflexiv-Bedeutung.", "3": "*giydiriyor* = er zieht (jemanden) an, z. B. ein Kind (Kausativ)."}, "e": "giy- + **in** + **iyor** = **giyiniyor** (reflexiv)."},
    {"id": "tr-b1-17.10", "t": "mc", "q": "Welche Aussage über *yıkanmak* stimmt?", "o": ["Es kann „sich waschen“ und „gewaschen werden“ heißen; der Zusammenhang entscheidet.", "Es heißt nur „sich waschen“.", "Es heißt nur „gewaschen werden“.", "Es heißt „waschen lassen“."], "a": 0, "why": {"1": "Es kann auch Passiv sein (Das Auto wurde gewaschen).", "2": "Es kann auch reflexiv sein (Das Kind hat sich gewaschen).", "3": "„Waschen lassen“ ist *yıkatmak* (Kausativ)."}, "e": "-(I)n sieht aus wie das Passiv -In. *Çocuk yıkandı*: Wer wäscht, sagt der Kontext."},
    {"id": "tr-b1-17.11", "t": "mc", "q": "„Wir sehen/sprechen uns morgen.“", "o": ["Yarın görüşürüz.", "Yarın görürüz.", "Yarın görülür.", "Yarın görüşmedik."], "a": 0, "why": {"1": "*görürüz* = wir sehen/werden sehen (kein „sich“).", "2": "*görülür* = man sieht (Passiv).", "3": "*görüşmedik* = wir haben uns nicht gesprochen (Vergangenheit, verneint)."}, "e": "gör- + **üş** + **ür** + **üz** = **görüşürüz**."},
    {"id": "tr-b1-17.12", "t": "mc", "q": "Welches Verb ist reziprok („einander“)?", "o": ["anlaşmak", "anlamak", "anlatmak", "anlatılmak"], "a": 0, "why": {"1": "*anlamak* = verstehen (ohne Gegenseitigkeit).", "2": "*anlatmak* = erzählen.", "3": "*anlatılmak* = erzählt werden (Passiv)."}, "e": "anla- + **ş** + **mak** = **anlaşmak** (sich einigen, sich verstehen)."},
    {"id": "tr-b1-17.13", "t": "order", "q": "Bilde den Satz: „Wir treffen uns morgen um sechs.“", "w": ["Yarın", "saat", "altıda", "buluşuruz"], "a": ["Yarın saat altıda buluşuruz", "Saat altıda yarın buluşuruz"], "e": "Das reziproke Verb *buluşuruz* steht am Ende; die Zeitangaben davor."},
    {"id": "tr-b1-17.14", "t": "order", "q": "Bilde den Satz: „Das Kind zieht sich allein an.“", "w": ["Çocuk", "kendi", "başına", "giyiniyor"], "a": ["Çocuk kendi başına giyiniyor"], "e": "*kendi başına* = allein. Das Reflexiv-Suffix steckt schon in *giyiniyor*."},
    {"id": "tr-b1-17.15", "t": "order", "q": "Bilde den Satz: „Gestern haben wir die Nachbarn kennengelernt.“", "w": ["Dün", "komşularla", "tanıştık"], "a": ["Dün komşularla tanıştık", "Komşularla dün tanıştık"], "e": "*komşularla* (mit den Nachbarn) steht vor dem reziproken Verb *tanıştık*."},
    {"id": "tr-b1-17.16", "t": "match", "q": "Ordne die Form der Bedeutung zu:", "p": [["yıkanmak", "sich waschen"], ["giyinmek", "sich anziehen"], ["görüşmek", "sich treffen, sprechen"], ["tanışmak", "sich kennenlernen"], ["anlaşmak", "sich einigen, sich verstehen"]], "e": "-(I)n = reflexiv (an sich selbst); -(I)ş = reziprok (miteinander)."},
    {"id": "tr-b1-17.17", "t": "cloze", "q": "Ergänze die Endungen.", "text": "Çocuk sabah kendi başına giy{1}. Yarın burada bulu{2}. Dün yeni komşularımızla tanı{3}.", "gaps": {"1": {"a": ["inir", "iniyor"], "wrong": {"ilir": "-Il ist das Passiv („wird angezogen“).", "ir": "Ohne -In fehlt das Reflexiv."}}, "2": {"a": ["şuruz", "şacağız", "şuyoruz"], "wrong": {"ruz": "Ohne -ş heißt es „wir finden“.", "şırız": "Letzter Vokal von *bul-* ist **u** → -uş."}}, "3": {"a": ["ştık"], "wrong": {"ştım": "-ım = „ich“; hier „wir“.", "ıştık": "Nach Vokal nur -ş."}}}, "e": "-(I)n = reflexiv, -(I)ş = reziprok; nach Vokal nur -n/-ş."},
    {"id": "tr-b1-17.18", "t": "sort", "q": "Reflexiv oder reziprok? Ordne die Sätze zu.", "cats": ["Reflexiv (sich selbst)", "Reziprok (miteinander)"], "items": [["Annem aynada taranıyor.", 0], ["Arkadaşlarımla buluşuyoruz.", 1], ["Çocuk giyindi.", 0], ["Komşularla tanıştık.", 1], ["Müdürle görüştüm.", 1], ["Kız hızlıca hazırlandı.", 0]], "why": {"Annem aynada taranıyor.": "*taranıyor* = sie kämmt sich selbst.", "Arkadaşlarımla buluşuyoruz.": "*buluşuyoruz* = wir treffen uns (miteinander).", "Çocuk giyindi.": "*giyindi* = es zog sich an.", "Komşularla tanıştık.": "*tanıştık* = wir lernten uns kennen.", "Müdürle görüştüm.": "*görüştüm* = ich sprach/traf mich mit dem Direktor.", "Kız hızlıca hazırlandı.": "*hazırlandı* = sie machte sich fertig (bezieht sich auf sie selbst)."}, "e": "-(I)n bezieht die Handlung auf das Subjekt selbst, -(I)ş auf mehrere Beteiligte."},
    {"id": "tr-b1-17.19", "t": "listen", "say": "Yarın saat altıda burada buluşuruz.", "q": "Hör zu: Was wird gesagt?", "o": ["Sie treffen sich morgen um sechs hier.", "Sie finden morgen etwas hier.", "Man trifft sie morgen nicht.", "Sie sprechen morgen am Telefon."], "a": 0, "why": {"1": "*bulmak* = finden; hier steht *buluşmak* (sich treffen).", "2": "Es gibt keine Verneinung (-mAz).", "3": "Von einem Telefonat ist nicht die Rede."}, "e": "„Morgen um sechs treffen wir uns hier.“ bul-uş-uruz = reziprok."},
    {"id": "tr-b1-17.20", "t": "dictation", "say": "Dün yeni komşularımızla tanıştık.", "a": ["Dün yeni komşularımızla tanıştık."], "wrong": {"Dün yeni komşularımızla tanıdık.": "*tanıdık* = wir kannten; für „kennengelernt“ braucht man tanış-tık.", "Dün yeni komşularımızla tanışdık.": "Nach ş (stimmlos) wird d zu **t**: tanış**t**ık.", "Dün yeni komşularımızla tanıştım.": "-ım = „ich“; hier „wir“: -ık."}, "e": "„Gestern haben wir unsere neuen Nachbarn kennengelernt.“ tanı + ş + tık."},
    {"id": "tr-b1-17.21", "t": "speak", "say": "Yarın saat altıda burada buluşuruz.", "e": "„Morgen um sechs treffen wir uns hier.“ *buluşuruz*: u kurz, ş = „sch“, Betonung auf der letzten Silbe (bu-lu-şu-RUZ). Typischer Fehler: *buluşurus* mit hartem s."},
    {"id": "tr-b1-17.22", "t": "speak", "say": "Çocuk kendi başına giyiniyor.", "e": "„Das Kind zieht sich allein an.“ *giyiniyor*: y wie „j“, Betonung auf -YOR. *başına*: ş = „sch“, ı dumpf. Typischer Fehler: das ı in *başına* wie ein i sprechen; es wird dumpf gesprochen."},
    {"id": "tr-b1-17.23", "t": "speak", "say": "Dün yeni komşularımızla tanıştık.", "e": "„Gestern haben wir unsere neuen Nachbarn kennengelernt.“ *tanıştık*: ı dumpf, ş = „sch“, k am Ende deutlich. *komşularımızla*: ş = „sch“, ı dumpf. Typischer Fehler: *tanistik* mit „s“ statt „sch“."},
    {"id": "tr-b1-17.24", "t": "respond", "say": "Hafta sonu arkadaşlarınla ne yapıyorsun?", "q": "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze reziproke (-(I)ş) und reflexive (-(I)n) Verben.", "chunks": ["… ile buluşuyoruz.", "… görüşüyoruz.", "Giyinip …", "Hazırlanıp …"], "models": ["Cumartesi arkadaşlarımla buluşuyoruz. Önce kahvaltı yapıyoruz, sonra uzun uzun sohbet ediyoruz. Akşam hazırlanıp sinemaya gidiyoruz.", "Hafta sonu eski arkadaşlarımla görüşüyorum. Birlikte yürüyüşe çıkıyoruz, sonra bir kafede oturuyoruz."], "modelsN": ["Samstags treffe ich mich mit meinen Freunden. Zuerst frühstücken wir, dann unterhalten wir uns lange. Abends machen wir uns fertig und gehen ins Kino.", "Am Wochenende treffe ich alte Freunde. Wir gehen zusammen spazieren und sitzen dann in einem Café."], "e": "**Reziprok** = -(I)ş (buluşmak, görüşmek), **reflexiv** = -(I)n (hazırlanmak, giyinmek). Deine Antwort darf ganz anders sein."}
  ]
});

K.add("tr-b1-06", {
  lesson: [{"p": "Im Deutschen sagst du „ich **lasse** mir die Haare schneiden“ oder „sie **gibt** dem Kind zu essen“. Türkisch hat dafür das **Kausativ-Suffix** am Verbstamm: Jemand **lässt** etwas tun oder **bringt** jemanden dazu. Das Suffix heißt je nach Verb **-DIr**, **-t**, **-Ir/-Ar**: *kes-tir-mek, yıka-t-mak, iç-ir-mek*. Der Handelnde steht, wenn genannt, bei Verben mit Objekt im Dativ (*Terziye elbise diktirdim*), bei Verben ohne Objekt im Akkusativ (*beni güldürdü, çocuğu uyuttu*)."}, {"h": "Der Bauplan"}, {"table": {"head": ["Deutsch", "Bauplan", "Türkisch"], "rows": [["Ich lasse mir die Haare schneiden.", "Stamm + **-DIr**", "Saç kes**tir**iyorum."], ["Ich lasse mein Auto waschen.", "Vokal-Stamm + **-t**", "Arabamı yıka**t**ıyorum."], ["Wir lassen ein Foto machen.", "Stamm + -DIr", "Fotoğraf çek**tir**iyoruz."], ["Ich gebe dem Kind Milch zu trinken.", "Stamm + **-Ir**", "Çocuğa süt iç**ir**iyorum."], ["Der Film bringt mich zum Lachen.", "Stamm + -DIr", "Film beni gül**dür**üyor."], ["Der Lehrer lässt die Kinder lesen.", "Vokal-Stamm + -t", "Öğretmen çocuklara kitap oku**t**uyor."]]}}, {"p": "**Welches Suffix?** Nach Vokal steht **-t** (*yıka-t-mak, boya-t-mak, oku-t-mak, temizle-t-mek*). Auch mehrsilbige Stämme auf l oder r nehmen oft -t (*kısal-t-mak, çoğal-t-mak*); sonst **-DIr**: *yap-tır-mak, kes-tir-mek, çek-tir-mek, dik-tir-mek, gül-dür-mek*. Einige häufige Verben haben **-Ir/-Ar**: *iç-ir-mek, piş-ir-mek, düş-ür-mek, çık-ar-mak*; ye- bildet *yedirmek*. Das d in -DIr wird nach stimmlosen Konsonanten (k, p, ç, t, s, ş, f, h) zu **t**: *kestir-, çektir-, baktır-*."}, {"p": "**Wer führt die Handlung aus?** Die Person, die etwas tun **soll**, steht bei Verben mit Objekt im **Dativ**: *Terziye elbise diktirdim* (ich ließ den Schneider ein Kleid nähen). Bei Verben ohne Objekt steht sie im **Akkusativ**: *Film beni güldürdü*, *çocuğu uyuttu*. Oft sagt man auch, **wo**: *berberde saç kestirdim*. Das Kausativ drückt aus, dass **jemand anderes** etwas für dich tut, nicht, dass du es selbst machst: *Saçımı kestim* (ich schnitt meine Haare selbst) vs. *Saçımı kestirdim* (ich ließ sie schneiden)."}, {"warn": "Typische Fehler: *„yıkadırdım“* (nach Vokal -t: yıka**t**tım, nicht -DIr), *„kesdirdim“* (nach stimmlosem Konsonant -tir: kes**tir**dim), *„Terziyi elbise diktirdim“* (der Ausführende steht im Dativ: Terziye) und *„arabamı yıkattırdım“* (meist genügt ein Kausativ-Suffix: yıkattım)."}, {"tip": "Typische Alltagswörter: **kestirmek** (Haare schneiden lassen), **yıkatmak** (waschen lassen), **yaptırmak** (machen lassen), **çektirmek** (z. B. Foto), **diktirmek** (nähen lassen), **boyatmak** (streichen lassen), **temizletmek**, **okutmak**, **yedirmek**, **içirmek**, **güldürmek**."}, {"ex": [["Dün berberde saç kestirdim.", "Gestern habe ich mir beim Friseur die Haare schneiden lassen."], ["Geçen hafta arabamı yıkattım.", "Letzte Woche habe ich mein Auto waschen lassen."], ["Terziye elbise diktirdim.", "Ich habe beim Schneider ein Kleid nähen lassen."], ["Çocuğa süt içirdim.", "Ich habe dem Kind Milch zu trinken gegeben."], ["Bu film beni çok güldürdü.", "Dieser Film hat mich sehr zum Lachen gebracht."]]}],
  exercises: [
    {"id": "tr-b1-06.1", "t": "gap", "q": "Dün berberde saç kes___. (kestirmek – Gestern habe ich mir beim Friseur die Haare schneiden lassen.)", "a": ["tirdim"], "wrong": {"tim": "Ohne -DIr heißt es *kestim*: ich schnitt (selbst).", "dirdim": "*kes-* endet auf s (stimmlos) → -tir, nicht -dir.", "tirdi": "-i = „er/sie“. Hier handelt „ich“: -im."}, "e": "kes- + **tir** + **di** + **m** = **kestirdim**. Stamm auf stimmlosen Konsonanten → -tir."},
    {"id": "tr-b1-06.2", "t": "gap", "q": "Dün arabamı yıka___. (yıkatmak – Gestern habe ich mein Auto waschen lassen.)", "a": ["ttım"], "wrong": {"dırdım": "*yıka-* endet auf Vokal → -t, nicht -DIr.", "tırdım": "Nach Vokal steht nur -t: yıka**t**tım.", "tım": "Es fehlt ein t: Kausativ -t + Vergangenheit -tı = yıkattım. Mit nur einem t hieße es *yıkatım*, das gibt es nicht."}, "e": "yıka- + **t** + **tı** + **m** = **yıkattım**. Doppeltes t: erst Kausativ -t, dann Vergangenheit -tı."},
    {"id": "tr-b1-06.3", "t": "gap", "q": "Düğünde fotoğraf çek___. (çektirmek – Bei der Hochzeit haben wir Fotos machen lassen.)", "a": ["tirdik"], "wrong": {"dirdik": "*çek-* endet auf k (stimmlos) → -tir.", "tirdim": "-im = „ich“. Hier handelt „wir“: -ik.", "ttik": "Das ist keine gültige Kausativform."}, "e": "çek- + **tir** + **dik** = **çektirdik**."},
    {"id": "tr-b1-06.4", "t": "gap", "q": "Çocuğa süt iç___. (içirmek – Ich habe dem Kind Milch zu trinken gegeben.)", "a": ["irdim"], "wrong": {"tirdim": "*iç-* gehört zu den Verben mit -Ir: iç**ir**mek.", "dirdim": "*iç-* nimmt -Ir, nicht -DIr.", "ildim": "-Il ist das Passiv; hier braucht man das Kausativ."}, "e": "iç- + **ir** + **di** + **m** = **içirdim**. Einige häufige Verben haben -Ir/-Ar."},
    {"id": "tr-b1-06.5", "t": "gap", "q": "Bu film beni çok gül___. (güldürmek – Dieser Film hat mich sehr zum Lachen gebracht.)", "a": ["dürdü"], "wrong": {"dırdı": "Letzter Vokal von *gül-* ist **ü** → -dür (nicht -dır).", "türdü": "*gül-* endet auf l (stimmhaft) → d bleibt: -dür.", "ildi": "-Il wäre das Passiv („wird gelacht“)."}, "e": "gül- + **dür** + **dü** = **güldürdü**."},
    {"id": "tr-b1-06.6", "t": "gap", "q": "Öğretmen çocuklara kitap oku___. (okutmak – Der Lehrer lässt die Kinder ein Buch lesen.)", "a": ["tur", "tuyor"], "wrong": {"dur": "*oku-* endet auf Vokal → -t, nicht -DIr.", "tır": "Letzter Vokal von *oku-* ist **u** → -tur (nicht -tır).", "nur": "-n wäre das Passiv („wird gelesen“)."}, "e": "oku- + **t** + **ur** = **okutur**. Auch *okutuyor* ist richtig."},
    {"id": "tr-b1-06.7", "t": "mc", "q": "„Ich lasse mir die Haare schneiden.“", "o": ["Saç kestiriyorum.", "Saç kesiyorum.", "Saç kesiliyor.", "Saç kestim."], "a": 0, "why": {"1": "*kesiyorum* = ich schneide (selbst).", "2": "*kesiliyor* = wird geschnitten (Passiv).", "3": "*kestim* = ich schnitt (selbst, Vergangenheit)."}, "e": "kes- + **tir** + **iyorum** = **kestiriyorum** (Kausativ, Präsens)."},
    {"id": "tr-b1-06.8", "t": "mc", "q": "„Er hat sein Auto waschen lassen.“", "o": ["Arabasını yıkattı.", "Arabasını yıkadı.", "Arabası yıkandı.", "Arabasını yıkadırdı."], "a": 0, "why": {"1": "*yıkadı* = er wusch es selbst.", "2": "*yıkandı* = es wurde gewaschen / er wusch sich.", "3": "Nach Vokal steht -t, nicht -DIr."}, "e": "yıka- + **t** + **tı** = **yıkattı**."},
    {"id": "tr-b1-06.9", "t": "mc", "q": "„Die Mutter gibt dem Kind zu essen.“", "o": ["Anne çocuğa yemek yediriyor.", "Anne çocuğa yemek yiyor.", "Anne çocuğa yemek yapıyor.", "Anne çocuk yemek yediriyor."], "a": 0, "why": {"1": "*yiyor* = sie isst selbst.", "2": "*yapıyor* = sie macht/kocht das Essen, ohne dass das Kind isst.", "3": "Das Kind, das isst, steht im Dativ: *çocuğa*."}, "e": "ye- + **dir** + **iyor** = **yediriyor** (füttern)."},
    {"id": "tr-b1-06.10", "t": "mc", "q": "„Ich habe beim Schneider ein Kleid nähen lassen.“", "o": ["Terziye elbise diktirdim.", "Terzi elbise diktirdim.", "Terziyi elbise diktirdim.", "Terziye elbise dikti."], "a": 0, "why": {"1": "Der Ausführende braucht den Dativ: *Terziye*.", "2": "Der Akkusativ passt nicht; der Ausführende steht im Dativ.", "3": "*dikti* = er nähte (selbst); es fehlt das Kausativ."}, "e": "dik- + **tir** + **di** + **m** = **diktirdim**; *terziye* = dem Schneider."},
    {"id": "tr-b1-06.11", "t": "mc", "q": "Welches Verb heißt „waschen lassen“?", "o": ["yıkatmak", "yıkanmak", "yıkamak", "yıkılmak"], "a": 0, "why": {"1": "*yıkanmak* = sich waschen / gewaschen werden.", "2": "*yıkamak* = waschen (selbst).", "3": "*yıkılmak* = einstürzen."}, "e": "yıka- + **t** + **mak** = **yıkatmak** (Kausativ)."},
    {"id": "tr-b1-06.12", "t": "mc", "q": "Welcher Satz bedeutet „Ich koche das Fleisch“?", "o": ["Eti pişiriyorum.", "Et pişiyor.", "Et pişiriliyor.", "Etti pişiyorum."], "a": 0, "why": {"1": "*pişiyor* = es gart (von selbst).", "2": "*pişiriliyor* = es wird gekocht (Passiv).", "3": "*Etti pişiyorum* ist kein gültiger Satz."}, "e": "piş- + **ir** + **iyorum** = **pişiriyorum** (Kausativ von *pişmek*: gar werden)."},
    {"id": "tr-b1-06.13", "t": "order", "q": "Bilde den Satz: „Gestern habe ich mir die Haare schneiden lassen.“", "w": ["Dün", "saçımı", "kestirdim"], "a": ["Dün saçımı kestirdim", "Saçımı dün kestirdim"], "e": "*kestirdim* steht am Ende; das Objekt *saçımı* ist bestimmt (mein Haar)."},
    {"id": "tr-b1-06.14", "t": "order", "q": "Bilde den Satz: „Letzte Woche haben wir unser Haus streichen lassen.“", "w": ["Geçen", "hafta", "evimizi", "boyattık"], "a": ["Geçen hafta evimizi boyattık", "Evimizi geçen hafta boyattık"], "e": "*boyattık* = boya- + t + tık: Kausativ + Vergangenheit."},
    {"id": "tr-b1-06.15", "t": "order", "q": "Bilde den Satz: „Der Lehrer lässt die Kinder ein Buch lesen.“", "w": ["Öğretmen", "çocuklara", "kitap", "okutuyor"], "a": ["Öğretmen çocuklara kitap okutuyor"], "e": "*çocuklara* (Dativ) = die Ausführenden, *kitap* ist das unbestimmte Objekt."},
    {"id": "tr-b1-06.16", "t": "match", "q": "Ordne die Form der Bedeutung zu:", "p": [["kestirmek", "schneiden lassen"], ["yıkatmak", "waschen lassen"], ["yaptırmak", "machen, bauen lassen"], ["çektirmek", "(Foto) machen lassen"], ["yedirmek", "zu essen geben, füttern"]], "e": "Kausativ = jemand lässt etwas tun oder gibt etwas: -DIr (kestirmek), -t (yıkatmak), -Ir (yedirmek, içirmek)."},
    {"id": "tr-b1-06.17", "t": "cloze", "q": "Ergänze die Endungen.", "text": "Dün berberde saç kes{1}. Geçen hafta arabamı yıka{2}. Çocuğa süt iç{3}.", "gaps": {"1": {"a": ["tirdim"], "wrong": {"tim": "Ohne -DIr: *kestim* = ich schnitt selbst.", "dirdim": "*kes-* endet auf s (stimmlos) → -tir."}}, "2": {"a": ["ttım"], "wrong": {"dırdım": "Nach Vokal -t, nicht -DIr.", "tım": "Es fehlt ein t: Kausativ -t + Vergangenheit -tı = yıkattım."}}, "3": {"a": ["irdim"], "wrong": {"tirdim": "*iç-* nimmt -Ir.", "dirdim": "*iç-* nimmt -Ir, nicht -DIr."}}}, "e": "Stamm auf stimmlosen Konsonanten → -tir; auf Vokal → -t; einige Verben -Ir (içirmek, pişirmek)."},
    {"id": "tr-b1-06.18", "t": "sort", "q": "Kausativ oder Aktiv? Ordne die Sätze zu.", "cats": ["Kausativ (jemand lässt etwas tun)", "Aktiv (selbst tun)"], "items": [["Saçımı kestirdim.", 0], ["Saçımı kestim.", 1], ["Arabayı yıkattık.", 0], ["Arabayı yıkadık.", 1], ["Elbise diktirdi.", 0], ["Elbise dikti.", 1]], "why": {"Saçımı kestirdim.": "*kestirdim* = ich ließ schneiden.", "Saçımı kestim.": "*kestim* = ich schnitt selbst.", "Arabayı yıkattık.": "*yıkattık* = wir ließen waschen.", "Arabayı yıkadık.": "*yıkadık* = wir wuschen selbst.", "Elbise diktirdi.": "*diktirdi* = er/sie ließ nähen.", "Elbise dikti.": "*dikti* = er/sie nähte selbst."}, "e": "Das Kausativ-Suffix (-DIr/-t) zeigt, dass jemand anderes die Arbeit macht."},
    {"id": "tr-b1-06.19", "t": "listen", "say": "Dün berberde saç kestirdim.", "q": "Hör zu: Was hat die Person gemacht?", "o": ["Sie hat sich beim Friseur die Haare schneiden lassen.", "Sie hat selbst Haare geschnitten.", "Sie hat dem Friseur geholfen.", "Sie hat sich die Haare gewaschen."], "a": 0, "why": {"1": "*kestirdim* = ich ließ schneiden, nicht „ich schnitt“.", "2": "Von Helfen ist nicht die Rede.", "3": "*kesmek* heißt schneiden, nicht waschen."}, "e": "„Gestern habe ich mir beim Friseur die Haare schneiden lassen.“ kes-tir-di-m."},
    {"id": "tr-b1-06.20", "t": "dictation", "say": "Geçen hafta evimizi boyattık.", "a": ["Geçen hafta evimizi boyattık."], "wrong": {"Geçen hafta evimizi boyadık.": "*boyadık* = wir strichen selbst; mit *boyattık* ließ man streichen.", "Geçen hafta evimizi boyadtık.": "Nach dem Kausativ -t steht -tı: boya**ttı**k, nicht -dtı.", "Geçen hafta evimizi boyatdık.": "Doppeltes t: boya**tt**ık (nicht -tdık)."}, "e": "„Letzte Woche haben wir unser Haus streichen lassen.“ boya- + t + tık."},
    {"id": "tr-b1-06.21", "t": "speak", "say": "Dün berberde saç kestirdim.", "e": "„Gestern habe ich mir beim Friseur die Haare schneiden lassen.“ *berberde*: b wie in „Bad“, r gerollt. *kestirdim*: Betonung auf -DIM, e kurz. Typischer Fehler: *kestirdim* mit sch statt s (*keştirdim*)."},
    {"id": "tr-b1-06.22", "t": "speak", "say": "Geçen hafta arabamı yıkattım.", "e": "„Letzte Woche habe ich mein Auto waschen lassen.“ *yıkattım*: ı dumpf, doppeltes t deutlich (yı-kat-tım). *geçen*: ç = „tsch“, g wie in „gehen“. Typischer Fehler: *yıkatım* mit nur einem t."},
    {"id": "tr-b1-06.23", "t": "speak", "say": "Öğretmen çocuklara kitap okutuyor.", "e": "„Der Lehrer lässt die Kinder ein Buch lesen.“ *okutuyor*: o-ku-tu-YOR, u kurz. *çocuklara*: ç = „tsch“, c wie „dsch“. Typischer Fehler: *çocuklara* mit dem deutschen ch."},
    {"id": "tr-b1-06.24", "t": "respond", "say": "Geçen hafta ne yaptırdın?", "q": "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze das Kausativ (-DIr, -t, -Ir).", "chunks": ["Saçımı kestirdim.", "Arabamı yıkattım.", "Fotoğraf çektirdim.", "… diktirdim."], "models": ["Geçen hafta berberde saçımı kestirdim. Sonra arabamı yıkattım. Evde de bir tamirci çağırıp musluğu tamir ettirdim.", "Geçen hafta terziye bir elbise diktirdim. Ayrıca düğünde fotoğraf çektirdik."], "modelsN": ["Letzte Woche habe ich mir beim Friseur die Haare schneiden lassen. Danach habe ich mein Auto waschen lassen. Zu Hause habe ich einen Handwerker gerufen und den Wasserhahn reparieren lassen.", "Letzte Woche habe ich beim Schneider ein Kleid nähen lassen. Außerdem haben wir bei der Hochzeit Fotos machen lassen."], "e": "Das **Kausativ** zeigt: Jemand anderes tut es für dich (kestirmek, yıkatmak, diktirmek, çektirmek). Deine Antwort darf ganz anders sein."}
  ]
});

K.add("tr-b1-14", {
  lesson: [{"p": "Gute Texte, Mails und Gespräche verbinden Sätze mit **Konnektoren**. Im Türkischen stehen sie meist **am Satzanfang** und werden oft durch ein Komma abgesetzt. Sie ersetzen deutsche Wörter wie „jedoch“, „dabei“, „obendrein“, „außerdem“, „trotzdem“, „folglich“ und „kurz gesagt“."}, {"h": "Die Bausteine"}, {"table": {"head": ["Deutsch", "Türkisch", "Beispiel"], "rows": [["jedoch; erst, nur (+ Zeit)", "**ancak**", "Gelmek istiyorum. Ancak vaktim yok."], ["dabei; wo doch", "**oysa**", "Herkes öyle sandı. Oysa öyle değildi."], ["und obendrein", "**üstelik**", "Pahalı. Üstelik uzak."], ["außerdem, zusätzlich", "**ayrıca**", "Otel temiz. Ayrıca kahvaltı güzel."], ["trotzdem", "**yine de**", "Yorgundum. Yine de gittim."], ["folglich, daher", "**dolayısıyla**", "Tren iptal edildi. Dolayısıyla geç kaldık."], ["kurz gesagt", "**kısacası**", "Kısacası bu iş zor."]]}}, {"p": "**ancak** = „jedoch“ (Gegensatz, eher geschrieben): *İstiyorum, ancak yapamam.* Vor Zeit- oder Mengenangaben heißt *ancak* „erst, nur“: *Yarın ancak öğleden sonra gelebilirim.* **oysa** stellt eine Behauptung oder Erwartung **richtig**: *Biletlerin bittiğini sandık. Oysa hâlâ bilet vardı.* **yine de** heißt „trotzdem“ und folgt auf einen Gegengrund: *Hava soğuktu. Yine de çıktık.*"}, {"p": "**üstelik** und **ayrıca** fügen etwas hinzu. *Üstelik* verstärkt („und dazu noch, noch dazu“) und passt oft zu Überraschendem oder Negativem; *ayrıca* ist neutral („außerdem“). **dolayısıyla** nennt die Folge („daher, folglich“), meist in formellen Texten. **kısacası** fasst zusammen („kurz gesagt“)."}, {"warn": "Typische Fehler: *„Yine de“* als „außerdem“ verwenden (es heißt „trotzdem“), *„oysa“* als „daher“ (es ist ein Gegensatz) und *„dolayısıyla“* nach einem Gegensatz (es nennt immer eine Folge). Auch *„çokda“* statt *çok da* ist falsch: de/da werden getrennt geschrieben."}, {"tip": "Merke die drei Gruppen: **Gegensatz** (ancak, oysa, yine de), **Ergänzung** (üstelik, ayrıca), **Folge/Fazit** (dolayısıyla, kısacası). Mit dem richtigen Konnektor klingt dein Text gleich viel natürlicher."}, {"ex": [["Hava soğuktu. Yine de yürüyüşe çıktık.", "Es war kalt. Trotzdem gingen wir spazieren."], ["Otel pahalı, üstelik çok uzak.", "Das Hotel ist teuer, und obendrein sehr weit weg."], ["Herkes toplantının iptal edildiğini sandı. Oysa toplantı yapılacaktı.", "Alle dachten, die Besprechung sei abgesagt. Dabei sollte sie stattfinden."], ["Tren iptal edildi. Dolayısıyla otobüsle gittik.", "Der Zug fiel aus. Folglich fuhren wir mit dem Bus."], ["Kısacası bu iş hiç kolay değil.", "Kurz gesagt: Diese Arbeit ist gar nicht leicht."]]}],
  exercises: [
    {"id": "tr-b1-14.1", "t": "gap", "q": "Hava çok soğuktu. ___ yürüyüşe çıktık. (Trotzdem gingen wir spazieren.)", "a": ["Yine de"], "wrong": {"Dolayısıyla": "*dolayısıyla* = folglich; ein Spaziergang wegen der Kälte wäre unlogisch.", "Üstelik": "*üstelik* = und obendrein; es fügt hinzu, widerspricht aber nicht.", "Kısacası": "*kısacası* fasst zusammen, drückt aber keinen Gegensatz aus."}, "e": "*yine de* = trotzdem; es nimmt den Gegensatz zur Kälte auf."},
    {"id": "tr-b1-14.2", "t": "gap", "q": "Otel çok pahalı. ___ merkeze de uzak. (Außerdem liegt es weit vom Zentrum.)", "a": ["Ayrıca", "Üstelik"], "wrong": {"Oysa": "*oysa* = dabei; es stellt etwas richtig, fügt aber nichts hinzu.", "Ancak": "*ancak* = jedoch; hier wird nichts entgegengesetzt.", "Dolayısıyla": "*dolayısıyla* = folglich; „teuer“ ist nicht der Grund für „weit weg“."}, "e": "*ayrıca* und *üstelik* fügen einen weiteren Nachteil hinzu."},
    {"id": "tr-b1-14.3", "t": "gap", "q": "Herkes toplantının iptal edildiğini sanıyordu. ___ toplantı yapılacaktı. (Dabei sollte die Besprechung stattfinden.)", "a": ["Oysa", "Ancak", "Halbuki"], "wrong": {"Dolayısıyla": "*dolayısıyla* = folglich; es nennt eine Folge, keine Richtigstellung.", "Ayrıca": "*ayrıca* = außerdem; es fügt nur hinzu.", "Kısacası": "*kısacası* = kurz gesagt; es fasst zusammen."}, "e": "*oysa* stellt eine falsche Annahme richtig („dabei“). Auch *ancak* („jedoch“) und *halbuki* (wie *oysa*, etwas förmlicher) passen hier."},
    {"id": "tr-b1-14.4", "t": "gap", "q": "Tren iptal edildi. ___ biz otobüsle gitmek zorunda kaldık. (Folglich mussten wir mit dem Bus fahren.)", "a": ["Dolayısıyla", "Bu yüzden"], "wrong": {"Oysa": "*oysa* = dabei; hier ist keine Richtigstellung gemeint.", "Yine de": "*yine de* = trotzdem; die Busfahrt ist aber die Folge der Absage.", "Üstelik": "*üstelik* = obendrein; es nennt keine Folge."}, "e": "*dolayısıyla* oder *bu yüzden* = folglich; die Absage ist der Grund der Busfahrt."},
    {"id": "tr-b1-14.5", "t": "gap", "q": "Konferansta üç konuşma vardı, iki atölye çalışması yapıldı ve akşam yemeği verildi. ___ çok verimli bir gündü.", "a": ["Kısacası"], "wrong": {"Ancak": "*ancak* = jedoch; es stellt einen Gegensatz her.", "Oysa": "*oysa* = dabei; es stellt eine Annahme richtig.", "Yine de": "*yine de* = trotzdem; es nimmt einen Gegengrund auf."}, "e": "*kısacası* = kurz gesagt; es fasst alles zusammen."},
    {"id": "tr-b1-14.6", "t": "gap", "q": "Sınavı geçmek istiyorum. ___ yeterince çalışamadım. (Jedoch habe ich nicht genug lernen können.)", "a": ["Ancak"], "wrong": {"Dolayısıyla": "*dolayısıyla* = folglich; es nennt eine Folge, nicht einen Gegensatz.", "Ayrıca": "*ayrıca* = außerdem; es fügt hinzu.", "Kısacası": "*kısacası* = kurz gesagt; es fasst zusammen."}, "e": "*ancak* = jedoch; es stellt dem Wunsch eine Einschränkung gegenüber."},
    {"id": "tr-b1-14.7", "t": "mc", "q": "„Es ist teuer, und obendrein ist es schlecht.“", "o": ["Pahalı, üstelik kalitesiz.", "Pahalı, oysa kalitesiz.", "Pahalı, dolayısıyla kalitesiz.", "Pahalı, yine de kalitesiz."], "a": 0, "why": {"1": "*oysa* = dabei; es stellt etwas richtig.", "2": "*dolayısıyla* = folglich; „teuer“ ist nicht der Grund für schlechte Qualität.", "3": "*yine de* = trotzdem; das passt hier nicht."}, "e": "*üstelik* = und obendrein; es fügt einen weiteren Nachteil hinzu."},
    {"id": "tr-b1-14.8", "t": "mc", "q": "Welches Wort drückt eine Folge aus?", "o": ["dolayısıyla", "oysa", "üstelik", "yine de"], "a": 0, "why": {"1": "*oysa* = dabei (Gegensatz).", "2": "*üstelik* = obendrein (Ergänzung).", "3": "*yine de* = trotzdem (Gegengrund)."}, "e": "*dolayısıyla* = folglich, daher."},
    {"id": "tr-b1-14.9", "t": "mc", "q": "„Er ist krank. Trotzdem arbeitet er.“", "o": ["Hasta. Yine de çalışıyor.", "Hasta. Dolayısıyla çalışıyor.", "Hasta. Kısacası çalışıyor.", "Hasta. Ayrıca çalışıyor."], "a": 0, "why": {"1": "*dolayısıyla* = folglich; Krankheit ist nicht der Grund zum Arbeiten.", "2": "*kısacası* = kurz gesagt; es drückt keinen Gegensatz aus.", "3": "*ayrıca* = außerdem; es fügt etwas Neues hinzu."}, "e": "*yine de* = trotzdem."},
    {"id": "tr-b1-14.10", "t": "mc", "q": "„Man dachte, das Konzert sei ausverkauft. Dabei gab es noch Karten.“", "o": ["Oysa hâlâ bilet vardı.", "Dolayısıyla hâlâ bilet vardı.", "Ayrıca hâlâ bilet vardı.", "Kısacası hâlâ bilet vardı."], "a": 0, "why": {"1": "*dolayısıyla* = folglich; die Karten sind keine Folge der Annahme.", "2": "*ayrıca* = außerdem; es fügt hinzu, widerspricht aber nicht.", "3": "*kısacası* = kurz gesagt; es fasst zusammen."}, "e": "*oysa* stellt die falsche Annahme richtig („dabei“)."},
    {"id": "tr-b1-14.11", "t": "mc", "q": "Was bedeutet *ancak* in „Yarın ancak öğleden sonra gelebilirim“?", "o": ["erst, nur", "jedoch", "trotzdem", "kurz gesagt"], "a": 0, "why": {"1": "„Jedoch“ steht am Satzanfang als Konnektor; hier bezieht sich *ancak* auf *öğleden sonra*.", "2": "„Trotzdem“ ist *yine de*.", "3": "„Kurz gesagt“ ist *kısacası*."}, "e": "Vor Zeitangaben heißt *ancak* „erst, nur“: Ich kann erst nachmittags kommen."},
    {"id": "tr-b1-14.12", "t": "mc", "q": "„Ich bin müde; außerdem ist es spät.“", "o": ["Yorgunum; ayrıca geç oldu.", "Yorgunum; oysa geç oldu.", "Yorgunum; yine de geç oldu.", "Yorgunum; kısacası geç oldu."], "a": 0, "why": {"1": "*oysa* = dabei; es würde etwas richtigstellen.", "2": "*yine de* = trotzdem; hier gibt es keinen Gegensatz.", "3": "*kısacası* fasst zusammen; es folgt hier aber kein Fazit."}, "e": "*ayrıca* = außerdem; es fügt einen zweiten Grund hinzu."},
    {"id": "tr-b1-14.13", "t": "order", "q": "Bilde den Satz: „Ich war müde, trotzdem ging ich zur Arbeit.“", "w": ["Yorgundum", "yine", "de", "işe", "gittim"], "a": ["Yorgundum yine de işe gittim"], "e": "*yine de* steht vor dem zweiten Satz; es nimmt den Gegengrund auf."},
    {"id": "tr-b1-14.14", "t": "order", "q": "Bilde den Satz: „Das Hotel ist teuer, außerdem liegt es sehr weit weg.“", "w": ["Otel", "pahalı", "ayrıca", "çok", "uzakta"], "a": ["Otel pahalı ayrıca çok uzakta"], "e": "*ayrıca* leitet den zweiten Gedanken ein."},
    {"id": "tr-b1-14.15", "t": "order", "q": "Bilde den Satz: „Das Wetter war schlecht, folglich fiel das Fest aus.“", "w": ["Hava", "kötüydü", "dolayısıyla", "şenlik", "iptal", "edildi"], "a": ["Hava kötüydü dolayısıyla şenlik iptal edildi"], "e": "*dolayısıyla* nennt die Folge der schlechten Wetterlage."},
    {"id": "tr-b1-14.16", "t": "match", "q": "Ordne die Form der Bedeutung zu:", "p": [["ancak", "jedoch; erst, nur"], ["oysa", "dabei; wo doch"], ["üstelik", "und obendrein"], ["ayrıca", "außerdem"], ["yine de", "trotzdem"]], "e": "Gegensatz: ancak, oysa, yine de. Ergänzung: üstelik, ayrıca."},
    {"id": "tr-b1-14.17", "t": "cloze", "q": "Setze den passenden Konnektor ein.", "text": "Hava soğuktu. {1} yürüyüşe çıktık. Otel pahalı. {2} çok uzak. Tren iptal edildi; {3} otobüsle gittik.", "gaps": {"1": {"a": ["Yine de"], "wrong": {"Dolayısıyla": "*dolayısıyla* = folglich; hier steht ein Gegensatz.", "Üstelik": "*üstelik* fügt nur hinzu."}}, "2": {"a": ["Üstelik", "Ayrıca"], "wrong": {"Oysa": "*oysa* stellt eine Annahme richtig.", "Ancak": "*ancak* stellt einen Gegensatz her."}}, "3": {"a": ["dolayısıyla", "bu yüzden"], "wrong": {"oysa": "*oysa* = dabei; es nennt keine Folge.", "yine de": "*yine de* = trotzdem; hier steht eine Folge."}}}, "e": "yine de = Gegensatz; üstelik/ayrıca = Ergänzung; dolayısıyla = Folge."},
    {"id": "tr-b1-14.18", "t": "sort", "q": "Gegensatz, Ergänzung oder Folge? Ordne die Sätze zu.", "cats": ["Gegensatz (jedoch, dabei, trotzdem)", "Ergänzung / Folge / Fazit (außerdem, folglich, kurz gesagt)"], "items": [["Yağmur yağıyordu. Yine de çıktık.", 0], ["Pahalı. Üstelik uzak.", 1], ["Herkes öyle sandı. Oysa öyle değildi.", 0], ["Tren iptal edildi. Dolayısıyla otobüsle gittik.", 1], ["Gelmek istiyorum. Ancak vaktim yok.", 0], ["Kısacası bu iş bitti.", 1]], "why": {"Yağmur yağıyordu. Yine de çıktık.": "*yine de* = trotzdem: Gegensatz zum Regen.", "Pahalı. Üstelik uzak.": "*üstelik* = obendrein: ein zweiter Nachteil.", "Herkes öyle sandı. Oysa öyle değildi.": "*oysa* = dabei: die Annahme war falsch.", "Tren iptal edildi. Dolayısıyla otobüsle gittik.": "*dolayısıyla* = folglich: Folge der Absage.", "Gelmek istiyorum. Ancak vaktim yok.": "*ancak* = jedoch: Einschränkung des Wunsches.", "Kısacası bu iş bitti.": "*kısacası* = kurz gesagt: Fazit."}, "e": "Konnektoren zeigen, wie zwei Sätze zusammenhängen: Widerspruch, Zusatz oder Folge."},
    {"id": "tr-b1-14.19", "t": "listen", "say": "Yorgundum, yine de işe gittim.", "q": "Hör zu: Was sagt die Person?", "o": ["Sie war müde und ging trotzdem zur Arbeit.", "Sie war müde und blieb zu Hause.", "Sie war müde, deshalb ging sie zur Arbeit.", "Sie war nicht müde."], "a": 0, "why": {"1": "*gittim* = ich ging, nicht „blieb“.", "2": "*yine de* = trotzdem, nicht „deshalb“ (dolayısıyla).", "3": "*yorgundum* = ich war müde."}, "e": "„Ich war müde, trotzdem ging ich zur Arbeit.“ *yine de* = trotzdem."},
    {"id": "tr-b1-14.20", "t": "dictation", "say": "Otel pahalı, üstelik çok da uzak.", "a": ["Otel pahalı, üstelik çok da uzak."], "wrong": {"Otel pahalı, üstelik çokda uzak.": "Die Partikel *de/da* („auch“) wird getrennt geschrieben: *çok da*.", "Otel pahalı, ayrıca çok da uzak.": "Gehört wurde *üstelik*, nicht *ayrıca*.", "Otel pahalı, üstelik çok da uzaktı.": "Der Satz steht im Präsens: *uzak* (nicht *uzaktı*)."}, "e": "„Das Hotel ist teuer, und obendrein auch noch sehr weit weg.“ *üstelik* = obendrein."},
    {"id": "tr-b1-14.21", "t": "speak", "say": "Hava soğuktu, yine de yürüyüşe çıktık.", "e": "„Es war kalt, trotzdem gingen wir spazieren.“ *yine*: y wie „j“, Betonung auf yi-NE. *yürüyüşe*: ü gerundet, ş = „sch“. Typischer Fehler: *yine de* zusammenziehen zu *yinede*."},
    {"id": "tr-b1-14.22", "t": "speak", "say": "Otel pahalı, üstelik çok uzak.", "e": "„Das Hotel ist teuer, und obendrein sehr weit weg.“ *üstelik*: ü gerundet wie in „Brücke“, s stimmlos, e kurz. Typischer Fehler: *üstelik* mit stimmhaftem s („üzstelik“)."},
    {"id": "tr-b1-14.23", "t": "speak", "say": "Kısacası bu iş çok kolay değil.", "e": "„Kurz gesagt, diese Arbeit ist nicht leicht.“ *kısacası*: ı dumpf, c wie „dsch“ (kı-sa-ca-sı). *değil*: ğ nach e wie leichtes j: de-yil. Typischer Fehler: *kısacası* mit „tsch“ statt „dsch“."},
    {"id": "tr-b1-14.24", "t": "respond", "say": "Yeni bir dil öğrenmek sence zor mu?", "q": "Hör dir die Frage an und antworte laut in 2–3 Sätzen. Benutze mindestens drei Konnektoren (ancak, üstelik, yine de, kısacası …).", "chunks": ["Ancak …", "Üstelik …", "Yine de …", "Kısacası …"], "models": ["Evet, biraz zor. Üstelik her gün çalışmak gerekiyor. Yine de çok eğlenceli. Kısacası zor ama sabırla mutlaka öğrenilir.", "Bence zor değil. Ancak düzenli çalışmak lazım. Ayrıca konuşmaktan korkmamak da önemli. Kısacası sabırlı olmak yeter."], "modelsN": ["Ja, ein bisschen. Obendrein muss man jeden Tag üben. Trotzdem macht es viel Spaß. Kurz gesagt: Es ist schwer, aber mit Geduld lernt man es auf jeden Fall.", "Meiner Meinung nach ist es nicht schwer. Jedoch muss man regelmäßig lernen. Außerdem ist es wichtig, keine Angst vorm Sprechen zu haben. Kurz gesagt: Geduld genügt."], "e": "Mit **ancak** (Einschränkung), **üstelik/ayrıca** (Zusatz), **yine de** (Gegengrund) und **kısacası** (Fazit) baust du einen Text. Deine Antwort darf ganz anders sein."}
  ]
});

})(window.KOPRU);
